local notifHolder = new("Frame", {
	Name = "Notifications",
	AnchorPoint = Vector2.new(1, 1),
	Position = UDim2.new(1, -18, 1, -18),
	Size = UDim2.new(0, 300, 1, -36),
	BackgroundTransparency = 1,
	ZIndex = 5,
	Parent = gui,
