-- Infinite jump: game dibuat mengira ada Antigravity Generator, jadi bisa lompat di udara
local OrigJammerOn = nil
local function infJumpWrapper(id, ...)
    -- dimatikan saat Clear / Pabrik jalan (lompat harus normal)
    if Misc.InfJump and id == 4992 and not AutoInput.active then
        return true
    end
    if OrigJammerOn then return OrigJammerOn(id, ...) end
    return false
end

local function hookJammer()
    local w = Refs.World
    if not w then return end
    local cur = rawget(w, "jammerOn")
    if cur == infJumpWrapper or type(cur) ~= "function" then return end
    OrigJammerOn = cur
    w.jammerOn = infJumpWrapper
end

local function unhookJammer()
    local w = Refs.World
    if w and rawget(w, "jammerOn") == infJumpWrapper and OrigJammerOn then
        w.jammerOn = OrigJammerOn
    end
end

local function setInfJump(on)
    Misc.InfJump = on
    if on then hookJammer() else unhookJammer() end
end

local function setGhost(on)
    Misc.Ghost = on
    if not on then
        Misc.UpHeld, Misc.DownHeld = false, false
        if Refs.World then Refs.World.ghost = false end
    end
    if UI.FlyPad then UI.FlyPad.Enabled = on end
end

local function setSpeed(pct)
    Misc.Speed = math.clamp(math.floor(tonumber(pct) or 100), 50, 500)
    if Misc.Speed == 100 and Refs.World then Refs.World.speedScale = 1 end
end

-- Tombol gerak game dibaca dari WorldMenu.isDown. Dibungkus supaya
-- tombol Fly bisa dipakai, dan Clear / Pabrik bisa "menekan" tombol sendiri.
local OrigIsDown = nil
Session.MovementProbe = Session.MovementProbe or {}
local function isDownWrapper(saved, key, ...)
    -- WorldMenu pada sebagian build dipanggil dengan dot (isDown("keyLeft")),
    -- sementara build lain memakai colon (isDown(self, "keyLeft")).
    local actualKey = key
    if actualKey == nil and type(saved) == "string" then
        actualKey = saved
    end

    -- Terima juga Enum.KeyCode bila client mengubah representasi tombol.
    if actualKey == Enum.KeyCode.Left then actualKey = "keyLeft"
    elseif actualKey == Enum.KeyCode.Right then actualKey = "keyRight"
    elseif actualKey == Enum.KeyCode.Space then actualKey = "keyJump"
    elseif actualKey == Enum.KeyCode.Down then actualKey = "keyDown" end

    if AutoInput.active then
        local probeKey = tostring(actualKey)
        if not Session.MovementProbe[probeKey] then
            Session.MovementProbe[probeKey] = true
            print("[ByteHub] Movement input diterima: " .. probeKey)
        end
        if actualKey == "keyLeft" then return AutoInput.left end
        if actualKey == "keyRight" then return AutoInput.right end
        if actualKey == "keyJump" then return AutoInput.jump end
        if actualKey == "keyDown" then return AutoInput.down end
    end

    if Misc.Ghost then
        if actualKey == "keyDown" and Misc.DownHeld then return true end
        if actualKey == "keyJump" and Misc.UpHeld then return true end
    end

    -- Pertahankan bentuk argumen asli ketika meneruskan ke fungsi game.
    if key == nil and type(saved) == "string" then
        return OrigIsDown(saved, ...)
    end
    return OrigIsDown(saved, key, ...)
end

-- Auto PnB fallback: gunakan adapter tombol executor yang sama dengan Auto Plant.
-- Ini memungkinkan PnB bergerak walau WorldMenu.isDown tidak diekspos Delta.
local PnbDirectInput = {
    held = {},
    warned = false,
    modeLogged = false,
}

local function pnbDirectInputAvailable()
    local runtime = executorEnv.__ByteHubAutoPlantRuntime
    return type(runtime) == "table"
        and type(runtime.setKey) == "function"
        and type(runtime.keyMap) == "table"
end

local function pnbSetDirectKey(name, isDown)
    local runtime = executorEnv.__ByteHubAutoPlantRuntime
    if type(runtime) ~= "table" or type(runtime.setKey) ~= "function" then
        return false
    end
    local ok, result = pcall(runtime.setKey, name, isDown)
    return ok and result == true
end

local function pnbReleaseDirectInput()
    for name in pairs(PnbDirectInput.held) do
        pnbSetDirectKey(name, false)
        PnbDirectInput.held[name] = nil
    end
end

local function pnbSyncDirectInput()
    -- Jika hook game tersedia, gunakan hook biasa dan jangan kirim input ganda.
    if type(OrigIsDown) == "function" or not AutoInput.active then
        pnbReleaseDirectInput()
        return
    end

    if not pnbDirectInputAvailable() then
        if not PnbDirectInput.warned then
            PnbDirectInput.warned = true
            warn("[ByteHub] Auto PnB: adapter input langsung executor tidak tersedia.")
        end
        return
    end

    if not PnbDirectInput.modeLogged then
        PnbDirectInput.modeLogged = true
        print("[ByteHub] Auto PnB menggunakan fallback input executor.")
    end

    -- Auto Plant telah mengalibrasi keyMap ini (Arrow/WASD/Space-S).
    -- Gunakan map yang sama agar PnB mengikuti kontrol yang terbukti bekerja.
    local desired = {
        Left = AutoInput.left == true,
        Right = AutoInput.right == true,
        Up = AutoInput.jump == true,
        Down = AutoInput.down == true,
    }

    for _, name in ipairs({ "Left", "Right", "Up", "Down" }) do
        if desired[name] and not PnbDirectInput.held[name] then
            if pnbSetDirectKey(name, true) then
                PnbDirectInput.held[name] = true
            elseif not PnbDirectInput.warned then
                PnbDirectInput.warned = true
                warn("[ByteHub] Auto PnB: executor menolak input tombol " .. name .. ".")
            end
        elseif not desired[name] and PnbDirectInput.held[name] then
            pnbSetDirectKey(name, false)
            PnbDirectInput.held[name] = nil
        end
    end
end

local function pnbMovementAvailable()
    return type(OrigIsDown) == "function" or pnbDirectInputAvailable()
end

function Session.bindMovementMenu()
    if type(MenuModule) ~= "table" or not Session.isMovementMenu(MenuModule) then
        Session.MovementInputReady = false
        return false
    end

    local current = rawget(MenuModule, "isDown")
    if type(current) ~= "function" then return false end
    if current == isDownWrapper then
        return type(OrigIsDown) == "function"
    end

    OrigIsDown = current
    local assigned = pcall(rawset, MenuModule, "isDown", isDownWrapper)
    if assigned and rawget(MenuModule, "isDown") == isDownWrapper then
        Session.MovementMenu = MenuModule
        Session.MovementInputReady = true
        return true
    end

    -- Fallback hanya jika tabel module tidak dapat ditulis oleh executor.
    if type(hookfunction) == "function" then
        local hooked, original = pcall(hookfunction, current, isDownWrapper)
        if hooked and type(original) == "function" then
            OrigIsDown = original
            Session.MovementMenu = MenuModule
            Session.MovementInputReady = true
            return true
        end
    end

    OrigIsDown = nil
    Session.MovementInputReady = false
    return false
end

pcall(Session.bindMovementMenu)

-- WorldMenu bisa tersedia setelah UI selesai dibuat. Retry dibatasi dan berjalan
-- di background agar tidak menahan UI atau melakukan scan setiap frame.
task.spawn(function()
    local attempts = 0
    while alive() and not OrigIsDown and attempts < 10 do
        attempts += 1

        local found = false
        if type(Session.resolveMovementMenu) == "function" then
            local ok, result = pcall(Session.resolveMovementMenu)
            found = ok and result == true
            if not ok then
                Session.ModuleScan.MovementError = tostring(result):sub(1, 180)
            end
        end

        if found and Session.bindMovementMenu() then
            print("[ByteHub] WorldMenu source: "
                .. tostring(Session.ModuleScan.MovementSource or Session.Modules.WorldMenu or "unknown"))
            print("[ByteHub] Kontrol gerak WorldMenu berhasil dihubungkan.")
            return
        end

        task.wait(1.5)
    end

    if alive() and not OrigIsDown then
        local detail = Session.ModuleScan and Session.ModuleScan.MovementError
        warn("[ByteHub] Kontrol gerak belum tersedia: WorldMenu.isDown."
            .. (detail and (" Detail: " .. tostring(detail)) or ""))
    end
end)

-- Pasang walkspeed & fly tiap frame (game bisa menimpanya)
table.insert(Connections, RunService.Heartbeat:Connect(function()
    pnbSyncDirectInput()
    local w = Refs.World
    if not w or not alive() then return end
    -- AutoInput.speed diisi Auto Plant selama berjalan (di-nil-kan saat selesai).
    -- Kalau diisi, speed itulah yang dipakai PERSIS (bukan "yang terbesar"), supaya
    -- Auto Plant tetap normal walau slider Kecepatan Auto Farm dinaikkan.
    local speed = Misc.Speed
    if AutoInput.speed and AutoInput.speed > 0 then speed = AutoInput.speed end
    if speed == 100 then
        if w.speedScale ~= 1 then w.speedScale = 1 end
    else
        w.speedScale = speed / 100
    end
    if Misc.Ghost and w.ghost ~= true then w.ghost = true end
end))

