--// --- AUTO HARVEST (mesin sendiri: panen saja, seluruh world, pola snake) ---
-- Tidak memakai FC/fieldScan supaya tidak mengganggu Pabrik / Bangun Lahan.
do (function() -- fungsi sendiri: variabel di dalam tidak ikut batas 200 local
local Hvs = Harvest
local HvsFail = {}

local function hvsLive()
    return alive() and Hvs.Running and Hvs.On
end

-- Referensi waktu tanam kadang belum dapat ditemukan pada frame pertama world
-- selesai dimuat. Tabel kosong juga tidak cukup: pastikan setidaknya satu tile
-- seed di world memiliki timestamp sebelum Auto Harvest mulai memilih target.
local function hvsTreeRefsReady(w)
    if not w then return false end
    local now = os.clock()
    if Hvs.TreeRefCheckWorld == w and now < (Hvs.TreeRefCheckAt or 0) then
        return Hvs.TreeRefCheckResult == true
    end

    local seedCount, timestampCount = 0, 0
    for y = 0, w.h - 1 do
        local row = w.fg[y]
        if row then
            for x = 0, w.w - 1 do
                local id = row[x] or 0
                local item = id ~= 0 and ItemDB[id]
                if item and item.kind == "seed" then
                    seedCount += 1
                    if Refs.Trees then
                        local entry = Auto.treeEntry(x, y)
                        if type(entry) == "table" and type(entry.p) == "number" then
                            timestampCount += 1
                        end
                    end
                end
            end
        end
    end

    -- World tanpa seed belum membutuhkan tabel waktu tanam. Jika ada seed,
    -- setidaknya satu timestamp harus terbaca agar scan tidak diam-diam kosong.
    Hvs.TreeRefSeedCount = seedCount
    Hvs.TreeRefTimestampCount = timestampCount
    Hvs.TreeRefMissingCount = math.max(0, seedCount - timestampCount)
    local ready = seedCount == 0 or timestampCount > 0
    Hvs.TreeRefCheckWorld = w
    Hvs.TreeRefCheckAt = now + 2
    Hvs.TreeRefCheckResult = ready
    return ready
end

-- Auto Harvest fallback: cari tabel timestamp pohon langsung dari heap game.
-- Jalur lama hanya menelusuri upvalue World/remote/RunService; pada beberapa
-- build, tabel pohon tidak lagi terhubung ke root tersebut.
local hvsHeapScanWorld = nil
local hvsHeapScanAt = 0

local function hvsTimestampField(entry, serverNow)
    local function validTime(value)
        return type(value) == "number"
            and value >= serverNow - (86400 * 365 * 10)
            and value <= serverNow + 86400
    end

    if type(entry) == "number" then
        return validTime(entry) and "p" or nil
    end
    if type(entry) ~= "table" then
        return nil
    end

    local plantedAt = rawget(entry, "p")
    if validTime(plantedAt) then
        return "p"
    end
    for key, value in pairs(entry) do
        if validTime(value) then
            return key
        end
    end
    return nil
end

local function hvsProbeTreeTable(candidate, w, seedTiles, serverNow)
    if type(candidate) ~= "table" or candidate == w
        or getmetatable(candidate) ~= nil or rawget(candidate, "fg") ~= nil then
        return nil
    end

    -- Utamakan layout yang sudah dikenal oleh Auto.treeEntry.
    for _, mode in ipairs({ "idx", "rows", "xy" }) do
        for _, tile in ipairs(seedTiles) do
            local entry
            if mode == "idx" then
                entry = rawget(candidate, tile.y * w.w + tile.x)
            elseif mode == "rows" then
                local row = rawget(candidate, tile.y)
                entry = type(row) == "table" and rawget(row, tile.x) or nil
            else
                entry = rawget(candidate, tile.x .. "," .. tile.y)
            end

            local field = hvsTimestampField(entry, serverNow)
            if field then
                return mode, field
            end
        end
    end
    return nil
end

local function hvsFindTreesInHeap(w)
    if not w or type(getgc) ~= "function" then
        return false
    end
    if hvsHeapScanWorld == w and os.clock() < hvsHeapScanAt then
        return false
    end
    hvsHeapScanWorld = w
    hvsHeapScanAt = os.clock() + 5

    local seedTiles = {}
    for y = 0, w.h - 1 do
        local row = w.fg[y]
        if row then
            for x = 0, w.w - 1 do
                local id = row[x] or 0
                local item = id ~= 0 and ItemDB[id]
                if item and item.kind == "seed" then
                    seedTiles[#seedTiles + 1] = { x = x, y = y }
                end
            end
        end
    end
    if #seedTiles == 0 then
        return false
    end

    local ok, objects = pcall(getgc, true)
    if not ok or type(objects) ~= "table" then
        ok, objects = pcall(getgc)
    end
    if not ok or type(objects) ~= "table" then
        return false
    end

    local serverNowOk, serverNow = pcall(function()
        return workspace:GetServerTimeNow()
    end)
    if not serverNowOk or type(serverNow) ~= "number" then
        serverNow = os.time()
    end

    local bestCandidate, bestMode, bestField, bestCount = nil, nil, nil, 0
    for _, candidate in pairs(objects) do
        if type(candidate) == "table" and candidate ~= w then
            local firstKey, firstValue = next(candidate)
            local possibleKey = type(firstKey) == "number"
                and firstKey % 1 == 0 and firstKey >= 0 and firstKey < (w.w * w.h)
                and (type(firstValue) == "table" or type(firstValue) == "number")
            if type(firstKey) == "string" then
                local x, y = string.match(firstKey, "^(%d+),(%d+)$")
                possibleKey = x ~= nil and y ~= nil
                    and (type(firstValue) == "table" or type(firstValue) == "number")
            end

            if possibleKey then
                local mode, field
                local okShape, knownMode, knownField = pcall(Auto.treeShape, candidate)
                if okShape and knownMode then
                    mode, field = knownMode, knownField
                else
                    local okProbe, probeMode, probeField = pcall(
                        hvsProbeTreeTable, candidate, w, seedTiles, serverNow
                    )
                    if okProbe then
                        mode, field = probeMode, probeField
                    end
                end

                if mode then
                    Refs.Trees, Refs.TreeMode, Refs.TreeP = candidate, mode, field
                    Hvs.TreeRefCheckAt = 0
                    Hvs.TreeRefCheckWorld = nil
                    if hvsTreeRefsReady(w) then
                        local count = Hvs.TreeRefTimestampCount or 0
                        if count > bestCount then
                            bestCandidate, bestMode, bestField, bestCount = candidate, mode, field, count
                        end
                        if bestCount >= #seedTiles then
                            break
                        end
                    end
                end
            end
        end
    end
    if bestCandidate then
        Refs.Trees, Refs.TreeMode, Refs.TreeP = bestCandidate, bestMode, bestField
        Hvs.TreeRefCheckAt = 0
        Hvs.TreeRefCheckWorld = nil
        if hvsTreeRefsReady(w) then
            Hvs.TreeRefSource = "getgc"
            return true
        end
    end
    Refs.Trees, Refs.TreeMode, Refs.TreeP = nil, nil, nil
    Hvs.TreeRefCheckAt = 0
    Hvs.TreeRefCheckWorld = nil
    return false
end

-- Jangan mensyaratkan pemain memukul satu pohon secara manual. Jika discovery
-- awal hanya mengembalikan tabel kosong/tidak cocok, paksa pencarian deep yang
-- memvalidasi bentuk data terhadap tile seed yang benar-benar ada di world.
local function hvsRetryTreeRefs(runId, forceRetry)
    local w = Refs.World
    if not forceRetry and hvsTreeRefsReady(w) then return true end
    if Hvs.TreeRefSearching or os.clock() < (Hvs.TreeRefRetryAt or 0) then
        return false
    end

    Hvs.TreeRefSearching = true
    Hvs.TreeRefAttempts = (Hvs.TreeRefAttempts or 0) + 1
    local attempt = Hvs.TreeRefAttempts
    local worldAtStart = w
    local forceDeep = Hvs.TreeRefForceDeep or Refs.Trees ~= nil
    Hvs.TreeRefRetryAt = os.clock() + math.min(12, 2 + attempt * 2)
    Hvs.Status = ("Mencari data waktu tanam pohon (percobaan %d)..."):format(attempt)

    task.spawn(function()
        local ok, found
        if forceDeep then
            Refs.Trees, Refs.TreeMode, Refs.TreeP = nil, nil, nil
            ok, found = pcall(function()
                return Auto.findTreesDeep and Auto.findTreesDeep() or false
            end)
        else
            ok, found = pcall(findTreeRefs)
        end

        -- Jika pencarian melalui World/remote/upvalue belum menemukan data,
        -- lakukan fallback khusus Auto Harvest ke tabel live di getgc().
        if Refs.World == worldAtStart and not hvsTreeRefsReady(worldAtStart) then
            local heapOk, heapFound = pcall(hvsFindTreesInHeap, worldAtStart)
            if heapOk and heapFound then
                ok, found = true, true
                warn("[ByteHub] Auto Harvest: tree timestamp table ditemukan melalui heap scan.")
            elseif not heapOk then
                warn("[ByteHub] Auto Harvest heap scan gagal: " .. tostring(heapFound))
            end
        end

        Hvs.TreeRefSearching = false
        Hvs.TreeRefCheckAt = 0
        Hvs.TreeRefCheckWorld = nil

        -- Discovery boleh selesai setelah worker dihentikan. Referensi yang
        -- berhasil ditemukan tetap berguna, tetapi jangan mengubah status sesi lama.
        if not hvsLive() or Hvs.RunId ~= runId then return end
        if Refs.World ~= worldAtStart then
            Hvs.TreeRefRetryAt = os.clock() + 1
            Hvs.ScanAt = 0
            Hvs.Status = "World berubah; mencari ulang data pohon..."
            return
        end

        if ok and found and hvsTreeRefsReady(worldAtStart) then
            local missingTimestamps = Hvs.TreeRefMissingCount or 0
            Hvs.TreeRefAttempts = 0
            Hvs.TreeRefForceDeep = missingTimestamps > 0
            -- Jika tabel baru terbaca sebagian, coba discovery ulang dengan jeda.
            Hvs.TreeRefRetryAt = missingTimestamps > 0 and (os.clock() + 10) or 0
            Hvs.ScanAt = 0
            Hvs.Status = missingTimestamps > 0
                and ("Data waktu tanam terbaca sebagian (%d/%d); mencoba discovery ulang...")
                    :format(Hvs.TreeRefTimestampCount or 0, Hvs.TreeRefSeedCount or 0)
                or "Data waktu tanam ditemukan; memindai pohon..."
        else
            Hvs.TreeRefForceDeep = forceDeep or (Refs.Trees ~= nil)
            if Refs.Trees and not hvsTreeRefsReady(worldAtStart) then
                Refs.Trees, Refs.TreeMode, Refs.TreeP = nil, nil, nil
                Hvs.TreeRefForceDeep = true
            end
            Hvs.Status = ("Timestamp pohon terbaca %d/%d; mencoba ulang (%d)...")
                :format(Hvs.TreeRefTimestampCount or 0, Hvs.TreeRefSeedCount or 0, attempt)
        end
    end)
    return false
end

-- Pickup fisik game (badan menyentuh drop) memanggil World.takeDrop. Fungsi itu
-- di-hook selama jendela proteksi Auto Drop supaya block hasil drop tidak terambil
-- balik saat avatar lewat. Setelah jendela habis, panggilan diteruskan seperti biasa.
local function hvsPickupBlocked()
    return os.clock() < (Hvs.PickupUntil or 0)
end
executorEnv.__hvsPickupBlock = hvsPickupBlocked

local function hvsHookPickup()
    local w = Refs.World
    local cur = w and rawget(w, "takeDrop")
    if type(cur) ~= "function" then return false end
    if Hvs.PickupFn == cur then return true end
    local store = executorEnv.__hvsPickupStore
    if type(store) ~= "table" then
        store = { orig = {} }
        executorEnv.__hvsPickupStore = store
    end
    if store.orig[cur] then -- sudah di-hook dari sesi sebelumnya
        Hvs.PickupFn = cur
        return true
    end
    if type(hookfunction) ~= "function" then
        if not Hvs.PickupHookWarned then
            Hvs.PickupHookWarned = true
            warn("[ByteHub] hookfunction tidak tersedia: pickup fisik hasil Auto Drop tidak bisa diblokir")
        end
        return false
    end
    local backdoor
    local function wrapper(...) -- fungsi yang dilihat game
        local guard = executorEnv.__hvsPickupBlock
        if type(guard) == "function" and guard() then return 0 end
        return backdoor(...)
    end
    local ok, res = pcall(hookfunction, cur, wrapper)
    if not ok or type(res) ~= "function" then
        if not Hvs.PickupHookWarned then
            Hvs.PickupHookWarned = true
            warn("[ByteHub] hook takeDrop gagal: " .. tostring(res))
        end
        return false
    end
    backdoor = res
    store.orig[cur] = backdoor
    Hvs.PickupFn = cur
    return true
end

-- Tandai semua drop yang berada di dekat tile drop sebagai milik Auto Drop.
-- `untilT` = batas proteksi (2 dtk sejak momen block dibuang). Setelah batas itu
-- Harvest.dropBlocked() melepas uid sehingga semua jalur collect boleh memungutnya.
local function hvsMarkDropped(x, y, untilT)
    untilT = tonumber(untilT) or (os.clock() + Hvs.DropGuardSec)
    local marked, live = 0, {}
    for _, d in pairs(Drops.list or {}) do
        if type(d) == "table" and d.uid ~= nil then
            live[d.uid] = true
            if (d.n or 0) > 0 and type(d.x) == "number" and type(d.y) == "number"
                and math.abs(d.x - (x + 0.5)) <= 2.5 and math.abs(d.y - (y + 0.5)) <= 2.5 then
                Harvest.DropBlock[d.uid] = math.max(Harvest.DropBlock[d.uid] or 0, untilT)
                marked += 1
            end
        end
    end
    -- buang uid yang dropnya sudah hilang supaya tabel tidak tumbuh terus
    for uid in pairs(Harvest.DropBlock) do
        if not live[uid] and Drops.list then Harvest.DropBlock[uid] = nil end
    end
    return marked
end

-- Urutan snake wajib. Baris panen diurutkan dulu (rank 1..n), lalu arah kolom
-- bergantian tiap baris: baris ke-1 kiri->kanan, baris ke-2 kanan->kiri, dst.
-- Memakai indeks baris PANEN, bukan nilai Y mentah: baris tanaman dipisah 1
-- baris kosong, jadi paritas Y tidak pernah berubah dan pola snake tidak muncul.
-- Baris panen = baris yang punya pohon ATAU baris kosong tepat di atas pijakan
-- block (baris tanam yang pohonnya belum tumbuh). Peta disimpan stabil per world
-- supaya paritas arah tidak bergeser saat baris habis dipanen.
local function hvsSolidBlockAt(y)
    local w = Refs.World
    local row = w and w.fg[y]
    if not row then return false end
    for x = 0, w.w - 1 do
        local id = row[x]
        if id and id ~= 0 then
            local it = ItemDB[id]
            if it and it.kind ~= "seed" then return true end
        end
    end
    return false
end

local function hvsEmptyAt(y)
    local w = Refs.World
    local row = w and w.fg[y]
    if not row then return true end
    for x = 0, w.w - 1 do
        local id = row[x]
        if id and id ~= 0 then return false end
    end
    return true
end

local function hvsRowMap(w)
    -- Stabil selama satu sesi: kalau peta dibangun ulang setelah beberapa baris
    -- dipanen (pohon hilang), rank baris bergeser dan arah snake jadi acak.
    if Hvs.RowRank and Hvs.RowRankWorld == w then
        return Hvs.RowRank, Hvs.RowCount or 0
    end
    local map, n = {}, 0
    for y = 0, w.h - 1 do
        local row = w.fg[y]
        local plant = false
        if row then
            for x = 0, w.w - 1 do
                local id = row[x]
                if id and id ~= 0 then
                    local it = ItemDB[id]
                    if it and it.kind == "seed" then plant = true break end
                end
            end
        end
        if not plant and y + 1 < w.h and hvsEmptyAt(y) and hvsSolidBlockAt(y + 1) then
            plant = true
        end
        if plant then
            n += 1
            map[y] = n
        end
    end
    Hvs.RowRank, Hvs.RowRankWorld, Hvs.RowCount = map, w, n
    return map, n
end

-- Baris panen/tanam paling bawah (Floor 1) tidak boleh dipanen atau ditanami.
local function hvsBottomRowY(w)
    if not w then return nil end
    local map, count = hvsRowMap(w)
    if count < 2 then return nil end
    local bottomY = nil
    for y in pairs(map) do
        if bottomY == nil or y > bottomY then
            bottomY = y
        end
    end
    return bottomY
end

local function hvsOrder()
    local w = Refs.World
    local map, count = {}, 0
    if w then map, count = hvsRowMap(w) end
    local topDown = Hvs.Order == "Atas ke Bawah"
    return function(a, b)
        local ia = map[a.y] or (a.y + 1)
        local ib = map[b.y] or (b.y + 1)
        if ia ~= ib then
            if topDown then return ia < ib end
            return ia > ib
        end
        local ra = topDown and (ia - 1) or (count - ia)
        local dir = (ra % 2 == 0) and 1 or -1
        if a.x ~= b.x then
            if dir > 0 then return a.x < b.x end
            return a.x > b.x
        end
        return false
    end
end

local function hvsRefreshKinds(w)
    if Hvs.KindWorld ~= w then
        Hvs.KindWorld = w
        Hvs.KindScanAt = 0
        table.clear(Hvs.TypeIds)
    end
    local now = os.clock()
    if not (Hvs.DropOn or Hvs.DropSeedOn) or now < (Hvs.KindScanAt or 0) then return end
    Hvs.KindScanAt = now + 1

    local seenSeeds = {}
    for y = 0, w.h - 1 do
        local row = w.fg[y]
        if row then
            for x = 0, w.w - 1 do
                local id = row[x]
                if id and id ~= 0 and not seenSeeds[id] then
                    seenSeeds[id] = true
                    local item = ItemDB[id]
                    local block = item and item.kind == "seed" and blockOfSeed(id)
                    if block and not table.find(Hvs.TypeIds, block) then
                        Hvs.TypeIds[#Hvs.TypeIds + 1] = block
                    end
                end
            end
        end
    end
end

-- Jenis block hasil panen yang sudah mencapai batas drop.
local function hvsFullKinds()
    local out = {}
    if not Hvs.DropOn then return out end
    local lim = tonumber(Hvs.DropAt) or 200
    for _, id in ipairs(Hvs.TypeIds) do
        local n = invCount(id)
        if n >= lim then out[#out + 1] = id end
    end
    return out
end

-- Seed dari jenis pohon yang ditemukan di world. Hanya seed milik block
-- yang memang menjadi target Auto Harvest, bukan seed lain di inventory.
local function hvsFullSeeds()
    local out, seen = {}, {}
    if not Hvs.DropSeedOn then return out end
    for _, blockId in ipairs(Hvs.TypeIds) do
        local seedId = seedOfBlock(blockId)
        if seedId and not seen[seedId] and invCount(seedId) >= 200 then
            seen[seedId] = true
            out[#out + 1] = seedId
        end
    end
    return out
end

-- Gabungkan block dan seed agar keduanya dapat dibuang dalam satu perjalanan.
local function hvsFullDropItems()
    local out, seen = {}, {}
    for _, id in ipairs(hvsFullKinds()) do
        if not seen[id] then
            seen[id] = true
            out[#out + 1] = { id = id, kind = "block" }
        end
    end
    for _, id in ipairs(hvsFullSeeds()) do
        if not seen[id] then
            seen[id] = true
            out[#out + 1] = { id = id, kind = "seed" }
        end
    end
    return out
end

local function hvsDropDue()
    -- Jalur ini dipanggil berkali-kali oleh MoveTick; cek boolean langsung
    -- agar tidak membuat tabel sementara pada setiap frame.
    if Hvs.DropOn then
        local limit = tonumber(Hvs.DropAt) or 200
        for _, id in ipairs(Hvs.TypeIds) do
            if invCount(id) >= limit then return true end
        end
    end
    if Hvs.DropSeedOn then
        for _, blockId in ipairs(Hvs.TypeIds) do
            local seedId = seedOfBlock(blockId)
            if seedId and invCount(seedId) >= 200 then return true end
        end
    end
    return false
end

local function hvsWait(ms)
    local deadline = os.clock() + math.max(tonumber(ms) or 0, 1) / 1000
    while hvsLive() and not hvsDropDue() do
        local remaining = deadline - os.clock()
        if remaining <= 0 then break end
        task.wait(math.min(remaining, 0.05))
    end
    return hvsLive() and not hvsDropDue()
end

local function hvsFace(facing, live)
    facing = (facing and facing < 0) and -1 or 1
    local s = playerState()
    if not s then return false end
    local function cur() local p = playerState(); return p and (((p.facing or 1) < 0) and -1 or 1) end
    if cur() == facing then return true end
    local was = AutoInput.active
    AutoInput.active = true
    local t0 = os.clock()
    while live() and os.clock() - t0 < 1.2 do
        if cur() == facing then break end
        AutoInput.left, AutoInput.right = facing < 0, facing > 0
        task.wait(0.05)
    end
    releaseInput()
    AutoInput.active = was
    return live() and cur() == facing
end

-- Pergi ke satu tile drop bersama, buang block dan/atau seed yang sudah
-- mencapai batas, lalu pulang ke posisi panen.
local function hvsDropTrip()
    local x, y = tonumber(Hvs.DropX) or -1, tonumber(Hvs.DropY) or -1
    if x < 0 or y < 0 then return false, "Tile drop belum diatur" end
    local w = Refs.World
    local worldName = Guard.worldName()
    if not w then return false, "Data world belum ketemu" end
    if Hvs.DropWorld ~= "" and worldName ~= Hvs.DropWorld then
        return false, "Tunggu world " .. Hvs.DropWorld
    end
    if x >= w.w or y >= w.h or not openAt(x, y) or not realSupport(x, y) then
        return false, "Tile drop harus kosong & punya pijakan"
    end
    local items = hvsFullDropItems()
    if #items == 0 then return false end
    local s = playerState()
    if not s then return false end
    local hx, hy = startNode(s)
    -- Simpan posisi asal sebelum bergerak. Jika ada runtime error di tengah
    -- transaksi drop, worker utama dapat memulihkan avatar sebelum panen lanjut.
    Hvs.DropRecovery = { x = hx, y = hy, world = w, worldName = worldName }
    local function tripLive()
        -- Setelah perjalanan dimulai, selesaikan antrean item yang sudah dipilih
        -- dan pulang dengan aman meskipun toggle diubah di tengah perjalanan.
        return hvsLive() and Refs.World == w and Guard.worldName() == worldName
    end

    Hvs.Dropping = true
    Hvs.DropLive = tripLive
    Hvs.DropStatus = ("Jalan ke titik drop (%d,%d)"):format(x, y)
    local ok = walkTo(x, y, 45, tripLive, nil, true)
    if not ok or not tripLive() then
        Hvs.Dropping, Hvs.DropLive = false, nil
        if not tripLive() then return false end
        return false, "Rute ke tile drop belum ditemukan"
    end

    local facingDir = (Hvs.Facing or 1) < 0 and -1 or 1
    local dropped, why = 0, nil
    local dropZones = {}
    local homeGoals = { [hy * w.w + hx] = true, allowLongFall = true }

    local function zoneFor(id, direction, now)
        return {
            id = id, world = worldName, at = now,
            x = x + 0.5, y = y + 0.5, dropX = x + 0.5 + direction, dropY = y + 0.5,
        }
    end

    local function hasDropSpace(direction)
        local current = playerState()
        if not tripLive() or not current or current.dead or not current.grounded then
            return false
        end
        local px, py = startNode(current)
        local front = px + direction
        if front < 0 or front >= w.w or not openAt(front, py) then
            return false
        end
        return true, px, py
    end

    local function canReturnAfterDrop(direction)
        local current = playerState()
        if not tripLive() or not current or current.dead or not current.grounded then return false end
        local px, py = startNode(current)
        local front = px + direction
        if front < 0 or front >= w.w or not openAt(front, py) then return false end

        local proposed = {}
        local now = os.clock()
        local oldX, oldY = x, y
        x, y = px, py
        for _, entry in ipairs(items) do
            proposed[entry.id] = zoneFor(entry.id, direction, now)
        end
        local route = AutoDrop.route(proposed)
        local reachable = route.point(hx, hy)
            and astar(px, py, homeGoals, hx, hy, 0.5, false, route) ~= nil
        x, y = oldX, oldY
        return reachable
    end

    -- Prioritaskan arah yang diprediksi punya jalur pulang. Jika prediksi A*
    -- terlalu konservatif, izinkan drop pada sisi yang benar-benar terbuka.
    -- Ini hanya mengubah keputusan Auto Drop, bukan pemilihan target panen.
    local preferredFacing = facingDir
    local chosenFacing = nil

    local function tryFacing(direction, requireReturn)
        local space, px, py = hasDropSpace(direction)
        if not space then return false end
        if requireReturn and not canReturnAfterDrop(direction) then return false end
        if not hvsFace(direction, tripLive) then return false end
        space, px, py = hasDropSpace(direction)
        if not space then return false end
        if requireReturn and not canReturnAfterDrop(direction) then return false end
        x, y = px, py
        return true
    end

    if tryFacing(preferredFacing, true) then
        chosenFacing = preferredFacing
    elseif tripLive() and tryFacing(-preferredFacing, true) then
        chosenFacing = -preferredFacing
    elseif tripLive() and tryFacing(preferredFacing, false) then
        chosenFacing = preferredFacing
    elseif tripLive() and tryFacing(-preferredFacing, false) then
        chosenFacing = -preferredFacing
    end

    if chosenFacing and tripLive() then
        facingDir = chosenFacing
        hvsHookPickup()
        local function protect(id)
            local now = os.clock()
            local untilT = now + math.clamp(tonumber(Hvs.DropGuardSec) or 2, 1, 5)
            Hvs.PickupUntil = untilT
            Hvs.MarkWorld = w
            Hvs.MarkX, Hvs.MarkY, Hvs.MarkUntil, Hvs.MarkNext = x, y, untilT, 0
            hvsMarkDropped(x, y, untilT)
            dropZones[id] = zoneFor(id, facingDir, now)
        end
        local batch = { nextAt = 0, protect = protect }
        for _, entry in ipairs(items) do
            if not tripLive() then break end
            local id = entry.id
            local isSeed = entry.kind == "seed"
            local threshold = isSeed and 200 or (tonumber(Hvs.DropAt) or 200)
            local n = invCount(id)
            -- Daftar item diambil sebagai snapshot sebelum perjalanan. Setelah
            -- trip dimulai, selesaikan item yang sudah masuk antrean agar avatar
            -- tetap pulang dengan aman meskipun toggle diubah di tengah perjalanan.
            if n >= threshold then
                local label = isSeed and "Drop seed " or "Drop block "
                Hvs.DropStatus = label .. itemName(id) .. " x" .. n
                if isSeed then Hvs.DropSeedStatus = Hvs.DropStatus end
                local amount = isSeed and n or math.min(n, 200)
                local got, err = dropItems(id, amount, tripLive, false, batch)
                dropped += got
                if isSeed then
                    Hvs.SeedDropped += got
                    if got > 0 then
                        Hvs.DropSeedStatus = ("Dibuang %s x%d"):format(itemName(id), got)
                    end
                else
                    Hvs.Dropped += got
                end
                if err then
                    why = err
                    if isSeed then Hvs.DropSeedStatus = "Drop seed gagal: " .. tostring(err) end
                    break
                end
            end
        end
    elseif tripLive() then
        why = "Tile di depan kedua arah drop terhalang atau karakter belum siap"
    end

    -- Jika tidak ada item yang berhasil dibuang, jangan membuat siklus pulang
    -- tanpa hasil; status error akan ditampilkan dan percobaan diulang kemudian.
    if dropped == 0 then
        Hvs.Dropping = false
        Hvs.DropLive = nil
        autoEnd()
        releaseInput()
        if not tripLive() then return false end
        return false, why or "Item belum terkonfirmasi dibuang"
    end

    -- PENTING: Dropping tetap true selama perjalanan pulang. Jika dilepas setelah
    -- inventory berkurang, MoveTick dapat mulai memanen saat walkTo masih berjalan.
    -- Itu membuat karakter menyimpang dari rute pulang meskipun inventory belum penuh.
    local back = false
    if tripLive() then
        Hvs.DropStatus = ("Kembali ke posisi panen (%d,%d)"):format(hx, hy)
        -- Drop milik Auto Harvest sudah dilindungi melalui DropBlock/PickupUntil.
        -- Jangan jadikan daftar item drop sebagai obstacle A*: AutoDrop.route()
        -- mencocokkan semua drop dengan ID sama dalam radius 2.5 tile, sehingga
        -- drop lama/di sekitar dapat menutup koridor yang sebenarnya kosong.
        -- Navigasi pulang cukup memakai collision map world yang aktual.
        local backWhy
        back, backWhy = walkTo(hx, hy, 45, tripLive, nil, true, true)
    end
    Hvs.Dropping = false
    Hvs.DropLive = nil
    autoEnd()
    releaseInput()
    if not tripLive() then return false end
    if not back and next(dropZones) then
        -- Jangan matikan Auto Harvest hanya karena satu percobaan pulang gagal.
        -- Simpan titik asal dan zona drop; worker utama akan mengulang rute pulang
        -- sebelum mengizinkan proses panen berjalan lagi.
        Hvs.DropReturnTarget = {
            x = hx, y = hy, world = w, zones = dropZones,
            worldName = worldName,
        }
        Hvs.Dropping = true
        Hvs.DropLive = nil
        Hvs.DropStatus = backWhy and ("Drop selesai; " .. backWhy) or "Drop selesai; rute pulang perlu dicoba lagi"
        releaseInput()
        return false, Hvs.DropStatus
    end
    Hvs.Dropping = false
    Hvs.DropReturnTarget = nil
    Hvs.DropRecovery = nil
    Hvs.DropError = nil
    Hvs.DropStatus = "Drop selesai, balik ke posisi panen"
    return true
end

-- Kecepatan adaptif: lebih pelan saat mendekati pohon / sedang mengunci harvest,
-- sedikit lebih cepat saat target masih jauh. Tidak pernah memakai fast-walk agresif.
local function hvsAdaptiveSpeed(s)
    if not Hvs.Running then return end
    if Hvs.Dropping then
        AutoInput.speed = nil
        return
    end

    -- Misc.Speed mendukung 50..500. Jangan memotongnya ke 100 karena itu
    -- membuat avatar terasa slow motion saat pengguna memilih speed > 100.
    local base = math.clamp(tonumber(Misc.Speed) or 100, 50, 500)
    local target = Hvs.PendingTarget or Hvs.HarvestLock or Hvs.AdaptiveTarget
    local now = os.clock()
    local factor = 0.96
    local distance, reach = nil, math.max(1, farmReach())

    if target and target.world == Refs.World
        and target.x >= 0 and target.y >= 0
        and fgIdAt(target.x, target.y) ~= 0 then
        local dx = abs((target.x + 0.5) - s.x)
        local dy = abs((target.y + 0.5) - (s.y - 0.475))
        distance = math.sqrt(dx * dx + (dy * 1.25) * (dy * 1.25))
    end

    -- Koreksi kecil saja: jaga kontrol di dekat pohon tanpa mengubah gerak
    -- menjadi sangat lambat. Nilai minimum faktor tetap 0.88.
    if Hvs.HarvestBusy or Hvs.PendingTarget then
        factor = 0.90
    elseif distance then
        if distance <= reach then
            factor = 0.90
        elseif distance <= reach + 1.5 then
            factor = 0.92
        elseif distance <= reach + 3 then
            factor = 0.95
        elseif distance <= reach + 6 then
            factor = 0.97
        else
            factor = 1.00
        end
    end

    if now < (Hvs.NextHarvestAt or 0) then
        factor = math.min(factor, (distance and distance <= reach + 1.5) and 0.88 or 0.94)
    end

    local desired = math.clamp(base * factor, 50, 500)
    local current = tonumber(Hvs.SpeedCurrent) or base
    local lastAt = tonumber(Hvs.SpeedUpdateAt) or 0
    local dt = (lastAt > 0) and math.clamp(now - lastAt, 0, 0.10) or 0.10
    -- Smooth tetapi responsif: maksimum perubahan 18 poin per 100 ms.
    local maxChange = 180 * dt
    current += math.clamp(desired - current, -maxChange, maxChange)
    Hvs.SpeedCurrent = current
    Hvs.SpeedUpdateAt = now
    AutoInput.speed = math.clamp(math.floor(current + 0.5), 50, 500)
end

-- Simpan koordinat panen agar drop yang muncul terlambat tetap ditemukan collector.
local function hvsQueueCollectTarget(target)
    if not Hvs.CollectOn or type(target) ~= "table" then return end
    local w = target.world or Refs.World
    if not w or w ~= Refs.World then return end
    local x, y = tonumber(target.x), tonumber(target.y)
    if not x or not y then return end
    local idx = target.idx or (y * w.w + x)
    local queue = Hvs.PendingCollect or {}
    Hvs.PendingCollect = queue
    for _, entry in ipairs(queue) do
        if entry.world == w and entry.idx == idx then
            entry.expires = os.clock() + 15
            return
        end
    end
    queue[#queue + 1] = {
        x = x, y = y, idx = idx, world = w,
        at = os.clock(), expires = os.clock() + 15,
    }
    while #queue > 64 do table.remove(queue, 1) end
end

-- Spacing panen: avatar harus berada satu tile di samping pohon, bukan
-- menumpuk di tile pohon atau memukul dari jarak yang terlalu jauh.
local function hvsAtSpacing(s, x, y)
    if not s or not s.grounded or floor(s.y - 0.475) ~= y then return false end
    local dx = abs((x + 0.5) - s.x)
    local dy = abs((y + 0.5) - (s.y - 0.475))
    local R = math.max(0.1, farmReach() - 0.08)
    return dx >= 0.68 and dx <= 1.38 and dy <= 0.60
        and stateReaches(s, x, y, R)
end

-- Target pada row di atas boleh dipanen dari posisi sekarang jika benar-benar
-- masuk jangkauan dan garis pandang tidak tertutup block solid. Mode ini hanya
-- untuk transisi vertikal; panen pada row aktif tetap wajib menjaga spacing 1 tile.
local function hvsVerticalReach(s, target)
    if not s or not s.grounded or not target then return false end
    local playerRow = floor(s.y - 0.475)
    if target.y >= playerRow then return false end
    local R = math.max(0.1, farmReach() - 0.08)
    if not stateReaches(s, target.x, target.y, R) then return false end
    return Move.los(floor(s.x), playerRow, target.x, target.y)
end

local function hvsCanHarvestPosition(s, x, y)
    if not s or not s.grounded then return false end
    local playerRow = floor(s.y - 0.475)
    if y == playerRow then return hvsAtSpacing(s, x, y) end
    return hvsVerticalReach(s, { x = x, y = y })
end

local function hvsRowDirection(y, w)
    w = w or Refs.World
    if not w then return 1 end
    local map, count = hvsRowMap(w)
    local rank = map[y] or (y + 1)
    local rowRank = (Hvs.Order == "Atas ke Bawah") and (rank - 1) or (count - rank)
    return (rowRank % 2 == 0) and 1 or -1
end

-- Kandidat tile berdiri tepat di samping target. Urutan sisi tetap mengikuti
-- posisi avatar agar pola gerak Auto Harvest tidak berubah.
local function hvsSpacingCandidateTiles(target, s)
    local w = target and target.world or Refs.World
    if not w or w ~= Refs.World or not s then return {} end
    local center = target.x + 0.5
    local side
    if s.x < center - 0.18 then
        side = -1
    elseif s.x > center + 0.18 then
        side = 1
    else
        side = -hvsRowDirection(target.y, w)
    end

    local out = {}
    for _, dx in ipairs({ side, -side }) do
        local x, y = target.x + dx, target.y
        if x >= 0 and x < w.w and y >= 0 and y < w.h then
            out[#out + 1] = { x = x, y = y }
        end
    end
    return out
end

-- Pilih tile berdiri yang benar-benar bisa ditempati.
-- Passable door / object tidak dipaksa kosong; selama collision game
-- menyatakan tile itu tidak solid, avatar boleh melewatinya.
local function hvsSpacingNodes(target, s)
    local out = {}
    for _, node in ipairs(hvsSpacingCandidateTiles(target, s)) do
        if openAt(node.x, node.y) and realSupport(node.x, node.y) then
            out[#out + 1] = node
        end
    end
    return out
end

-- Cari block yang benar-benar menghalangi. Pohon tidak dihancurkan oleh
-- mekanisme obstacle ini; pohon tetap ditangani oleh mesin Auto Harvest.
local function hvsBreakableObstacleAt(x, y)
    local w = Refs.World
    if not w or x < 0 or y < 0 or x >= w.w or y >= w.h then return nil end
    if openAt(x, y) then return nil end

    local fg = fgIdAt(x, y)
    if fg ~= 0 then
        local item = ItemDB[fg]
        if item and item.kind == "seed" then return nil end
        if canBreak(fg) then
            return { x = x, y = y, id = fg, layer = "fg" }
        end
        return nil
    end

    local bg = bgIdAt(x, y)
    if State.BreakBackground and bg ~= 0 and canBreak(bg) then
        return { x = x, y = y, id = bg, layer = "bg" }
    end
    return nil
end

-- Hancurkan satu obstacle yang memang tidak bisa dilewati.
-- Tidak ada noclip/Ghost di sini. Avatar harus tetap berada pada posisi
-- yang secara fisik dapat memukul block tersebut.
local function hvsBreakObstacleAt(x, y, live, maxSec)
    local obstacle = hvsBreakableObstacleAt(x, y)
    if not obstacle or not hvsLive() then return false end
    if live and not live() then return false end
    if not canWorkAt(x, y) then return false end

    local s = playerState()
    if not s or s.dead then return false end

    local function inPunchReach()
        local cur = playerState()
        return cur and not cur.dead
            and stateReaches(cur, x, y, math.max(0.1, punchReach() - 0.05))
            and canWorkAt(x, y)
    end

    -- Jika block belum terjangkau, dekati sisi block yang berada di depan avatar.
    if not inPunchReach() then
        local sx = floor(s.x)
        local sy = floor(s.y - 0.475)
        local dir = x > sx and 1 or (x < sx and -1 or 0)
        local approaches = {}

        if dir ~= 0 then
            approaches[#approaches + 1] = { x = x - dir, y = y }
        end
        approaches[#approaches + 1] = { x = x + 1, y = y }
        approaches[#approaches + 1] = { x = x - 1, y = y }
        approaches[#approaches + 1] = { x = x, y = y + 1 }
        approaches[#approaches + 1] = { x = x, y = y - 1 }

        local approached = false
        local limit = math.min(8, math.max(3, tonumber(maxSec) or 6))
        for _, a in ipairs(approaches) do
            if a.x >= 0 and a.x < Refs.World.w and a.y >= 0 and a.y < Refs.World.h
                and openAt(a.x, a.y) and realSupport(a.x, a.y) then
                local ok = walkTo(a.x, a.y, limit, live, nil, true, true)
                if ok and inPunchReach() then
                    approached = true
                    break
                end
            end
            if live and not live() then return false end
        end
        if not approached and not inPunchReach() then return false end
    end

    local oldBusy = Hvs.HarvestBusy
    Hvs.HarvestBusy = true
    local changed = false
    local deadline = os.clock() + math.min(6, math.max(2, tonumber(maxSec) or 6))
    local interval = math.max(0.08, tonumber(Hvs.HitMs) or 250) / 1000

    while hvsLive() and os.clock() < deadline do
        if live and not live() then break end
        if openAt(x, y) then
            changed = true
            break
        end

        local currentObstacle = hvsBreakableObstacleAt(x, y)
        if not currentObstacle or not canWorkAt(x, y) then break end

        local ok, result = pcall(tryBreak, x, y, true, nil, function()
            return hvsLive()
                and (not live or live())
                and canWorkAt(x, y)
                and hvsBreakableObstacleAt(x, y) ~= nil
        end)

        if not ok then
            break
        end

        if result == "broke" then
            changed = true
            break
        elseif result == "hit" then
            changed = true
            task.wait(interval)
        else
            break
        end
    end

    Hvs.HarvestBusy = oldBusy
    return changed
end

-- Jika jalur horizontal terhalang, buka hanya block pertama yang benar-benar
-- menghalangi. Block yang passable dilewati; block yang tidak bisa dihancurkan
-- tidak disentuh sehingga A* masih boleh mencari jalur lain.
local function hvsClearBlockingPath(node, live, maxSec)
    local s = playerState()
    if not s or s.dead or not node then return false end

    local sx = floor(s.x)
    local sy = floor(s.y - 0.475)
    local tx, ty = node.x, node.y
    local cells = {}

    local dx = tx > sx and 1 or (tx < sx and -1 or 0)
    if sy == ty and dx ~= 0 then
        local x = sx + dx
        while (dx > 0 and x <= tx) or (dx < 0 and x >= tx) do
            cells[#cells + 1] = { x = x, y = sy }
            x += dx
        end
    else
        -- Untuk transisi vertikal, buka obstacle tepat di depan avatar terlebih
        -- dahulu. Setelah itu walkTo/A* dihitung ulang dari posisi baru.
        if dx ~= 0 then
            cells[#cells + 1] = { x = sx + dx, y = sy }
            cells[#cells + 1] = { x = sx + dx, y = sy - 1 }
        end
    end

    for _, cell in ipairs(cells) do
        if cell.x >= 0 and cell.x < Refs.World.w and cell.y >= 0 and cell.y < Refs.World.h then
            if not openAt(cell.x, cell.y) then
                local obstacle = hvsBreakableObstacleAt(cell.x, cell.y)
                if obstacle then
                    return hvsBreakObstacleAt(cell.x, cell.y, live, maxSec)
                end
                return false
            end
        end
    end
    return false
end

-- Cari pohon penghalang pada baris avatar/target maupun di atasnya.
-- Pohon di depan avatar pada baris yang sama dapat menutup tile spacing; panen
-- pohon itu lebih dulu, lalu lanjutkan target yang sebelumnya tertunda.
local function hvsFindSpacingBlocker(target, s)
    local w = target and (target.world or Refs.World)
    if not target or not w or w ~= Refs.World or not s then return nil end

    local currentX = floor(s.x)
    local currentY = floor(s.y - 0.475)
    local center = target.x + 0.5
    local side
    if s.x < center - 0.18 then
        side = -1
    elseif s.x > center + 0.18 then
        side = 1
    else
        side = -hvsRowDirection(target.y, w)
    end
    local direction = target.x > currentX and 1
        or (target.x < currentX and -1 or hvsRowDirection(currentY, w))

    -- Periksa tile spacing target terlebih dahulu, lalu seluruh koridor avatar
    -- menuju target. Versi lama hanya memeriksa 5 kolom sehingga pohon matang
    -- di tengah jalur dapat terlewat dan avatar tampak diam sampai didekati manual.
    local columns, seenColumns = {}, {}
    local function addColumn(x)
        if x >= 0 and x < w.w and not seenColumns[x] then
            seenColumns[x] = true
            columns[#columns + 1] = x
        end
    end
    addColumn(target.x + side)
    addColumn(target.x - side)
    local distance = math.abs(target.x - currentX)
    for step = 1, distance do
        addColumn(currentX + direction * step)
    end
    addColumn(currentX - direction)
    addColumn(currentX)
    addColumn(target.x)

    local rows, seenRows = {}, {}
    local function addRow(y)
        if y >= 0 and y < w.h and not seenRows[y] then
            seenRows[y] = true
            rows[#rows + 1] = y
        end
    end
    addRow(currentY)
    addRow(target.y)
    addRow(currentY - 1)
    addRow(currentY - 2)
    addRow(target.y - 1)
    addRow(target.y - 2)

    local serverTime = workspace:GetServerTimeNow()
    local resume = Hvs.SpacingResumeTarget
    for _, x in ipairs(columns) do
        for _, y in ipairs(rows) do
            local isResumeTarget = resume and resume.world == w
                and resume.x == x and resume.y == y
            if (x ~= target.x or y ~= target.y) and not isResumeTarget then
                local id = fgIdAt(x, y)
                local item = id ~= 0 and ItemDB[id]
                local readyAt = id ~= 0 and treeReadyAt(x, y, id)
                if item and item.kind == "seed" and solidAt(x, y)
                    and readyAt and serverTime >= readyAt and canWorkAt(x, y) then
                    local candidate = {
                        x = x, y = y,
                        idx = y * w.w + x,
                        id = id, world = w, spacingDependency = true,
                        readyAt = readyAt,
                    }
                    -- Pilih pohon penghalang yang sendiri sudah punya tile
                    -- spacing kosong. Ini menghindari rantai target yang saling
                    -- mengunci ketika satu baris ditanami rapat tanpa celah.
                    if #hvsSpacingNodes(candidate, s) > 0 then
                        return candidate
                    end
                end
            end
        end
    end
    return nil
end

-- Panen SATU pohon siap pada satu waktu. HarvestBusy mencegah callback frame
-- dan loop utama menjalankan tryBreak bersamaan ketika salah satunya sedang yield.
local function hvsWorkInReach(s, retryTarget)
    if Hvs.HarvestBusy then return 0 end
    local w = Refs.World
    if not w then return 0 end
    local W = w.w
    local R = farmReach() - 0.08
    local playerRow = floor(s.y - 0.475)
    local y = retryTarget and retryTarget.y or playerRow
    if not s.grounded or playerRow < 0 or playerRow >= w.h then return 0 end
    local skipBottomY = hvsBottomRowY(w)
    if skipBottomY ~= nil and y == skipBottomY then return 0 end
    if retryTarget and y ~= playerRow and not hvsVerticalReach(s, retryTarget) then return 0 end
    if y < 0 or y >= w.h then return 0 end

    local now = os.clock()
    if now < (Hvs.NextHarvestAt or 0) then return 0 end

    local serverTime = workspace:GetServerTimeNow()
    local list = {}
    local left = retryTarget and retryTarget.x or math.max(0, floor(s.x - R - 0.5))
    local right = retryTarget and retryTarget.x or math.min(floor(s.x + R + 0.5), W - 1)
    for x = left, right do
        if stateReaches(s, x, y, R) and hvsCanHarvestPosition(s, x, y) then
            local idx = y * W + x
            if not skipped(Hvs.Skip, idx, now) then
                local id = fgIdAt(x, y)
                local readyAt = id ~= 0 and treeReadyAt(x, y, id)
                if readyAt and serverTime >= readyAt then
                    if canWorkAt(x, y) then
                        list[#list + 1] = { x = x, y = y, idx = idx, world = w }
                    else
                        skipTile(Hvs.Skip, idx, 120)
                    end
                end
            end
        end
    end
    if #list == 0 then return 0 end

    -- Jika satu pohon membutuhkan beberapa hit, lock tetap menunjuk pohon yang sama
    -- sampai pohon tersebut benar-benar hilang dari foreground.
    local pending = Hvs.PendingTarget
    if pending then
        local pendingId = (pending.world == w) and fgIdAt(pending.x, pending.y) or nil
        if pending.world ~= w or pendingId == 0
            or (pending.id and pendingId ~= pending.id) then
            -- Jika target sudah hilang setelah respons server terlambat, catat
            -- tile-nya supaya drop tetap dicari walau avatar sudah menjauh.
            if pending.world == w and pendingId == 0 then hvsQueueCollectTarget(pending) end
            Hvs.PendingTarget = nil
        else
            Hvs.AdaptiveTarget = pending
            -- Jangan mengerjakan pohon lain sebelum target multi-hit selesai.
            if pending.y ~= y or not hvsCanHarvestPosition(s, pending.x, pending.y) then return 0 end
            local found = false
            for _, t in ipairs(list) do
                if t.idx == pending.idx then found = true break end
            end
            if found then
                list = { pending }
            else
                return 0
            end
        end
    end
    -- Di baris yang sama, ikuti urutan snake secara ketat agar pohon di pojok
    -- tidak terlewati saat avatar memanjat dari baris bawah.
    local rowMap, rowCount = hvsRowMap(w)
    local rank = rowMap[y] or (y + 1)
    local rowRank = (Hvs.Order == "Atas ke Bawah") and (rank - 1) or (rowCount - rank)
    local sweepDir = (rowRank % 2 == 0) and 1 or -1
    table.sort(list, function(a, b)
        if a.x ~= b.x then
            return (a.x * sweepDir) < (b.x * sweepDir)
        end
        return false
    end)

    -- Hanya satu kandidat yang dicoba dalam satu slot waktu. Kandidat berikutnya
    -- menunggu cooldown, bukan ikut mengirim aksi pada slot yang sama.
    local t = list[1]
    if not t then return 0 end
    local id = fgIdAt(t.x, t.y)
    if id == 0 then return 0 end
    Hvs.AdaptiveTarget = { x = t.x, y = t.y, idx = t.idx, world = w }

    local function canHarvest(x, ty, blockId)
        if not hvsLive() or hvsDropDue() or Refs.World ~= w or fgIdAt(x, ty) ~= blockId then return false end
        local cur = playerState()
        if not cur or not cur.grounded or not hvsCanHarvestPosition(cur, x, ty) then return false end
        local readyAt = treeReadyAt(x, ty, blockId)
        return readyAt and workspace:GetServerTimeNow() >= readyAt and canWorkAt(x, ty)
    end

    if not canHarvest(t.x, y, id) then return 0 end

    Hvs.HarvestBusy = true
    Hvs.HarvestLock = { x = t.x, y = y, idx = t.idx, id = id, world = w, at = os.clock() }
    local ok, result = pcall(tryBreak, t.x, y, false, nil, canHarvest)
    Hvs.HarvestBusy = false
    Hvs.HarvestLock = nil

    if not ok then
        if os.clock() - (Hvs.LastHarvestErrorAt or -10) >= 5 then
            Hvs.LastHarvestErrorAt = os.clock()
            warn("[ByteHub] Auto Harvest action: " .. tostring(result))
        end
        skipTile(Hvs.Skip, t.idx, 1)
        Hvs.PendingTarget = nil
        return 0
    end

    local interval = math.max(1, tonumber(Hvs.HitMs) or 250) / 1000
    if result == "broke" then
        Hvs.Harvested += 1
        local outId = blockOfSeed(id) or id
        if not table.find(Hvs.TypeIds, outId) then
            Hvs.TypeIds[#Hvs.TypeIds + 1] = outId
        end
        Hvs.Status = ("Panen %s (%d,%d)"):format(itemName(id), t.x, y)
        Hvs.PendingTarget = nil
        if t.y < playerRow then
            -- Pohon row atas sudah kosong. Jadikan tile bekas pohon sebagai
            -- pijakan transisi agar avatar naik dahulu sebelum menyapu row itu.
            Hvs.RowTransitionTarget = { x = t.x, y = t.y, idx = t.idx, world = w }
        end
        hvsQueueCollectTarget({ x = t.x, y = y, idx = t.idx, world = w })
        Hvs.NextHarvestAt = os.clock() + interval
        return 1
    elseif result == "hit" then
        Hvs.PendingTarget = { x = t.x, y = t.y, idx = t.idx, id = id, world = w }
        Hvs.Status = ("Memanen %s (%d,%d)"):format(itemName(id), t.x, y)
        Hvs.NextHarvestAt = os.clock() + interval
        return 0
    end

    -- Tidak ada aksi terkonfirmasi: jangan pindah ke pohon lain pada slot yang sama.
    skipTile(Hvs.Skip, t.idx, 0.15)
    if Hvs.PendingTarget and Hvs.PendingTarget.idx == t.idx then
        Hvs.PendingTarget = nil
    end
    Hvs.NextHarvestAt = os.clock() + math.min(interval, 0.15)
    return 0
end

-- Worker tunggal untuk semua pemanggil harvest. tryBreak dapat menunggu respons
-- game; kunci ini mencegah loop utama dan callback gerak menjalankannya bersamaan.
local function hvsRunWork(s, retryTarget)
    if Hvs.HarvestWorkerBusy or not hvsLive() then return 0 end
    Hvs.HarvestWorkerBusy = true
    local ok, harvested, failed = pcall(hvsWorkInReach, s, retryTarget)
    Hvs.HarvestWorkerBusy = false
    if not ok then
        if os.clock() - (Hvs.LastWorkerErrorAt or -10) >= 10 then
            Hvs.LastWorkerErrorAt = os.clock()
            warn("[ByteHub] Auto Harvest worker: " .. tostring(harvested))
        end
        return 0
    end
    return harvested or 0, failed
end

-- Dekati pohon melalui tile berdiri yang berjarak satu block. Jangan pernah
-- walkTo() ke koordinat pohon itu sendiri karena itu menghilangkan spacing.
local function hvsMoveToSpacing(target, maxSec, live)
    local w = target and (target.world or Refs.World)
    if not target or not w or w ~= Refs.World then return false end
    local function deferForBlocker(blocker)
        -- Override cooldown lama untuk blocker: target prioritas harus boleh
        -- dicoba sekarang, bukan ikut tertahan oleh skip dari percobaan rute lama.
        if blocker.idx then Hvs.Skip[blocker.idx] = nil end
        Hvs.SpacingPriorityTarget = blocker
        if not Hvs.SpacingResumeTarget then
            Hvs.SpacingResumeTarget = {
                x = target.x, y = target.y, idx = target.idx,
                id = target.id or fgIdAt(target.x, target.y), world = w,
            }
        end
        Hvs.SpacingDependencyTarget = blocker
        Hvs.PathStatus = ("Mendahulukan pohon penghalang (%d,%d) untuk membuka spacing (%d,%d)")
            :format(blocker.x, blocker.y, target.x, target.y)
        Hvs.Status = Hvs.PathStatus
    end
    local function targetLive()
        if not hvsLive() or Refs.World ~= w or hvsDropDue() then return false end
        if live and not live() then return false end
        -- Jika jalur menemukan pohon terlewat, hentikan walkTo saat itu juga
        -- agar worker tidak terus mencoba rute yang sama sampai timeout.
        if Hvs.TravelLive and not Hvs.TravelLive() then return false end
        local id = fgIdAt(target.x, target.y)
        if id == 0 then return false end
        if target.id and id ~= target.id then return false end
        return true
    end

    local s = playerState()
    if not targetLive() then return false end
    if hvsAtSpacing(s, target.x, target.y) then return true end

    -- Bersihkan obstacle yang tepat menutup tile spacing jika obstacle tersebut
    -- memang bisa dihancurkan. Jika passable, hvsSpacingNodes akan menerimanya.
    local nodes = hvsSpacingNodes(target, s)
    if #nodes == 0 then
        for _, candidate in ipairs(hvsSpacingCandidateTiles(target, s)) do
            if hvsClearBlockingPath(candidate, targetLive, 6) then
                s = playerState()
                nodes = hvsSpacingNodes(target, s)
                if #nodes > 0 then break end
            end
        end
    end
    if #nodes == 0 then
        local blocker = hvsFindSpacingBlocker(target, s)
        if blocker then
            deferForBlocker(blocker)
            return false
        end
        Hvs.PathStatus = ("Tidak ada tile spacing kosong di samping pohon (%d,%d)")
            :format(target.x, target.y)
        return false
    end

    -- Coba rute biasa lebih dulu agar pola gerak stabil. Jika A* menolak rute
    -- hanya karena batas jatuh 40 tile, ulangi dengan long-fall sebagai fallback.
    -- Game tidak memiliki fall damage; fallback ini hanya dipakai untuk mencapai
    -- tile berdiri di samping target, bukan untuk mengubah urutan harvest.
    local budget = math.max(8, tonumber(maxSec) or 10)
    local function tryNode(node, allowLongFall)
        if not targetLive() then return false end
        local current = playerState()
        local distance = current and (
            math.abs(node.x - current.x)
            + math.abs(node.y - (current.y - 0.475)) * 1.5
        ) or 0
        -- Timeout mengikuti jarak rute. Sebelumnya setiap percobaan dibatasi
        -- maksimum 10 detik dan budget dibagi 4, sehingga target jauh sering
        -- gagal sebelum avatar sempat mencapai tile spacing.
        local perTry = math.clamp(
            math.max(budget / (#nodes * 2), 4 + distance * 0.22),
            4,
            math.max(18, budget)
        )
        -- Coba jalan normal. Jika gagal, buka satu obstacle yang memang
        -- menghalangi lalu hitung ulang rute dari posisi aktual.
        for obstacleAttempt = 1, 3 do
            local ok = walkTo(node.x, node.y, perTry, targetLive, nil, allowLongFall)
            if ok then
                local after = playerState()
                if hvsAtSpacing(after, target.x, target.y) then
                    Hvs.PathStatus = nil
                    return true
                end
            end

            if not targetLive() then return false end
            local cleared = hvsClearBlockingPath(node, targetLive, math.min(6, perTry))
            if not cleared then break end
            task.wait(0.05)
        end
        return false
    end

    -- Pass 1: jalur normal untuk kedua sisi, tetap memprioritaskan sisi avatar.
    for _, node in ipairs(nodes) do
        if tryNode(node, false) then return true end
        if not targetLive() then return false end
    end

    -- Pass 2: fallback long-fall untuk kedua sisi. Tidak mengubah spacing 1 tile.
    Hvs.Status = ("Rute normal gagal ke (%d,%d), mencoba jalur alternatif...")
        :format(target.x, target.y)
    for _, node in ipairs(nodes) do
        if tryNode(node, true) then return true end
        if not targetLive() then return false end
    end

    -- Jika pohon di atas menutup ruang kepala, jangan tandai target bawah gagal.
    -- Jadikan pohon penghalang target prioritas, panen dulu, lalu coba target bawah.
    local blocker = hvsFindSpacingBlocker(target, playerState())
    if blocker and (blocker.x ~= target.x or blocker.y ~= target.y) then
        deferForBlocker(blocker)
        return false
    end

    Hvs.PathStatus = ("Gagal mencapai tile spacing (%d,%d), rute normal dan long-fall gagal")
        :format(target.x, target.y)
    return false
end

-- Naik ke tile bekas pohon yang baru dipanen. Prioritas pertama adalah tile
-- bekas pohon itu sendiri, lalu tile tetangga yang tetap memberi spacing 1 block.
local function hvsClimbToClearedRow(target, maxSec, live)
    local w = target and (target.world or Refs.World)
    if not target or not w or w ~= Refs.World then return false end
    local function targetLive()
        if not hvsLive() or Refs.World ~= w or hvsDropDue() then return false end
        if live and not live() then return false end
        return fgIdAt(target.x, target.y) == 0
    end
    if not targetLive() then return false end

    local current = playerState()
    if current and current.grounded and floor(current.y - 0.475) == target.y then
        return true
    end

    local dir = hvsRowDirection(target.y, w)
    local nodes, seen = {}, {}
    local function addNode(x)
        if x < 0 or x >= w.w or seen[x] then return end
        seen[x] = true
        if openAt(x, target.y) and realSupport(x, target.y) then
            nodes[#nodes + 1] = { x = x, y = target.y }
        end
    end
    addNode(target.x)
    addNode(target.x + dir)
    addNode(target.x - dir)
    if #nodes == 0 then return false end

    local budget = math.max(3, tonumber(maxSec) or 7)
    local perTry = math.max(2, budget / #nodes)
    for _, node in ipairs(nodes) do
        if not targetLive() then return false end
        Hvs.RowTransitionActive = true
        local ok, reached = pcall(walkTo, node.x, node.y, perTry, targetLive, nil, true)
        Hvs.RowTransitionActive = false
        if ok and reached then
            local after = playerState()
            if after and after.grounded and floor(after.y - 0.475) == target.y then
                return true
            end
        end
    end
    Hvs.RowTransitionActive = false
    return false
end

-- Callback gerak hanya menjadwalkan worker; tidak menunggu tryBreak di frame gerakan.
Hvs.MoveTick = function()
    if Hvs.RowSweepActive then return end
    if not hvsLive() or Hvs.Dropping or Hvs.RowTransitionActive or hvsDropDue() then return end
    local s = playerState()
    if not s or s.dead then return end
    if Session.Factory and Session.Factory.Harvesting then
        local tgt = Hvs.AdaptiveTarget
        if not tgt or floor(s.y - 0.475) ~= tgt.y then return end
        local rowDir = hvsRowDirection(tgt.y, Refs.World)
        if ((tgt.x + 0.5) - s.x) * rowDir < -1.5 then return end
    end
    hvsAdaptiveSpeed(s)
    if not s.grounded or Hvs.HarvestBusy or Hvs.HarvestWorkerBusy or Hvs.HarvestQueued
        or os.clock() < (Hvs.NextHarvestAt or 0) then return end

    Hvs.HarvestQueued = true
    task.spawn(function()
        Hvs.HarvestQueued = false
        if not hvsLive() or Hvs.Dropping or Hvs.RowTransitionActive or hvsDropDue() or Hvs.HarvestWorkerBusy then return end
        local current = playerState()
        if current and not current.dead and current.grounded then
            hvsRunWork(current)
        end
    end)
end

-- Callback dipanggil oleh frame() saat avatar bergerak, termasuk saat mengikuti
-- jalur A*. Inilah yang membuat pola menjadi jalan -> panen -> jalan -> panen.
-- (Eksekusi harvest berjalan di worker terpisah agar frame gerak tidak tersendat.)

-- Periksa tile yang dilewati di baris panen, mulai dari yang terdekat di belakang.
local function hvsMissBehind(w, row, trace)
    local s = playerState()
    if not s or s.dead or not s.grounded then return nil end
    local x, y = floor(s.x), floor(s.y - 0.475)
    if y ~= row then
        trace.x = nil
        return nil
    end

    local previous = trace.x
    trace.x = x
    if not previous or previous == x then return nil end
    local rowDir = hvsRowDirection(row, w)
    if (x - previous) * rowDir <= 0 then return nil end
    local step = previous < x and -1 or 1
    local now, serverTime = os.clock(), workspace:GetServerTimeNow()
    for col = x + step, previous, step do
        if col >= 0 and col < w.w then
            local idx = y * w.w + col
            local id = fgIdAt(col, y)
            if id ~= 0 and not skipped(Hvs.Skip, idx, now) then
                local readyAt = treeReadyAt(col, y, id)
                if readyAt and serverTime >= readyAt and canWorkAt(col, y) then
                    -- Jika avatar sudah melewati posisi satu-tile yang aman,
                    -- jadikan target recovery agar spacing diperbaiki sebelum hit.
                    if not hvsAtSpacing(s, col, y) then
                        return { x = col, y = y, idx = idx, id = id, world = w }
                    end
                end
            end
        end
    end
end

local function hvsRecover(target)
    Hvs.AdaptiveTarget = target
    local function live()
        return hvsLive() and Refs.World == target.world and not hvsDropDue()
    end
    if not live() then return false end

    local currentId = fgIdAt(target.x, target.y)
    if currentId == 0 or (target.id and currentId ~= target.id) then
        if currentId == 0 then hvsQueueCollectTarget(target) end
        return true
    end

    Hvs.Status = ("Mengatur spacing pohon (%d,%d)"):format(target.x, target.y)
    if not hvsMoveToSpacing(target, 35, live) then
        local blocker = Hvs.SpacingPriorityTarget
        if blocker and blocker.world == target.world
            and (blocker.x ~= target.x or blocker.y ~= target.y) then
            -- Target ini ditunda sementara; loop utama memproses pohon penghalang.
            return live()
        end
        if live() then skipTile(Hvs.Skip, target.idx, 1.5) end
        return live()
    end

    local s = playerState()
    if not live() or not hvsAtSpacing(s, target.x, target.y) then return live() end
    hvsRunWork(s, target)

    local function collectLive()
        return live() and Hvs.CollectOn and not hvsPickupBlocked()
    end
    if collectLive() and fgIdAt(target.x, target.y) == 0 then
        hvsQueueCollectTarget(target)
        Drops.waitSpawn({ target }, collectLive)
        if collectLive() then
            local tiles = {}
            for x = math.max(0, target.x - 1), math.min(target.world.w - 1, target.x + 1) do
                tiles[#tiles + 1] = { x = x, y = target.y }
                if target.y > 0 then tiles[#tiles + 1] = { x = x, y = target.y - 1 } end
            end
            Drops.touchAll(tiles, target.x, target.y, collectLive)
        end
    end
    return live()
end

-- Cari target panen berikutnya menurut urutan snake (seluruh world).
local function hvsScan(excludeState)
    local w = Refs.World
    if not w then return nil end
    local W, H = w.w, w.h
    local now, st = os.clock(), workspace:GetServerTimeNow()
    local best = nil
    local bestSkippedOnRow = nil
    local cmp = hvsOrder()
    local rowMap, rowCount = hvsRowMap(w)
    local skipBottomY = hvsBottomRowY(w)
    local factoryStrict = Session.Factory and Session.Factory.Harvesting == true
    local hasExcludeState = excludeState ~= nil
    local excludeY = excludeState and floor(excludeState.y - 0.475) or nil
    local excludeX = excludeState and excludeState.x or nil
    -- Saat avatar benar-benar berjalan horizontal, MoveTick memanen pohon
    -- dalam jangkauan. Saat berhenti, scan harus tetap memilih pohon lokal;
    -- jika tidak, target tersebut terlewat karena tidak ada frame gerak baru.
    local movingAlongRow = hasExcludeState and abs(tonumber(excludeState.vx) or 0) >= 2
    local scanDir = 1
    if excludeState then
        local rank = rowMap[excludeY] or (excludeY + 1)
        local rowRank = (Hvs.Order == "Atas ke Bawah") and (rank - 1) or (rowCount - rank)
        scanDir = (rowRank % 2 == 0) and 1 or -1
    end
    local function beforeCandidate(a, b)
        if factoryStrict then
            return cmp(a, b)
        end
        if excludeState then
            local function priority(t)
                if t.y == excludeY then return 0 end
                -- Row atas yang bisa dipanen langsung didahulukan daripada
                -- target jauh yang memaksa avatar berjalan mengitari farm.
                if hvsVerticalReach(excludeState, t) then return 1 end
                return 2
            end
            local pa, pb = priority(a), priority(b)
            if pa ~= pb then return pa < pb end
            if pa == 0 then
                if a.x ~= b.x then
                    return (a.x * scanDir) < (b.x * scanDir)
                end
                return false
            elseif pa == 1 then
                local da = abs(a.x + 0.5 - excludeX) + abs(a.y - excludeY) * 1.5
                local db = abs(b.x + 0.5 - excludeX) + abs(b.y - excludeY) * 1.5
                return da < db
            end
        end
        return cmp(a, b)
    end
    for y = 0, H - 1 do
        local row = (skipBottomY == nil or y ~= skipBottomY) and w.fg[y] or nil
        if row then
            for x = 0, W - 1 do
                local id = row[x] or 0
                if id ~= 0 then
                    local idx = y * W + x
                    if not skipped(Hvs.Skip, idx, now) then
                        local ra = treeReadyAt(x, y, id)
                        if ra and st >= ra then
                            local alreadyInMoveRange = movingAlongRow and y == excludeY
                                and hvsAtSpacing(excludeState, x, y)
                            if not alreadyInMoveRange then
                                if canWorkAt(x, y) then
                                    local t = { x = x, y = y, idx = idx, id = id, world = w }
                                    if not best or beforeCandidate(t, best) then best = t end
                                else
                                    skipTile(Hvs.Skip, idx, 120)
                                end
                            end
                        end
                    elseif excludeState and y == excludeY then
                        local skipUntil = Hvs.Skip[idx]
                        if skipUntil and (skipUntil - now) <= 3.0 then
                            local ra = treeReadyAt(x, y, id)
                            if ra and st >= ra and canWorkAt(x, y) then
                                local t = { x = x, y = y, idx = idx, id = id, world = w }
                                if not bestSkippedOnRow or beforeCandidate(t, bestSkippedOnRow) then
                                    bestSkippedOnRow = t
                                end
                            end
                        end
                    end
                end
            end
        end
    end
    if excludeState and bestSkippedOnRow and (not best or best.y ~= excludeY) then
        Hvs.Skip[bestSkippedOnRow.idx] = nil
        best = bestSkippedOnRow
    end
    Hvs.AdaptiveTarget = best
    return best
end

-- Jika semua pohon siap masih berada dalam jangkauan gerak, lakukan sapuan
-- beberapa tile ke arah target/urutan snake. MoveTick tetap memanen saat berjalan.
local function hvsSweepRow(s, preferred)
    local w = Refs.World
    if not w or not s or not s.grounded then return false end
    local y = floor(s.y - 0.475)
    if y < 0 or y >= w.h then return false end

    local map, count = hvsRowMap(w)
    local rank = map[y] or (y + 1)
    local rowRank = (Hvs.Order == "Atas ke Bawah") and (rank - 1) or (count - rank)
    -- Arah sapuan ditentukan oleh pola snake baris, bukan target terdekat
    -- yang bisa berubah-ubah pada setiap scan.
    local dir = (rowRank % 2 == 0) and 1 or -1

    local sx = floor(s.x)
    local tx = nil
    for step = 1, math.min(w.w, 12) do
        local x = sx + dir * step
        if x < 0 or x >= w.w then break end
        if openAt(x, y) and realSupport(x, y) then
            tx = x -- pilih waypoint terjauh yang masih aman dalam sapuan ini
        end
    end
    if not tx then return false end

    Hvs.Status = ("Menyusuri baris panen (%d,%d)"):format(tx, y)
    Hvs.AdaptiveTarget = preferred
    local missedTarget, trace = nil, {}
    Hvs.TravelLive = function()
        if not hvsLive() or Refs.World ~= w or hvsDropDue() or missedTarget then return false end
        missedTarget = hvsMissBehind(w, y, trace)
        return missedTarget == nil
    end
    local live = function()
        return hvsLive() and Refs.World == w and not hvsDropDue()
    end
    local ok = walkTo(tx, y, 15, live)
    Hvs.TravelLive = nil
    Hvs.ScanAt = 0
    return ok, missedTarget
end

-- Sapu baris datar secara kontinu dengan jarak berhenti ketat 1 tile di belakang
-- target (atau sisi berlawanan untuk pohon pojok), lalu langsung panen sesuai timing.
function Hvs.walkRowHarvest(w, initialTarget)
    if not w or w ~= Refs.World or not initialTarget or not hvsLive() then return false end
    local y = tonumber(initialTarget.y)
    if not y or y < 0 or y >= w.h then return false end
    local skipBottomY = hvsBottomRowY(w)
    if skipBottomY ~= nil and y == skipBottomY then return false end
    local s0 = playerState()
    if not s0 or s0.dead or not s0.grounded or floor(s0.y - 0.475) ~= y then return false end

    local dir = hvsRowDirection(y, w)
    local failCount = {}

    local function findNextOnRow(curX)
        local row = w.fg[y]
        if not row then return nil end
        local pending = Hvs.PendingTarget
        if pending and pending.world == w and pending.y == y then
            local pId = fgIdAt(pending.x, y)
            if pId ~= 0 and (not pending.id or pId == pending.id) and canWorkAt(pending.x, y) then
                return pending
            end
        end
        local now, st = os.clock(), workspace:GetServerTimeNow()
        local xStart = (dir > 0) and 0 or (w.w - 1)
        local xEnd = (dir > 0) and (w.w - 1) or 0
        for x = xStart, xEnd, dir do
            local id = row[x] or 0
            if id ~= 0 then
                local idx = y * w.w + x
                local skipUntil = Hvs.Skip[idx]
                local blockedSkip = false
                if skipUntil and skipUntil > now then
                    if (skipUntil - now) > 3.0 or (failCount[idx] or 0) >= 6 then
                        blockedSkip = true
                    elseif not curX or ((x + 0.5 - curX) * dir > 1.6) or os.clock() >= (Hvs.NextHarvestAt or 0) then
                        Hvs.Skip[idx] = nil
                    end
                end
                if not blockedSkip then
                    local ra = treeReadyAt(x, y, id)
                    if ra and st >= ra then
                        if canWorkAt(x, y) then
                            return { x = x, y = y, idx = idx, id = id, world = w }
                        else
                            skipTile(Hvs.Skip, idx, 120)
                        end
                    end
                end
            end
        end
        return nil
    end

    local function pickStandX(tx, curX)
        local isBehind = curX ~= nil and ((tx + 0.5 - curX) * dir < -0.1)
        local order = isBehind and { tx + dir, tx - dir } or { tx - dir, tx + dir }
        for _, sx in ipairs(order) do
            if sx >= 0 and sx < w.w and openAt(sx, y) and realSupport(sx, y)
                and not Move.isForbiddenFloor1Right(w, sx, y) then
                return sx
            end
        end
        return nil
    end

    local function corridorOk(fromX, toX)
        local lo, hi = math.min(fromX, toX), math.max(fromX, toX)
        for x = lo, hi do
            if not openAt(x, y) or not realSupport(x, y)
                or Move.isForbiddenFloor1Right(w, x, y) then
                return false
            end
        end
        return true
    end

    local initStandX = pickStandX(initialTarget.x, s0.x)
    if not initStandX or not corridorOk(floor(s0.x), initStandX) then
        return false
    end

    Hvs.RowSweepActive = true
    local startHarvested = Hvs.Harvested or 0
    local didAny = false
    local lastProgressAt = os.clock()
    local lastTargetX = nil
    local lastHarvestCount = startHarvested
    local settleUntil = nil
    local bestGoalDist = nil

    local okLoop, loopErr = pcall(function()
        while frame() do
            if not hvsLive() or Refs.World ~= w or hvsDropDue() then break end
            local s = playerState()
            if not s or s.dead or not s.grounded or floor(s.y - 0.475) ~= y then break end

            AutoInput.speed = math.clamp(tonumber(Misc.Speed) or 100, 50, 500)

            local front = findNextOnRow(s.x)
            if not front then
                AutoInput.left, AutoInput.right = false, false
                lastProgressAt = os.clock()
                bestGoalDist = nil
                if Hvs.HarvestBusy or Hvs.HarvestWorkerBusy or Hvs.HarvestQueued then
                    settleUntil = nil
                    Hvs.Status = ("Menyelesaikan panen terakhir di baris %d..."):format(y)
                else
                    if not settleUntil then
                        settleUntil = os.clock() + 0.45
                        Hvs.Status = ("Verifikasi baris %d sebelum pindah floor..."):format(y)
                    end
                    if os.clock() >= settleUntil then
                        Hvs.FloorVerifiedY = y
                        didAny = true
                        break
                    end
                end
            else
                settleUntil = nil
                Hvs.FloorVerifiedY = nil

                local standX = pickStandX(front.x, s.x)
                if not standX or not corridorOk(floor(s.x), standX) then
                    break
                end

                Hvs.AdaptiveTarget = front
                local curHarvested = Hvs.Harvested or 0
                if curHarvested > startHarvested then
                    didAny = true
                end

                local goalCx = standX + 0.5
                local distToGoal = abs(goalCx - s.x)
                if front.x ~= lastTargetX or curHarvested ~= lastHarvestCount then
                    lastTargetX = front.x
                    lastHarvestCount = curHarvested
                    lastProgressAt = os.clock()
                    bestGoalDist = distToGoal
                elseif bestGoalDist == nil or distToGoal < bestGoalDist - 0.35 then
                    bestGoalDist = distToGoal
                    lastProgressAt = os.clock()
                elseif os.clock() - lastProgressAt > 3.5 then
                    break
                end

                steerX(s, goalCx, 0.12)

                if hvsAtSpacing(s, front.x, y)
                    and not Hvs.HarvestBusy and not Hvs.HarvestWorkerBusy and not Hvs.HarvestQueued
                    and os.clock() >= (Hvs.NextHarvestAt or 0) then
                    Hvs.HarvestQueued = true
                    local hitTarget = front
                    task.spawn(function()
                        Hvs.HarvestQueued = false
                        if not hvsLive() or Refs.World ~= w or hvsDropDue() or Hvs.HarvestWorkerBusy then return end
                        local cur = playerState()
                        if cur and not cur.dead and cur.grounded and hvsAtSpacing(cur, hitTarget.x, y) then
                            local beforeCount = Hvs.Harvested or 0
                            hvsRunWork(cur, hitTarget)
                            if fgIdAt(hitTarget.x, y) == 0 then
                                failCount[hitTarget.idx] = nil
                            elseif (Hvs.Harvested or 0) == beforeCount
                                and not (Hvs.PendingTarget and Hvs.PendingTarget.idx == hitTarget.idx) then
                                failCount[hitTarget.idx] = (failCount[hitTarget.idx] or 0) + 1
                                if failCount[hitTarget.idx] >= 6 then
                                    skipTile(Hvs.Skip, hitTarget.idx, 10)
                                end
                            end
                        end
                    end)
                    didAny = true
                elseif not Hvs.HarvestBusy then
                    if ((front.x + 0.5 - s.x) * dir) < -0.1 then
                        Hvs.Status = ("Balik panen pohon terlewat (%d,%d)"):format(front.x, y)
                    else
                        Hvs.Status = ("Menyusuri baris (%d,%d)"):format(front.x, y)
                    end
                end
            end
        end
    end)

    Hvs.RowSweepActive = false
    AutoInput.speed = nil
    releaseInput()
    if not okLoop and os.clock() - (Hvs.LastWorkerErrorAt or -10) >= 10 then
        Hvs.LastWorkerErrorAt = os.clock()
        warn("[ByteHub] Auto Harvest row sweep: " .. tostring(loopErr))
    end
    return didAny
end

local function hvsLoop(runId)
    Hvs.Guard = 0
    table.clear(Hvs.Skip)
    table.clear(HvsFail)
    Hvs.KindScanAt = 0
    if not hvsPickupBlocked() then
        table.clear(Hvs.DropBlock)
        Hvs.MarkWorld = nil
        Hvs.MarkX, Hvs.MarkY, Hvs.MarkUntil, Hvs.MarkNext = -1, -1, 0, 0
    end
    Hvs.RowRank, Hvs.RowRankWorld, Hvs.RowCount = nil, nil, 0
    Hvs.SpacingPriorityTarget = nil
    Hvs.SpacingResumeTarget = nil
    Hvs.SpacingDependencyTarget = nil
    Hvs.RowTransitionTarget = nil
    Hvs.RowTransitionActive = false
    autoBegin()
    local missed
    while hvsLive() and Hvs.RunId == runId do
        task.wait()
        if not hvsLive() or Hvs.RunId ~= runId then break end
        local w = Refs.World
        local s = playerState()
        if not w or not s or s.dead then
            releaseInput()
            Hvs.Status = "Menunggu karakter / world..."
            task.wait(0.5)
        elseif not s.grounded then
            releaseInput()
            Move.airCheck(s)
            task.wait()
        else
            releaseInput()
            Move.AirAt = nil
            -- Setelah drop berhasil tetapi rute pulang terhalang, prioritaskan
            -- kembali ke titik panen. Jangan jalankan scan/punch dari tile drop.
            local returnTarget = Hvs.DropReturnTarget
            if returnTarget then
                if returnTarget.world ~= Refs.World
                    or returnTarget.worldName ~= Guard.worldName() then
                    Hvs.DropReturnTarget = nil
                    Hvs.DropRecovery = nil
                    Hvs.Dropping = false
                    Hvs.DropStatus = "World berubah; titik pulang dibatalkan"
                else
                    Hvs.Dropping = true
                    Hvs.DropStatus = ("Mencoba kembali ke posisi panen (%d,%d)...")
                        :format(returnTarget.x, returnTarget.y)
                    local returnLive = function()
                        return hvsLive() and Refs.World == returnTarget.world
                            and Guard.worldName() == returnTarget.worldName
                    end
                    -- Rescan A* dari posisi aktual setiap percobaan. Drop hasil
                    -- panen telah diproteksi oleh UID/jendela pickup, jadi tidak
                    -- perlu memasukkan drop list sebagai obstacle navigasi.
                    local returned, returnWhy = walkTo(returnTarget.x, returnTarget.y, 45,
                        returnLive, nil, true, true)
                    if returned and returnLive() then
                        Hvs.DropReturnTarget = nil
                        Hvs.DropRecovery = nil
                        Hvs.Dropping = false
                        Hvs.DropStatus = "Berhasil kembali ke posisi panen"
                        Hvs.DropNextTry = 0
                    else
                        Hvs.DropStatus = returnWhy or "Rute pulang belum berhasil; akan mencoba lagi"
                        releaseInput()
                        task.wait(0.75)
                    end
                    continue
                end
            end
            -- Jangan pilih target / mulai rute baru ketika worker MoveTick sedang
            -- menyelesaikan satu pohon. Ini mencegah target saling menyalip.
            if Hvs.HarvestWorkerBusy or Hvs.HarvestQueued then
                Hvs.Status = "Menyelesaikan satu proses harvest..."
                task.wait(0.02)
                continue
            end
            hvsRefreshKinds(w)
            -- drop hasil Auto Drop bisa muncul terlambat dari server: tandai berkala
            -- selama jendela MarkUntil supaya collector tidak memungutnya.
            if os.clock() < (Hvs.MarkUntil or 0) and os.clock() >= (Hvs.MarkNext or 0) then
                Hvs.MarkNext = os.clock() + 0.3
                hvsMarkDropped(Hvs.MarkX, Hvs.MarkY, Hvs.MarkUntil)
            end
            -- world bisa berganti: pastikan hook pickup masih menempel di World aktif.
            if os.clock() < (Hvs.PickupUntil or 0) then
                local curTake = rawget(w, "takeDrop")
                if type(curTake) == "function" and curTake ~= Hvs.PickupFn then hvsHookPickup() end
            end
            -- Saat stok penuh, drop diprioritaskan sampai berhasil atau Auto Drop dimatikan.
            if hvsDropDue() then
                if os.clock() >= (Hvs.DropNextTry or 0) then
                    -- Isolasi error transaksi drop. Error saat drop/return tidak boleh
                    -- meruntuhkan seluruh hvsLoop dan mematikan Auto Harvest.
                    local callOk, ok, why = pcall(hvsDropTrip)
                    if not callOk then
                        local errText = tostring(ok)
                        Hvs.DropError = errText
                        Hvs.DropStatus = "Error saat Auto Drop; memulihkan posisi"
                        warn("[ByteHub] Auto Harvest drop transaction: " .. errText)
                    elseif not ok then
                        if why then Hvs.DropStatus = why end
                    else
                        Hvs.DropError = nil
                        Hvs.DropNextTry = 0
                    end

                    if not callOk or not ok then
                        -- Bersihkan state gerak yang mungkin tertinggal oleh error.
                        Hvs.DropLive = nil
                        Move.Homing, Move.HomingLive, Move.HomingRoute = false, nil, nil
                        releaseInput()
                        autoEnd()

                        -- Jika avatar sudah meninggalkan titik asal, prioritaskan
                        -- kembali ke snapshot sebelum mencoba drop lagi / panen.
                        local recovery = Hvs.DropRecovery
                        if recovery and recovery.world == Refs.World
                            and recovery.worldName == Guard.worldName() then
                            local current = playerState()
                            local cx, cy
                            if current and not current.dead and current.grounded then
                                cx, cy = startNode(current)
                            end
                            if cx ~= recovery.x or cy ~= recovery.y then
                                Hvs.DropReturnTarget = Hvs.DropReturnTarget or {
                                    x = recovery.x, y = recovery.y,
                                    world = recovery.world, worldName = recovery.worldName,
                                    zones = {},
                                }
                                Hvs.Dropping = true
                                Hvs.DropStatus = Hvs.DropStatus .. "; kembali ke posisi panen"
                            else
                                Hvs.DropRecovery = nil
                                Hvs.Dropping = false
                            end
                        else
                            Hvs.DropRecovery = nil
                            Hvs.Dropping = false
                        end
                        Hvs.DropNextTry = os.clock() + 3
                    end
                end
                continue
            end
            -- Jangan scan / bergerak / memukul sebelum tabel waktu tanam tersedia.
            -- Pada world yang baru dimuat, discovery pertama bisa terlalu dini.
            if not hvsTreeRefsReady(w) then
                hvsRetryTreeRefs(runId)
                releaseInput()
                if not Hvs.TreeRefSearching then
                    Hvs.Status = Refs.Trees
                        and ("Menunggu timestamp pohon (%d/%d)...")
                            :format(Hvs.TreeRefTimestampCount or 0, Hvs.TreeRefSeedCount or 0)
                        or "Menunggu data waktu tanam pohon..."
                end
                task.wait(0.12)
                continue
            end
            if missed then
                if missed.world ~= w or hvsRecover(missed) then missed = nil end
                Hvs.ScanAt = 0
                continue
            end
            -- Sesudah harvest vertikal berhasil, naik melalui tile yang baru
            -- kosong. Tile itu menjadi pijakan satu tile dari pohon tetangga.
            local rowTransition = Hvs.RowTransitionTarget
            if rowTransition then
                local transitionId = rowTransition.world == w
                    and fgIdAt(rowTransition.x, rowTransition.y) or nil
                if rowTransition.world ~= w or transitionId ~= 0 then
                    Hvs.RowTransitionTarget = nil
                else
                    local currentRow = floor(s.y - 0.475)
                    if currentRow == rowTransition.y then
                        Hvs.RowTransitionTarget = nil
                    else
                        local climbLive = function()
                            return hvsLive() and Refs.World == w and not hvsDropDue()
                                and rowTransition.world == w
                                and fgIdAt(rowTransition.x, rowTransition.y) == 0
                        end
                        Hvs.Status = ("Naik ke row %d melalui tile (%d,%d)...")
                            :format(rowTransition.y, rowTransition.x, rowTransition.y)
                        local climbed = hvsClimbToClearedRow(rowTransition, 7, climbLive)
                        local afterClimb = playerState()
                        if climbed and afterClimb and afterClimb.grounded
                            and floor(afterClimb.y - 0.475) == rowTransition.y then
                            Hvs.RowTransitionTarget = nil
                            Hvs.ScanAt = 0
                            Hvs.Status = "Berhasil naik, melanjutkan spacing 1 tile"
                        else
                            Hvs.Status = "Menunggu jalur naik ke row atas..."
                            task.wait(0.25)
                        end
                        continue
                    end
                end
            end
            -- Harvest pertama boleh dilakukan dari posisi awal. Setelah itu,
            -- prioritaskan mencari target di luar jangkauan gerak agar avatar
            -- berjalan dan MoveTick memanen pohon yang dilewati.
            local harvested, failed = 0, nil
            if (Hvs.Harvested or 0) == 0 and not (Session.Factory and Session.Factory.Harvesting) then
                harvested, failed = hvsRunWork(s)
            end
            if failed then
                missed = failed
                continue
            end
            if harvested > 0 then
                Hvs.Guard = 0
                Hvs.ScanAt = 0
            else
                -- Scan cepat (real-time) agar pohon yang baru matang atau terlewat langsung terdeteksi.
                local now = os.clock()
                if now < (Hvs.ScanAt or 0) then
                    task.wait(0.05)
                    continue
                end
                Hvs.ScanAt = now + 0.05
                local moveFirst = (Hvs.Harvested or 0) > 0 or Hvs.PendingTarget ~= nil
                local pending = Hvs.PendingTarget
                if pending then
                    local pendingId = (pending.world == w) and fgIdAt(pending.x, pending.y) or nil
                    if pending.world ~= w or pendingId == 0
                        or (pending.id and pendingId ~= pending.id) then
                        if pending.world == w and pendingId == 0 then hvsQueueCollectTarget(pending) end
                        Hvs.PendingTarget = nil
                        pending = nil
                    end
                end

                -- Setelah pohon penghalang hilang, lanjutkan target awal yang
                -- sempat ditunda. Ini juga menangani blocker yang dipanen manual
                -- atau oleh MoveTick, bukan hanya oleh worker utama.
                local dependency = Hvs.SpacingDependencyTarget
                if dependency then
                    local dependencyId = dependency.world == w
                        and fgIdAt(dependency.x, dependency.y) or 0
                    if dependency.world ~= w or dependencyId == 0
                        or (dependency.id and dependencyId ~= dependency.id) then
                        Hvs.SpacingDependencyTarget = nil
                        Hvs.SpacingPriorityTarget = nil
                        local resume = Hvs.SpacingResumeTarget
                        Hvs.SpacingResumeTarget = nil
                        if resume and resume.world == w then
                            local resumeId = fgIdAt(resume.x, resume.y)
                            if resumeId ~= 0 and (not resume.id or resumeId == resume.id) then
                                Hvs.PendingTarget = resume
                                pending = resume
                            end
                        end
                    elseif not pending then
                        local readyAt = treeReadyAt(dependency.x, dependency.y, dependencyId)
                        if readyAt and workspace:GetServerTimeNow() >= readyAt
                            and canWorkAt(dependency.x, dependency.y)
                            and not Hvs.SpacingPriorityTarget then
                            Hvs.SpacingPriorityTarget = dependency
                        end
                    end
                end

                if pending then
                    Hvs.AdaptiveTarget = pending
                    if not hvsAtSpacing(s, pending.x, pending.y)
                        and not hvsVerticalReach(s, pending) then
                        Hvs.Status = "Mengembalikan spacing target harvest..."
                        local aligned = hvsMoveToSpacing(pending, 35, function()
                            return hvsLive() and Refs.World == w and not hvsDropDue()
                        end)
                        if not aligned then
                            local blocker = Hvs.SpacingPriorityTarget
                            if blocker and blocker.world == w
                                and (blocker.x ~= pending.x or blocker.y ~= pending.y) then
                                -- Jangan continue di sini. Biarkan blok prioritas di
                                -- bawah memproses blocker, bukan mengulang pending.
                                pending = nil
                            else
                                Hvs.Status = "Menunggu tile kosong dengan spacing 1 block..."
                                task.wait(0.15)
                                continue
                            end
                        else
                            task.wait(0.03)
                            continue
                        end
                    end
                    if pending then
                        local waitLeft = (Hvs.NextHarvestAt or 0) - os.clock()
                        if waitLeft > 0 then
                            Hvs.Status = "Menjaga spacing dan lock harvest..."
                            task.wait(math.min(waitLeft, 0.05))
                            continue
                        end
                        local retried = hvsRunWork(s, pending)
                        if retried > 0 then
                            Hvs.Guard = 0
                            Hvs.ScanAt = 0
                        end
                        task.wait(0.03)
                        continue
                    end
                end
                local target = pending and {
                    x = pending.x, y = pending.y, idx = pending.idx,
                    id = pending.id or fgIdAt(pending.x, pending.y), world = w,
                } or hvsScan(s)
                if not target and (Hvs.TreeRefMissingCount or 0) > 0 then
                    hvsRetryTreeRefs(runId, true)
                end
                if target then Hvs.AdaptiveTarget = target end
                if not target and moveFirst then
                    -- Fallback lokal: jika ada pohon di baris saat ini tetapi avatar
                    -- belum berada satu tile di sampingnya, atur spacing dahulu.
                    local localTarget = hvsScan()
                    local currentY = floor(s.y - 0.475)
                    if localTarget and localTarget.y == currentY
                        and stateReaches(s, localTarget.x, localTarget.y, farmReach() - 0.08) then
                        Hvs.AdaptiveTarget = localTarget
                        if not hvsAtSpacing(s, localTarget.x, localTarget.y) then
                            Hvs.Status = ("Mengatur jarak 1 block ke (%d,%d)"):format(localTarget.x, localTarget.y)
                            local okSpacing = hvsMoveToSpacing(localTarget, 10, function()
                                return hvsLive() and Refs.World == w and not hvsDropDue()
                            end)
                            if not okSpacing and hvsLive() then
                                local blocker = Hvs.SpacingPriorityTarget
                                if not (blocker and blocker.world == w
                                    and (blocker.x ~= localTarget.x or blocker.y ~= localTarget.y)) then
                                    skipTile(Hvs.Skip, localTarget.idx, 1.5)
                                end
                            end
                            Hvs.ScanAt = 0
                            continue
                        end

                        local waitLeft = (Hvs.NextHarvestAt or 0) - os.clock()
                        if waitLeft > 0 then
                            Hvs.Status = "Menjaga spacing dan jeda panen..."
                            task.wait(math.min(waitLeft, 0.05))
                            continue
                        end
                        local localHarvest = hvsRunWork(s, localTarget)
                        if localHarvest > 0 then
                            Hvs.Guard = 0
                            Hvs.ScanAt = 0
                        end
                        task.wait(0.03)
                        continue
                    end
                    target = hvsScan(s)
                end

                -- Pohon matang yang menutup ruang kepala diproses sebelum target bawah.
                if not pending and Hvs.SpacingPriorityTarget then
                    local priority = Hvs.SpacingPriorityTarget
                    local priorityId = priority.world == w and fgIdAt(priority.x, priority.y) or 0
                    local readyAt = priorityId ~= 0 and treeReadyAt(priority.x, priority.y, priorityId)
                    if priorityId ~= 0 and (not priority.id or priority.id == priorityId)
                        and readyAt and workspace:GetServerTimeNow() >= readyAt
                        and canWorkAt(priority.x, priority.y) then
                        target = priority
                        Hvs.SpacingPriorityTarget = nil
                        Hvs.AdaptiveTarget = priority
                    else
                        Hvs.SpacingPriorityTarget = nil
                    end
                end

                if hvsDropDue() then continue end
                if target then
                    Hvs.Guard += 1
                    local curRowY = floor(s.y - 0.475)
                    if s.grounded and target.y == curRowY then
                        Hvs.FloorVerifiedY = nil
                    elseif s.grounded and target.y ~= curRowY
                        and Hvs.FloorVerifiedY ~= curRowY
                        and curRowY ~= hvsBottomRowY(w) then
                        releaseInput()
                        Hvs.Status = ("Memastikan floor %d bersih sebelum pindah..."):format(curRowY)
                        local waitBusy = os.clock() + 1.0
                        while hvsLive() and Refs.World == w and not hvsDropDue()
                            and (Hvs.HarvestBusy or Hvs.HarvestWorkerBusy or Hvs.HarvestQueued)
                            and os.clock() < waitBusy do
                            task.wait(0.05)
                        end
                        local settleEnd = os.clock() + 0.45
                        while hvsLive() and Refs.World == w and not hvsDropDue() and os.clock() < settleEnd do
                            task.wait(0.05)
                        end
                        Hvs.FloorVerifiedY = curRowY
                        Hvs.ScanAt = 0
                        continue
                    end
                    -- Panen dulu pohon row atas jika masih masuk jangkauan dan
                    -- tidak tertutup block. Setelah berhasil, loop akan naik ke
                    -- tile yang baru dikosongkan lalu spacing normal dilanjutkan.
                    if hvsVerticalReach(s, target) then
                        Hvs.Status = ("Memanen row atas (%d,%d) sebelum naik..."):format(target.x, target.y)
                        local verticalHarvested, verticalFailed = hvsRunWork(s, target)
                        if verticalFailed then missed = verticalFailed end
                        if verticalHarvested > 0 then
                            Hvs.Guard = 0
                            Hvs.ScanAt = 0
                        end
                        task.wait(0.03)
                        continue
                    end
                    if s.grounded and floor(s.y - 0.475) == target.y then
                        local swept = Hvs.walkRowHarvest(w, target)
                        if swept then
                            Hvs.Guard = 0
                            Hvs.ScanAt = 0
                            continue
                        end
                    end
                    Hvs.Status = ("Mengatur spacing ke pohon (%d,%d)"):format(target.x, target.y)
                    local trace = {}
                    Hvs.TravelLive = function()
                        if not hvsLive() or Refs.World ~= w or hvsDropDue() or missed then return false end
                        missed = hvsMissBehind(w, target.y, trace)
                        return missed == nil
                    end
                    local reachedSpacing = hvsMoveToSpacing(target, 35, function()
                        return hvsLive() and Refs.World == w and not hvsDropDue()
                            and not missed
                    end)
                    Hvs.TravelLive = nil
                    Hvs.ScanAt = 0
                    local afterState = playerState()
                    if reachedSpacing and afterState
                        and hvsAtSpacing(afterState, target.x, target.y) then
                        if fgIdAt(target.x, target.y) ~= 0 and (Hvs.NextHarvestAt or 0) > os.clock() then
                            local waitLeft = (Hvs.NextHarvestAt or 0) - os.clock()
                            if waitLeft > 0 then
                                task.wait(math.min(waitLeft, 0.5))
                                afterState = playerState()
                            end
                        end
                        if hvsLive() and Refs.World == w and not hvsDropDue()
                            and afterState and hvsAtSpacing(afterState, target.x, target.y) then
                            -- walkTo dapat selesai karena avatar sudah berada tepat di
                            -- tile spacing. Dalam kasus itu tidak ada frame gerak untuk
                            -- memicu MoveTick, jadi jalankan satu harvest secara langsung.
                            local directHarvested, directFailed = hvsRunWork(afterState, target)
                            if directFailed then missed = directFailed end
                            if directHarvested > 0 then
                                Hvs.Guard = 0
                                Hvs.ScanAt = 0
                            end
                        end
                    end
                    if not reachedSpacing or not (afterState and hvsAtSpacing(afterState, target.x, target.y)) then
                        local blocker = Hvs.SpacingPriorityTarget
                        if not (blocker and blocker.world == w
                            and (blocker.x ~= target.x or blocker.y ~= target.y)) then
                            -- Jangan skip target bawah jika sedang menunggu penghalang dipanen.
                            skipTile(Hvs.Skip, target.idx, 1.5)
                        end
                    end
                    if missed or hvsDropDue() then continue end
                    if Hvs.Guard > 60 then
                        Hvs.Status = Hvs.PathStatus or "Tidak ada pohon siap yang terjangkau, memindai ulang jalur..."
                        Hvs.Guard = 0
                        Hvs.ScanAt = 0
                        task.wait(0.25)
                    end
                else
                    Hvs.Guard = 0
                    Hvs.Status = "Menunggu pohon siap..."
                    task.wait(0.2)
                end
            end
        end
    end
    releaseInput()
end

function Hvs.start()
    if Hvs.Running then return nil end
    if Hvs.WorkerActive or Hvs.HarvestWorkerBusy then return "Tunggu proses Auto Harvest sebelumnya selesai." end
    local err = checkAutoStart()
    if err then return err end
    if not Refs.Trees then findTreeRefs() end
    if State.Running then stopFarm("Dihentikan karena Auto Harvest dimulai") end
    if Clear.Running then stopClear("Dihentikan karena Auto Harvest dimulai") end
    if Splice.Running and Splice.stop then Splice.stop("Dihentikan karena Auto Harvest dimulai") end
    if Pabrik.Running then Pabrik.stop("Dihentikan karena Auto Harvest dimulai") end
    if Build.Running then Build.stop("Dihentikan karena Auto Harvest dimulai") end
    if Vend.Running and Vend.stop then Vend.stop("Dihentikan karena Auto Harvest dimulai") end
    if Session.Factory and Session.Factory.Running and not Session.Factory.Harvesting and Session.Factory.stop then
        Session.Factory.stop("Dihentikan karena Auto Harvest dimulai")
    end
    if stopAutoPlant then stopAutoPlant("Dihentikan karena Auto Harvest dimulai") end
    Hvs.Harvested, Hvs.Collected, Hvs.Dropped, Hvs.SeedDropped = 0, 0, 0, 0
    Hvs.CollectBase = State.Collected
    Hvs.NextHarvestAt, Hvs.PendingTarget = 0, nil
    Hvs.RowTransitionTarget, Hvs.RowTransitionActive = nil, false
    Hvs.RowSweepActive = false
    Hvs.FloorVerifiedY = nil
    Hvs.PathStatus = nil
    Hvs.HarvestBusy, Hvs.HarvestLock, Hvs.AdaptiveTarget = false, nil, nil
    Hvs.HarvestQueued = false
    table.clear(Hvs.PendingCollect)
    Hvs.SpeedBefore = AutoInput.speed
    Hvs.SpeedCurrent = math.clamp(tonumber(Misc.Speed) or 100, 50, 500)
    Hvs.SpeedUpdateAt = os.clock()
    Hvs.Guard, Hvs.ScanAt, Hvs.DropNextTry = 0, 0, 0
    Hvs.RowRank, Hvs.RowRankWorld, Hvs.RowCount = nil, nil, 0
    Hvs.TreeRefAttempts = 0
    Hvs.TreeRefForceDeep = false
    Hvs.TreeRefCheckAt, Hvs.TreeRefCheckWorld, Hvs.TreeRefCheckResult = 0, nil, nil
    hvsHeapScanWorld, hvsHeapScanAt = nil, 0
    Hvs.TreeRefRetryAt = os.clock() + 1.5
    Hvs.Status = "Memvalidasi data waktu tanam pohon..."
    Hvs.DropError = nil
    Hvs.DropRecovery = nil
    Hvs.DropReturnTarget = nil
    local dropEnabled = Hvs.DropOn or Hvs.DropSeedOn
    Hvs.DropStatus = dropEnabled and (Hvs.DropX >= 0 and "Siap" or "Tile drop belum diatur") or "Mati"
    Hvs.DropSeedStatus = Hvs.DropSeedOn and "Menunggu seed mencapai 200" or "Mati"
    Hvs.On, Hvs.Running, Hvs.WorkerActive = true, true, true
    Hvs.RunId = (Hvs.RunId or 0) + 1
    local id = Hvs.RunId
    task.spawn(function()
        local ok, e = pcall(hvsLoop, id)
        if not ok then warn("[ByteHub] Auto Harvest error: " .. tostring(e)) end
        Hvs.WorkerActive = false
        if Hvs.RunId == id and Hvs.Running then
            Hvs.stop(not ok and "Error Auto Harvest" or nil)
        end
    end)
    return nil
end

function Hvs.stop(reason)
    local was = Hvs.Running
    Hvs.Running = false
    Hvs.On = false
    Hvs.TravelLive = nil
    Hvs.RowTransitionTarget, Hvs.RowTransitionActive = nil, false
    Hvs.RowSweepActive = false
    Hvs.FloorVerifiedY = nil
    Hvs.Guard = 0
    Hvs.ScanAt = 0
    Hvs.Dropping = false
    Hvs.DropReturnTarget = nil
    Hvs.DropRecovery = nil
    if Hvs.DropLive and Move.HomingLive == Hvs.DropLive then
        Move.Homing, Move.HomingLive, Move.HomingRoute = false, nil, nil
    end
    Hvs.DropLive = nil
    Hvs.HarvestBusy, Hvs.HarvestLock, Hvs.AdaptiveTarget = false, nil, nil
    Hvs.HarvestQueued = false
    Hvs.SpeedCurrent, Hvs.SpeedUpdateAt = nil, 0
    AutoInput.speed = Hvs.SpeedBefore
    Hvs.SpeedBefore = nil
    Hvs.RowRank, Hvs.RowRankWorld, Hvs.RowCount = nil, nil, 0
    autoEnd()
    releaseInput()
    if was then
        if UI.HarvestToggle then pcall(function() UI.HarvestToggle:Set(false, true) end) end
        if reason then
            Hvs.Status = "Berhenti: " .. tostring(reason)
            notify("Auto Harvest", Hvs.Status, 4)
        end
    end
end

function Hvs.readyCount()
    local w = Refs.World
    if not w then return 0, 0 end
    local skipBottomY = hvsBottomRowY(w)
    local st = workspace:GetServerTimeNow()
    local ready, total = 0, 0
    for y = 0, w.h - 1 do
        local row = (skipBottomY == nil or y ~= skipBottomY) and w.fg[y] or nil
        if row then
            for x = 0, w.w - 1 do
                local id = row[x] or 0
                if id ~= 0 then
                    local ra = treeReadyAt(x, y, id)
                    if ra then
                        total += 1
                        if st >= ra then ready += 1 end
                    end
                end
            end
        end
    end
    return ready, total
end

Auto.startHarvest = Hvs.start
Auto.stopHarvest = Hvs.stop
Auto.harvestReadyCount = Hvs.readyCount
Harvest.start = Hvs.start
Harvest.stop = Hvs.stop
Harvest.readyCount = Hvs.readyCount
executorEnv.__harvestStop = Hvs.stop -- dipakai Auto Plant (di luar mount) untuk eksklusif

--// --- FACTORY (siklus Harvest bawah -> PnB jarak aman -> Auto Drop Seed -> Auto Plant) ---
do (function() -- fungsi sendiri: variabel di dalam tidak ikut batas 200 local
    local F = Session.Factory
    local DEFAULT_ROT_LOADER_URL = "https://raw.githubusercontent.com/brbrpatapimm/plerr/main/NewUI_Second_95.lua"
    local ROT_FOLDER = "ByteHub"
    local ROT_FILE = ROT_FOLDER .. "/factory_rotation_" .. tostring(LocalPlayer and LocalPlayer.UserId or 0) .. ".json"
    local ROT_TELEPORT_KEY = "ByteHub.FactoryRotation.v1"

    local function normalizeRotationWorld(name)
        return tostring(name or ""):upper():gsub("[^A-Z0-9]", "")
    end

    local function parseRotationWorlds(raw)
        local text = tostring(raw or "")
        local out, seen = {}, {}
        for token in text:gmatch("[^,%s;]+") do
            local clean = normalizeRotationWorld(token)
            if clean ~= "" and not seen[clean] then
                seen[clean] = true
                out[#out + 1] = clean
            end
        end
        return out
    end

    local function nextRotationWorld(currentWorld)
        local worlds = parseRotationWorlds(F.RotationWorldsText)
        if #worlds == 0 then return nil, 0 end
        local cur = normalizeRotationWorld(currentWorld)
        if #worlds == 1 then
            if worlds[1] ~= cur then return worlds[1], 1 end
            return nil, 1
        end
        for i, wn in ipairs(worlds) do
            if wn == cur then
                local nextIdx = (i % #worlds) + 1
                return worlds[nextIdx], nextIdx
            end
        end
        local idx = ((math.max(1, math.floor(tonumber(F.RotationIndex) or 1)) - 1) % #worlds) + 1
        if worlds[idx] == cur then
            idx = (idx % #worlds) + 1
        end
        return worlds[idx], idx
    end

    local function ensureRotFolder()
        if type(isfolder) == "function" and type(makefolder) == "function" then
            local ok, exists = pcall(isfolder, ROT_FOLDER)
            if ok and not exists then pcall(makefolder, ROT_FOLDER) end
        end
    end

    local function saveRotationPending(targetWorld, nextIdx)
        local target = normalizeRotationWorld(targetWorld)
        if target == "" then return false end
        local payload = {
            Schema = 1,
            UserId = LocalPlayer and LocalPlayer.UserId or 0,
            PlaceId = game.PlaceId,
            TargetWorld = target,
            RotationIndex = math.max(1, math.floor(tonumber(nextIdx) or 1)),
            RotationWorldsText = tostring(F.RotationWorldsText or ""),
            RotationOn = true,
            RotationDelaySec = math.clamp(math.floor(tonumber(F.RotationDelaySec) or 3), 1, 15),
            DropX = tonumber(F.DropX) or -1,
            DropY = tonumber(F.DropY) or -1,
            DropFacing = (tonumber(F.DropFacing) or 1) < 0 and -1 or 1,
            DropGuardSec = tonumber(F.DropGuardSec) or 2.5,
            SafeDist = tonumber(F.SafeDist) or 3,
            BlockLimit = tonumber(F.BlockLimit) or 200,
            SeedDropAt = tonumber(F.SeedDropAt) or 200,
            CreatedAt = os.time(),
        }
        local fileSaved = false
        if type(writefile) == "function" then
            ensureRotFolder()
            local okEnc, encoded = pcall(HttpService.JSONEncode, HttpService, payload)
            if okEnc and type(encoded) == "string" then
                fileSaved = pcall(writefile, ROT_FILE, encoded)
            end
        end
        local teleSaved = pcall(function()
            TeleportService:SetTeleportSetting(ROT_TELEPORT_KEY, payload)
        end)
        return fileSaved or teleSaved
    end

    local function clearRotationPending()
        if type(isfile) == "function" and type(delfile) == "function" then
            local okEx, exists = pcall(isfile, ROT_FILE)
            if okEx and exists then pcall(delfile, ROT_FILE) end
        end
        pcall(function()
            TeleportService:SetTeleportSetting(ROT_TELEPORT_KEY, false)
        end)
    end

    local function readRotationPending()
        local payload
        if type(isfile) == "function" and type(readfile) == "function" then
            local okEx, exists = pcall(isfile, ROT_FILE)
            if okEx and exists then
                local okRd, raw = pcall(readfile, ROT_FILE)
                if okRd and type(raw) == "string" then
                    local okDec, dec = pcall(HttpService.JSONDecode, HttpService, raw)
                    if okDec and type(dec) == "table" then payload = dec end
                end
            end
        end
        if not payload then
            local okT, data = pcall(function()
                return TeleportService:GetTeleportSetting(ROT_TELEPORT_KEY)
            end)
            if okT and type(data) == "table" then payload = data end
        end
        local uid = LocalPlayer and LocalPlayer.UserId or 0
        if type(payload) ~= "table"
            or payload.Schema ~= 1
            or tonumber(payload.UserId) ~= uid
            or (payload.PlaceId ~= nil and tonumber(payload.PlaceId) ~= game.PlaceId)
            or normalizeRotationWorld(payload.TargetWorld) == ""
            or os.time() - (tonumber(payload.CreatedAt) or 0) < 0
            or os.time() - (tonumber(payload.CreatedAt) or 0) > 900 then
            return nil
        end
        return payload
    end

    local function queueFactoryLoader()
        local ar = executorEnv.__ByteHubAutoReconnect
        if type(ar) == "table" and type(ar.queueLoader) == "function" then
            local ok, res, detail = pcall(ar.queueLoader)
            if ok and res == true then return true end
        end
        local url = DEFAULT_ROT_LOADER_URL
        local arFile = ROT_FOLDER .. "/autoreconnect_" ..
            tostring(LocalPlayer and LocalPlayer.UserId or 0) .. "_" .. tostring(game.PlaceId) .. ".json"
        if type(isfile) == "function" and type(readfile) == "function" then
            local okEx, exists = pcall(isfile, arFile)
            if okEx and exists then
                local okRd, raw = pcall(readfile, arFile)
                if okRd and type(raw) == "string" then
                    local okDec, dec = pcall(HttpService.JSONDecode, HttpService, raw)
                    if okDec and type(dec) == "table" and type(dec.Settings) == "table"
                        and type(dec.Settings.LoaderUrl) == "string" and dec.Settings.LoaderUrl ~= "" then
                        url = dec.Settings.LoaderUrl
                    end
                end
            end
        end
        local queueFn = executorEnv.queue_on_teleport
            or executorEnv.queueonteleport
            or (executorEnv.syn and executorEnv.syn.queue_on_teleport)
            or (executorEnv.fluxus and executorEnv.fluxus.queue_on_teleport)
        if type(queueFn) ~= "function" then
            return false, "Executor tidak menyediakan queue_on_teleport"
        end
        local queuedSource = ([=[
            if not game:IsLoaded() then game.Loaded:Wait() end
            local loaderUrl = %q
            local source
            local lastError = "respons kosong"
            local function validLua(text)
                if type(text) ~= "string" or text:match("^%%s*$") then return false, "respons kosong" end
                if text:sub(1, 3) == "\239\187\191" then text = text:sub(4) end
                if text:match("^%%s*<") then return false, "Server mengirim HTML" end
                if text:match("^%%s*[45]%%d%%d[:%%s]") then return false, text:sub(1, 120) end
                return true, text
            end
            local function tryLocal(path)
                if type(path) ~= "string" or path == "" then return nil end
                if type(isfile) == "function" and type(readfile) == "function" then
                    local okEx, exists = pcall(isfile, path)
                    if okEx and exists then
                        local okRd, content = pcall(readfile, path)
                        if okRd then
                            local v, val = validLua(content)
                            if v then return val end
                            lastError = val
                        end
                    end
                end
                return nil
            end
            if loaderUrl:match("^local:") then
                source = tryLocal(loaderUrl:sub(7))
            elseif loaderUrl:match("%%.luau?$") and not loaderUrl:match("^https?://") then
                source = tryLocal(loaderUrl)
            end
            if not source and loaderUrl:match("^https://") then
                local ok, res = pcall(function() return game:HttpGet(loaderUrl) end)
                if ok then
                    local v, val = validLua(res)
                    if v then source = val else lastError = val end
                else
                    lastError = tostring(res)
                end
                if not source then
                    local env = (type(getgenv) == "function" and getgenv()) or _G
                    local req = env.request or env.http_request or (env.syn and env.syn.request) or (env.http and env.http.request)
                    if type(req) == "function" then
                        local okR, resp = pcall(req, { Url = loaderUrl, Method = "GET" })
                        local status = okR and type(resp) == "table" and tonumber(resp.StatusCode or resp.Status)
                        local body = okR and type(resp) == "table" and (resp.Body or resp.body)
                        if not status or (status >= 200 and status < 300) then
                            local v, val = validLua(body)
                            if v then source = val else lastError = val end
                        else
                            lastError = "HTTP " .. tostring(status)
                        end
                    end
                end
            end
            if not source then
                for _, localPath in ipairs({ "ByteHub/local_loader.lua", "NewUI_Second_95.lua" }) do
                    source = tryLocal(localPath)
                    if source then break end
                end
            end
            assert(type(source) == "string" and source ~= "", "[ByteHub] Gagal mengunduh loader Rotation: " .. tostring(lastError))
            local fn, compErr = loadstring(source, "ByteHub_Loader")
            assert(type(fn) == "function", "[ByteHub] Compile loader gagal: " .. tostring(compErr))
            fn()
        ]=]):format(url)
        local okQ, qRes = pcall(queueFn, queuedSource)
        return okQ and qRes ~= false, qRes
    end

    local function parseFactoryOffsets()
        local list = {}
        for key in pairs(State.Offsets or {}) do
            local dx, dy = string.match(key, "^(-?%d+),(-?%d+)$")
            if dx and dy then
                list[#list + 1] = { dx = tonumber(dx), dy = tonumber(dy) }
            end
        end
        table.sort(list, function(a, b)
            if a.dy ~= b.dy then return a.dy < b.dy end
            return a.dx < b.dx
        end)
        return list
    end

    local function factoryLive(runId)
        return alive() and F.Running and F.On and F.RunId == runId
    end

    local function dropPointValid()
        local x, y = tonumber(F.DropX) or -1, tonumber(F.DropY) or -1
        if x < 0 or y < 0 then
            return false, "Titik drop belum diatur di tab Factory"
        end
        local w = Refs.World
        if not w then return false, "Data world belum ketemu" end
        local wn = Guard.worldName()
        if F.RotationOn ~= true and F.DropWorld and F.DropWorld ~= "" and wn ~= F.DropWorld then
            return false, "World titik drop (" .. tostring(F.DropWorld) .. ") berbeda"
        end
        if x >= w.w or y >= w.h or not openAt(x, y) or not realSupport(x, y) then
            return false, "Tile titik drop terhalang atau tanpa pijakan"
        end
        return true, x, y
    end

    local function treeCoverageOk(w)
        if not hvsTreeRefsReady(w) then return false end
        local totalSeeds = Hvs.TreeRefSeedCount or 0
        if totalSeeds == 0 then return true end
        local stamped = Hvs.TreeRefTimestampCount or 0
        return stamped >= math.max(1, math.floor(totalSeeds * 0.5))
    end

    local function ensureFactoryTreeRefs(w)
        if not w then return false end
        Hvs.TreeRefCheckAt = 0
        Hvs.TreeRefCheckWorld = nil
        if treeCoverageOk(w) then return true end

        pcall(findTreeRefs)
        Hvs.TreeRefCheckAt = 0
        Hvs.TreeRefCheckWorld = nil
        if treeCoverageOk(w) then return true end

        Refs.Trees, Refs.TreeMode, Refs.TreeP = nil, nil, nil
        if Auto.findTreesDeep then pcall(Auto.findTreesDeep) end
        Hvs.TreeRefCheckAt = 0
        Hvs.TreeRefCheckWorld = nil
        if treeCoverageOk(w) then return true end

        hvsHeapScanWorld = nil
        hvsHeapScanAt = 0
        pcall(hvsFindTreesInHeap, w)
        Hvs.TreeRefCheckAt = 0
        Hvs.TreeRefCheckWorld = nil
        return treeCoverageOk(w)
    end

    local function scanWorldTrees(w)
        local trees, readyCount, totalTrees = {}, 0, 0
        if not w then return trees, 0, 0 end
        local skipBottomY = hvsBottomRowY(w)
        local now = workspace:GetServerTimeNow()
        local countsByBlock, readyByBlock, seedByBlock = {}, {}, {}
        for y = 0, w.h - 1 do
            local row = (skipBottomY == nil or y ~= skipBottomY) and w.fg[y] or nil
            if row then
                for x = 0, w.w - 1 do
                    local id = row[x] or 0
                    if id ~= 0 then
                        local it = ItemDB[id]
                        if it and it.kind == "seed" then
                            totalTrees += 1
                            local bId = blockOfSeed(id)
                            local ra = treeReadyAt(x, y, id)
                            local ready = ra ~= nil and now >= ra
                            if ready then readyCount += 1 end
                            if bId then
                                F.TrackedBlocks[bId] = true
                                seedByBlock[bId] = id
                                countsByBlock[bId] = (countsByBlock[bId] or 0) + 1
                                if ready then
                                    readyByBlock[bId] = (readyByBlock[bId] or 0) + 1
                                end
                            end
                            trees[#trees + 1] = {
                                x = x, y = y, seedId = id, blockId = bId, ready = ready,
                            }
                        end
                    end
                end
            end
        end
        for _, bId in ipairs(Hvs.TypeIds or {}) do
            if bId then
                F.TrackedBlocks[bId] = true
                if not seedByBlock[bId] then
                    seedByBlock[bId] = seedOfBlock(bId)
                end
            end
        end
        if not F.BlockId then
            local bestBlock, bestReady, bestTotal = nil, -1, -1
            for bId, cnt in pairs(countsByBlock) do
                local rc = readyByBlock[bId] or 0
                if rc > bestReady or (rc == bestReady and cnt > bestTotal) then
                    bestBlock, bestReady, bestTotal = bId, rc, cnt
                end
            end
            if not bestBlock then
                for _, bId in ipairs(Hvs.TypeIds or {}) do
                    if bId then bestBlock = bId break end
                end
            end
            if bestBlock then
                F.BlockId = bestBlock
                F.SeedId = seedByBlock[bestBlock] or seedOfBlock(bestBlock)
            end
        elseif not F.SeedId then
            F.SeedId = seedByBlock[F.BlockId] or seedOfBlock(F.BlockId)
        end
        return trees, readyCount, totalTrees
    end

    local function pickBlockForPnB(minCount)
        minCount = math.max(1, tonumber(minCount) or 1)
        for _, bId in ipairs(Hvs.TypeIds or {}) do
            if bId then F.TrackedBlocks[bId] = true end
        end
        local bestBlock, bestCount = nil, 0
        local function consider(bId)
            if not bId then return end
            local c = invCount(bId)
            if c >= minCount then
                if c > bestCount or (c == bestCount and bId == F.BlockId) then
                    bestBlock, bestCount = bId, c
                end
            end
        end
        if F.BlockId then consider(F.BlockId) end
        for bId in pairs(F.TrackedBlocks) do
            consider(bId)
        end
        if bestBlock then
            return bestBlock, bestCount, seedOfBlock(bestBlock)
        end
        return nil, 0, nil
    end

    local function pickFullSeed()
        local lim = math.max(1, tonumber(F.SeedDropAt) or 200)
        local seen = {}
        local function checkSeed(sId)
            if not sId or seen[sId] then return nil end
            seen[sId] = true
            local c = invCount(sId)
            if c >= lim then return sId, c end
            return nil
        end
        if F.SeedId then
            local sId, c = checkSeed(F.SeedId)
            if sId then return sId, c end
        end
        if F.BlockId then
            local sId, c = checkSeed(seedOfBlock(F.BlockId))
            if sId then return sId, c end
        end
        for bId in pairs(F.TrackedBlocks) do
            local sId, c = checkSeed(seedOfBlock(bId))
            if sId then return sId, c end
        end
        for _, bId in ipairs(Hvs.TypeIds or {}) do
            local sId, c = checkSeed(seedOfBlock(bId))
            if sId then return sId, c end
        end
        return nil, 0
    end

    local function worldDropSeedCount(seedId)
        pcall(findDropRefs, false)
        local list = Drops.list
        if type(list) ~= "table" then return 0 end
        local wanted = tonumber(seedId) or seedId
        local total = 0
        for _, d in pairs(list) do
            if type(d) == "table" and (tonumber(d.id) or d.id) == wanted and (d.n or 0) > 0 then
                total += tonumber(d.n) or 0
            end
        end
        return total
    end

    local function hasPlantableSpot(w, seedId)
        if not w or not seedId then return false end
        local skipBottomY = hvsBottomRowY(w)
        for y = 0, w.h - 2 do
            if skipBottomY == nil or y ~= skipBottomY then
                for x = 0, w.w - 1 do
                    if plantSpotOk(x, y, seedId) then return true end
                end
            end
        end
        return false
    end

    local function findSafePnBSpot(w, sx, sy, safeDist, sameRowOnly)
        if not w then return nil, nil, "World belum tersedia" end
        local offs = parseFactoryOffsets()
        if #offs == 0 then
            return nil, nil, "Pilih tile dulu di Grid Tile tab Auto PnB"
        end
        local treesByRow, treeAt = {}, {}
        for y = 0, w.h - 1 do
            local row = w.fg[y]
            if row then
                for x = 0, w.w - 1 do
                    local id = row[x] or 0
                    local it = id ~= 0 and ItemDB[id]
                    if it and it.kind == "seed" then
                        local list = treesByRow[y]
                        if not list then
                            list = {}
                            treesByRow[y] = list
                        end
                        list[#list + 1] = x
                        treeAt[y * w.w + x] = true
                    end
                end
            end
        end

        local baseDist = math.max(1, math.floor(tonumber(safeDist) or 3))
        local dropHere = (tonumber(F.DropX) or -1) >= 0 and (tonumber(F.DropY) or -1) >= 0
            and (F.DropWorld == "" or F.DropWorld == Guard.worldName())
        local dropSafeR = math.max(3, (tonumber(State.CollectRadius) or 3) + 2)

        local function rowClearanceOk(x, y, minStandDist, minOffDist)
            if Move.isForbiddenFloor1Right(w, x, y) then return false end
            if fgIdAt(x, y) ~= 0 or not openAt(x, y) or not realSupport(x, y) then
                return false
            end
            local sameRowTrees = treesByRow[y]
            if sameRowTrees then
                for i = 1, #sameRowTrees do
                    if math.abs(x - sameRowTrees[i]) < minStandDist then
                        return false
                    end
                end
            end
            for _, o in ipairs(offs) do
                local ox, oy = x + o.dx, y + o.dy
                if ox < 0 or ox >= w.w or oy < 0 or oy >= w.h
                    or (ox == x and oy == y + 1)
                    or fgIdAt(ox, oy) ~= 0 or solidAt(ox, oy) or hazardAt(ox, oy)
                    or treeAt[oy * w.w + ox] or not canWorkAt(ox, oy) then
                    return false
                end
                local offRowTrees = treesByRow[oy]
                if offRowTrees then
                    for i = 1, #offRowTrees do
                        if math.abs(ox - offRowTrees[i]) < minOffDist then
                            return false
                        end
                    end
                end
            end
            return true
        end

        local function pickReachable(candidates, limit)
            if #candidates == 0 then return nil, nil end
            table.sort(candidates, function(a, b) return a.score < b.score end)
            local n = math.min(#candidates, limit or 25)
            for i = 1, n do
                local c = candidates[i]
                if c.x == sx and c.y == sy then
                    return sx, sy
                end
                local path = astar(sx, sy, { [c.y * w.w + c.x] = true, allowLongFall = true }, c.x, c.y, 0.5, false, nil, 0.15)
                if path then
                    return c.x, c.y
                end
            end
            return nil, nil
        end

        local sameRowAttempts = {
            { stand = baseDist + 1, off = math.max(2, baseDist) },
            { stand = baseDist, off = math.max(1, baseDist - 1) },
        }
        if sy >= 0 and sy <= w.h - 2 then
            for _, rule in ipairs(sameRowAttempts) do
                local candidates = {}
                for x = 0, w.w - 1 do
                    if rowClearanceOk(x, sy, rule.stand, rule.off) then
                        local score = math.abs(x - sx)
                        if dropHere and math.max(math.abs(x - F.DropX), math.abs(sy - F.DropY)) < dropSafeR then
                            score += 500
                        end
                        candidates[#candidates + 1] = { x = x, y = sy, score = score }
                    end
                end
                local rx, ry = pickReachable(candidates, 30)
                if rx then return rx, ry, nil end
            end
        end

        if sameRowOnly then
            return nil, nil, ("Belum ada ruang PnB >= %d tile di baris %d"):format(baseDist, sy)
        end

        local fallbackAttempts = {
            { stand = baseDist + 1, off = math.max(2, baseDist) },
            { stand = baseDist, off = math.max(1, baseDist - 1) },
        }
        for _, rule in ipairs(fallbackAttempts) do
            local candidates = {}
            for y = 0, w.h - 2 do
                if y ~= sy then
                    for x = 0, w.w - 1 do
                        if rowClearanceOk(x, y, rule.stand, rule.off) then
                            local score = math.abs(y - sy) * 6 + math.abs(x - sx)
                            if dropHere and math.max(math.abs(x - F.DropX), math.abs(y - F.DropY)) < dropSafeR then
                                score += 500
                            end
                            candidates[#candidates + 1] = { x = x, y = y, score = score }
                        end
                    end
                end
            end
            local rx, ry = pickReachable(candidates, 25)
            if rx then return rx, ry, nil end
        end

        return nil, nil, ("Tidak ada tile aman >= %d tile dari pohon"):format(baseDist)
    end

    local function restoreHarvestSettings()
        local sv = F.SavedHarvest
        if type(sv) ~= "table" then return end
        if sv.Order ~= nil then Harvest.Order = sv.Order end
        if sv.DropOn ~= nil then Harvest.DropOn = sv.DropOn end
        if sv.DropSeedOn ~= nil then Harvest.DropSeedOn = sv.DropSeedOn end
        if sv.CollectOn ~= nil then Harvest.CollectOn = sv.CollectOn end
        F.SavedHarvest = nil
    end

    local function clearDropProtections()
        Hvs.PickupUntil = 0
        Hvs.MarkUntil = 0
        Hvs.Dropping = false
        if Hvs.DropBlock then table.clear(Hvs.DropBlock) end
        Pabrik.Zone = nil
        Supply.BlockCollectUntil = 0
        table.clear(DropFailUntil)
    end

    local function runDropSeed(seedId, returnX, returnY, live)
        local okPt, dx, dy = dropPointValid()
        if not okPt then
            F.Status = tostring(dx)
            return false, dx
        end
        local w = Refs.World
        local wn = Guard.worldName()
        local function tripLive()
            return live() and Refs.World == w and Guard.worldName() == wn
        end

        F.Phase = "Auto Drop Seed"
        Hvs.Dropping = true
        Hvs.DropLive = tripLive
        Supply.BlockCollectUntil = os.clock() + 30
        F.Status = ("Menuju titik drop (%d,%d)..."):format(dx, dy)

        local reached = walkTo(dx, dy, 45, tripLive, nil, true, true)
        if not reached or not tripLive() then
            Hvs.Dropping, Hvs.DropLive = false, nil
            Supply.BlockCollectUntil = os.clock() + 0.5
            autoEnd()
            releaseInput()
            return false, "Gagal mencapai titik drop"
        end

        local cur = playerState()
        if not cur or cur.dead or not cur.grounded then
            Hvs.Dropping, Hvs.DropLive = false, nil
            Supply.BlockCollectUntil = os.clock() + 0.5
            autoEnd()
            releaseInput()
            return false, "Karakter belum siap drop"
        end

        local px, py = startNode(cur)
        local prefDir = (tonumber(F.DropFacing) or 1) < 0 and -1 or 1
        local dir = nil
        if px + prefDir >= 0 and px + prefDir < w.w and openAt(px + prefDir, py) then
            dir = prefDir
        elseif px - prefDir >= 0 and px - prefDir < w.w and openAt(px - prefDir, py) then
            dir = -prefDir
        end
        if not dir then
            Hvs.Dropping, Hvs.DropLive = false, nil
            Supply.BlockCollectUntil = os.clock() + 0.5
            autoEnd()
            releaseInput()
            F.Status = "Tile depan arah drop terhalang"
            return false, F.Status
        end

        F.Status = ("Menghadap arah %s..."):format(dir < 0 and "kiri" or "kanan")
        hvsFace(dir, tripLive)
        if not tripLive() then
            Hvs.Dropping, Hvs.DropLive = false, nil
            autoEnd()
            releaseInput()
            return false, "Dihentikan"
        end

        hvsHookPickup()
        local guardSec = math.clamp(tonumber(F.DropGuardSec) or 2.5, 1, 5)
        local function protect()
            local untilT = os.clock() + guardSec
            Hvs.PickupUntil = untilT
            Hvs.MarkWorld = w
            Hvs.MarkX, Hvs.MarkY, Hvs.MarkUntil, Hvs.MarkNext = px, py, untilT, 0
            hvsMarkDropped(px, py, untilT)
            Supply.BlockCollectUntil = untilT
        end
        protect()
        local batch = { nextAt = 0, protect = function() protect() end }
        local n = invCount(seedId)
        local got, dropErr = 0, nil
        if n > 0 then
            F.Status = ("Drop %s x%d (arah %s)"):format(itemName(seedId), n, dir < 0 and "kiri" or "kanan")
            got, dropErr = dropItems(seedId, n, tripLive, false, batch)
            F.SeedsDropped += got
            protect()
        end

        if tripLive() and type(returnX) == "number" and type(returnY) == "number" then
            local backCur = playerState()
            local bx, by = backCur and startNode(backCur)
            if bx ~= returnX or by ~= returnY then
                F.Status = ("Kembali ke posisi kerja (%d,%d)..."):format(returnX, returnY)
                walkTo(returnX, returnY, 45, tripLive, nil, true, true)
            end
        end

        Hvs.Dropping, Hvs.DropLive = false, nil
        Supply.BlockCollectUntil = os.clock() + 1
        autoEnd()
        releaseInput()
        if got > 0 then
            F.Status = ("Berhasil drop %s x%d"):format(itemName(seedId), got)
            return true, nil
        end
        F.Status = tostring(dropErr or "Drop seed gagal")
        return false, dropErr
    end

    local function runPnBPhase(blockId, seedId, live)
        local w = Refs.World
        local s = playerState()
        if not w or not s then return false, "Belum di world" end
        local offs = parseFactoryOffsets()
        if #offs == 0 then
            F.Status = "Grid Tile di tab Auto PnB masih kosong!"
            notify("Factory", F.Status, 5)
            return false, F.Status
        end
        F.BlockId = blockId
        if seedId then F.SeedId = seedId end
        local sx, sy = startNode(s)
        local tx, ty, spotErr = findSafePnBSpot(w, sx, sy, F.SafeDist, true)
        if not tx and sy >= 0 and sy <= w.h - 2 and sy ~= hvsBottomRowY(w) then
            local function clearForwardForPnB()
                local clearCount = math.clamp(math.max(4, (tonumber(F.SafeDist) or 3) + 1), 3, 6)
                local dir = hvsRowDirection(sy, w)

                local function findNextReadyTreeAhead(curX, d, maxSteps)
                    local limit = maxSteps or 12
                    local st = workspace:GetServerTimeNow()
                    for step = 0, limit do
                        local x = curX + d * step
                        if x < 0 or x >= w.w then break end
                        local id = fgIdAt(x, sy)
                        if id ~= 0 then
                            local it = ItemDB[id]
                            if it and it.kind == "seed" then
                                local ra = treeReadyAt(x, sy, id)
                                if ra and st >= ra and canWorkAt(x, sy)
                                    and not Move.isForbiddenFloor1Right(w, x, sy) then
                                    return x
                                end
                            elseif not openAt(x, sy) then
                                break
                            end
                        elseif step >= 1 and not realSupport(x, sy) then
                            break
                        end
                    end
                    return nil
                end

                local activeDir = dir
                if not findNextReadyTreeAhead(sx, activeDir, 6) then
                    if findNextReadyTreeAhead(sx, -activeDir, 6) then
                        activeDir = -activeDir
                    else
                        return nil, nil
                    end
                end

                local hitInterval = math.clamp((tonumber(Hvs.HitMs) or 200) / 1000, 0.08, 0.35)
                local lastX, lastY = sx, sy
                for i = 1, clearCount do
                    if not live() or Refs.World ~= w then break end
                    local curS = playerState()
                    if not curS or curS.dead then break end
                    local curX, curY = startNode(curS)
                    if curY ~= sy then break end
                    lastX, lastY = curX, curY

                    local targetX = findNextReadyTreeAhead(curX, activeDir, 10)
                    if not targetX then break end

                    local stX = nil
                    for _, candX in ipairs({ targetX - activeDir, targetX + activeDir }) do
                        if candX >= 0 and candX < w.w and openAt(candX, sy) and realSupport(candX, sy)
                            and not Move.isForbiddenFloor1Right(w, candX, sy) then
                            stX = candX
                            break
                        end
                    end
                    if not stX then break end

                    if not curS.grounded or not hvsAtSpacing(curS, targetX, sy) then
                        F.Phase = "Buka Ruang PnB"
                        F.Status = ("Buka ruang PnB: menuju (%d,%d) [%d/%d]"):format(stX, sy, i, clearCount)
                        local walked = walkTo(stX, sy, 8, live, nil, false, true)
                        releaseInput()
                        autoEnd()
                        if not walked or not live() or Refs.World ~= w then break end
                    end

                    F.Phase = "Buka Ruang PnB"
                    F.Status = ("Buka ruang PnB: panen (%d,%d) [%d/%d]"):format(targetX, sy, i, clearCount)
                    for hit = 1, 6 do
                        if not live() or Refs.World ~= w or fgIdAt(targetX, sy) == 0 then break end
                        local curCheck = playerState()
                        if not curCheck or curCheck.dead then break end
                        if not curCheck.grounded or not hvsAtSpacing(curCheck, targetX, sy) then
                            local movedOk = walkTo(stX, sy, 6, live, nil, false, true)
                            releaseInput()
                            autoEnd()
                            if not movedOk or not live() then break end
                        end
                        local res = tryBreak(targetX, sy, false)
                        if res == "broke" or fgIdAt(targetX, sy) == 0 then
                            break
                        end
                        task.wait(hitInterval)
                    end

                    local afterS = playerState()
                    if afterS and not afterS.dead then
                        local ax, ay = startNode(afterS)
                        lastX, lastY = ax, ay
                        if ay == sy then
                            local rx, ry = findSafePnBSpot(w, ax, sy, F.SafeDist, true)
                            if rx then
                                return rx, ry
                            end
                        end
                    end
                end

                local finalS = playerState()
                if finalS and not finalS.dead then
                    lastX, lastY = startNode(finalS)
                end
                return findSafePnBSpot(w, lastX, sy, F.SafeDist, true)
            end

            local cx, cy = clearForwardForPnB()
            if cx then
                tx, ty = cx, cy
            end
            s = playerState()
            if s then
                sx, sy = startNode(s)
            end
        end
        if not tx then
            tx, ty, spotErr = findSafePnBSpot(w, sx, sy, F.SafeDist, false)
        end
        if not tx then
            F.Status = tostring(spotErr or "Posisi PnB aman tidak ketemu")
            notify("Factory", F.Status, 4)
            return false, spotErr
        end

        F.Phase = "Menuju Posisi PnB"
        F.PnbX, F.PnbY = tx, ty
        if sx ~= tx or sy ~= ty then
            F.Status = ("Jaga jarak >=%d tile ke (%d,%d)"):format(tonumber(F.SafeDist) or 3, tx, ty)
            local moved = walkTo(tx, ty, 45, live, nil, true, true)
            autoEnd()
            releaseInput()
            if not live() then return false, "Dihentikan" end
            if not moved then
                F.Status = ("Gagal jalan ke posisi PnB (%d,%d)"):format(tx, ty)
                return false, F.Status
            end
        end

        local function collectPnBPendingTiles()
            local pending, seen = {}, {}
            local function addCandidate(x, y, onlyBlock)
                if type(x) ~= "number" or type(y) ~= "number" then return end
                if x < 0 or y < 0 or x >= w.w or y >= w.h then return end
                local key = x .. "," .. y
                if seen[key] then return end
                local fg = fgIdAt(x, y)
                if fg == 0 or not canBreak(fg) then return end
                local it = ItemDB[fg]
                if it and it.kind == "seed" then return end
                if onlyBlock and fg ~= blockId then return end
                seen[key] = true
                pending[#pending + 1] = { x = x, y = y }
            end

            local curS = playerState()
            local curX, curY
            if curS then curX, curY = startNode(curS) end

            for _, o in ipairs(offs) do
                addCandidate(tx + o.dx, ty + o.dy, false)
                if curX and curY == ty and math.abs(curX - tx) <= 3 then
                    addCandidate(curX + o.dx, curY + o.dy, true)
                end
                for dxShift = -2, 2 do
                    addCandidate(tx + o.dx + dxShift, ty + o.dy, true)
                end
            end
            for x = math.max(0, tx - 3), math.min(w.w - 1, tx + 3) do
                addCandidate(x, ty, true)
            end
            for key in pairs(PlacedAt) do
                local kx, ky = string.match(key, "^(-?%d+),(-?%d+)$")
                kx, ky = tonumber(kx), tonumber(ky)
                if kx and ky and math.abs(kx - tx) <= 4 and math.abs(ky - ty) <= 2 then
                    addCandidate(kx, ky, false)
                end
            end

            local refX, refY = curX or tx, curY or ty
            table.sort(pending, function(a, b)
                local da = math.abs(a.x - refX) + math.abs(a.y - refY)
                local db = math.abs(b.x - refX) + math.abs(b.y - refY)
                if da ~= db then return da < db end
                if a.y ~= b.y then return a.y < b.y end
                return a.x < b.x
            end)
            return pending
        end

        local function anyOffsetBreakable()
            return #collectPnBPendingTiles() > 0
        end

        local function bestPunchStandTile(t)
            if math.abs(tx - t.x) <= 2 and math.abs(ty - t.y) <= 1 and openAt(tx, ty) and realSupport(tx, ty) then
                return tx, ty
            end
            local candidates = {
                { x = t.x - 1, y = ty },
                { x = t.x + 1, y = ty },
                { x = t.x, y = ty },
                { x = t.x - 1, y = t.y },
                { x = t.x + 1, y = t.y },
            }
            for _, c in ipairs(candidates) do
                if c.x >= 0 and c.y >= 0 and c.x < w.w and c.y < w.h
                    and math.abs(c.x - t.x) <= 2 and math.abs(c.y - t.y) <= 2
                    and openAt(c.x, c.y) and realSupport(c.x, c.y) then
                    return c.x, c.y
                end
            end
            return tx, ty
        end

        -- Block yang masih terpasang di tile PnB wajib dihancurkan sebelum keluar dari
        -- fase PnB (stok habis, seed penuh/drop, watchdog, atau Factory dihentikan).
        local function cleanupPnBTiles()
            local deadline = os.clock() + 15
            local function cleanLive()
                return alive() and Refs.World == w and os.clock() < deadline
            end
            State.Running = false
            State.Override = { offsets = State.Offsets, block = blockId, mode = "Break saja" }
            State.Quiet = true
            -- Tunggu singkat agar paket replikasi server dari place terakhir sempat masuk
            -- dan melewati jendela anti-instant-break server (PLACE_GUARD = 0.32s).
            if cleanLive() then
                task.wait(0.38)
            end
            if live() then
                local curS = playerState()
                if curS then
                    local cx, cy = startNode(curS)
                    if cx ~= tx or cy ~= ty then
                        walkTo(tx, ty, 20, live, nil, true, true)
                        autoEnd()
                        releaseInput()
                    end
                end
            end
            local lastStatus = F.Status
            while cleanLive() do
                local pending = collectPnBPendingTiles()
                if #pending == 0 then
                    task.wait(0.35)
                    if not cleanLive() then break end
                    pending = collectPnBPendingTiles()
                    if #pending == 0 then break end
                end
                if F.Running then
                    F.Phase = "Auto PnB"
                    F.Status = ("Menghancurkan sisa block PnB (%d tile)..."):format(#pending)
                end
                for _, t in ipairs(pending) do
                    if not cleanLive() then break end
                    if live() then
                        local curS = playerState()
                        if curS then
                            local cx, cy = startNode(curS)
                            if math.abs(cy - t.y) > 1 or math.abs(cx - t.x) > 2 then
                                local sxStand, syStand = bestPunchStandTile(t)
                                if cx ~= sxStand or cy ~= syStand then
                                    walkTo(sxStand, syStand, 15, live, nil, true, true)
                                    autoEnd()
                                    releaseInput()
                                end
                            end
                        end
                    end
                    local pKey = t.x .. "," .. t.y
                    local placedT = PlacedAt[pKey]
                    if placedT then
                        local age = os.clock() - placedT
                        if age < 0.35 and cleanLive() then
                            task.wait(0.35 - age)
                        end
                        PlacedAt[pKey] = nil
                    end
                    if not cleanLive() then break end
                    pcall(tryBreak, t.x, t.y, false)
                    task.wait(math.max(0.24, tonumber(State.RefillHitGate) or 0.22))
                end
            end
            if F.Running then F.Status = lastStatus end
            State.Override = nil
            State.Quiet = false
            return not anyOffsetBreakable()
        end

        local warnedNoDrop = false
        local seedLimit = math.max(1, tonumber(F.SeedDropAt) or 200)
        while live() and Refs.World == w and (invCount(blockId) > 0 or anyOffsetBreakable()) do
            if seedId and invCount(seedId) >= seedLimit then
                local ptOk, ptMsg = dropPointValid()
                if ptOk then
                    cleanupPnBTiles()
                    if not live() then break end
                    local okDrop = runDropSeed(seedId, tx, ty, live)
                    if not live() then break end
                    if not okDrop then task.wait(0.8) end
                    continue
                elseif not warnedNoDrop then
                    warnedNoDrop = true
                    notify("Factory", "Seed penuh (200) tapi " .. tostring(ptMsg), 5)
                end
            end

            local curS = playerState()
            if not curS or not live() then break end
            local cx, cy = startNode(curS)
            if cx ~= tx or cy ~= ty then
                F.Status = ("Kembali ke titik PnB (%d,%d)"):format(tx, ty)
                walkTo(tx, ty, 30, live, nil, true, true)
                autoEnd()
                releaseInput()
                if not live() then break end
            end

            F.Phase = "Auto PnB"
            F.Status = ("Auto PnB %s (stok: %d)"):format(itemName(blockId), invCount(blockId))
            local mode = (State.Mode == "Place + Break (instan refill)" or State.Mode == "Place + Break")
                and State.Mode or "Place + Break"
            State.Override = { offsets = State.Offsets, block = blockId, mode = mode }
            State.Quiet = true
            table.clear(HitCount)
            table.clear(PlacedAt)
            table.clear(HitGateAt)
            State.Running = true
            State.RunId = (State.RunId or 0) + 1
            local id = State.RunId
            local broken0 = tonumber(State.Broken) or 0
            local acts0 = (tonumber(State.Placed) or 0) + broken0
            local lastActs, lastActAt = acts0, os.clock()

            task.spawn(function()
                while State.Running and State.RunId == id do
                    task.wait(0.15)
                    local acts = (tonumber(State.Placed) or 0) + (tonumber(State.Broken) or 0)
                    if acts ~= lastActs then
                        lastActs, lastActAt = acts, os.clock()
                    end
                    local sFull = seedId and invCount(seedId) >= seedLimit and dropPointValid()
                    if not live() or Refs.World ~= w or sFull or (os.clock() - lastActAt > 10) then
                        State.Running = false
                    end
                    if State.Running and F.Status then
                        F.Status = ("Auto PnB %s (stok: %d | seed: %d)"):format(
                            itemName(blockId), invCount(blockId), seedId and invCount(seedId) or 0
                        )
                    end
                end
            end)

            local okRun, runErr
            if mode == "Place + Break (instan refill)" then
                okRun, runErr = pcall(UI.RefillLoop, id)
            else
                okRun, runErr = pcall(farmLoop, id)
            end
            State.Running = false
            State.Override = nil
            State.Quiet = false
            if not okRun then
                warn("[ByteHub] Factory PnB error: " .. tostring(runErr))
            end
            local brokenNow = tonumber(State.Broken) or 0
            F.BlocksBroken += math.max(0, brokenNow - broken0)

            local actsNow = (tonumber(State.Placed) or 0) + brokenNow
            if actsNow == acts0 and invCount(blockId) > 0 and not (seedId and invCount(seedId) >= seedLimit) then
                task.wait(0.4)
                break
            end
        end

        cleanupPnBTiles()
        if alive() and Refs.World == w then
            task.wait(0.35)
            for _ = 1, 2 do
                if not anyOffsetBreakable() then break end
                cleanupPnBTiles()
                if not (alive() and Refs.World == w) then break end
                task.wait(0.35)
            end
        end
        if live() and seedId and invCount(seedId) >= seedLimit and dropPointValid() then
            runDropSeed(seedId, tx, ty, live)
        end
        F.PnbX, F.PnbY = -1, -1
        return true, nil
    end

    local function runHarvestPhase(live)
        local deadline = os.clock() + 5
        while live() and (Hvs.WorkerActive or Hvs.HarvestWorkerBusy) and os.clock() < deadline do
            task.wait(0.1)
        end
        if not live() then return "stopped" end

        local wStart = Refs.World
        if wStart then
            local _, _, totalNow = scanWorldTrees(wStart)
            if totalNow > 0 and not ensureFactoryTreeRefs(wStart) then
                return "error", "Data waktu tumbuh pohon belum terbaca"
            end
        end

        if not F.SavedHarvest then
            F.SavedHarvest = {
                Order = Harvest.Order,
                DropOn = Harvest.DropOn,
                DropSeedOn = Harvest.DropSeedOn,
                CollectOn = Harvest.CollectOn,
            }
        end
        Harvest.Order = "Bawah ke Atas"
        Harvest.DropOn = false
        Harvest.DropSeedOn = false
        Harvest.CollectOn = true

        F.Harvesting = true
        F.Phase = "Auto Harvest"
        F.Status = "Panen dari bawah (Auto Harvest)..."
        local err = Hvs.start()
        if err then
            F.Harvesting = false
            restoreHarvestSettings()
            return "error", err
        end

        local emptyStreak = 0
        while live() do
            for _, bId in ipairs(Hvs.TypeIds or {}) do
                if bId then
                    F.TrackedBlocks[bId] = true
                    if not F.BlockId then
                        F.BlockId = bId
                        F.SeedId = seedOfBlock(bId)
                    end
                end
            end

            local bId, bCount, sId = pickBlockForPnB(F.BlockLimit)
            if bId then
                F.Status = ("Block %s mencapai %d, pindah ke Auto PnB..."):format(itemName(bId), bCount)
                Hvs.stop()
                local waitStop = os.clock() + 4
                while live() and (Hvs.WorkerActive or Hvs.HarvestWorkerBusy) and os.clock() < waitStop do
                    task.wait(0.08)
                end
                F.Harvesting = false
                restoreHarvestSettings()
                return "pnb", bId, sId
            end

            local fullSeed = pickFullSeed()
            if fullSeed and dropPointValid() then
                F.Status = ("Seed %s mencapai batas drop (%d)..."):format(itemName(fullSeed), invCount(fullSeed))
                Hvs.stop()
                local waitStop = os.clock() + 4
                while live() and (Hvs.WorkerActive or Hvs.HarvestWorkerBusy) and os.clock() < waitStop do
                    task.wait(0.08)
                end
                F.Harvesting = false
                restoreHarvestSettings()
                return "dropseed", fullSeed
            end

            if not Hvs.Running then
                F.Harvesting = false
                restoreHarvestSettings()
                return "stopped"
            end

            local w = Refs.World
            if w and hvsTreeRefsReady(w) and not Hvs.TreeRefSearching then
                local ready = Hvs.readyCount()
                if ready == 0 and Hvs.PendingTarget == nil and not Hvs.HarvestBusy
                    and not Hvs.HarvestWorkerBusy and Hvs.RowTransitionTarget == nil
                    and #(Hvs.PendingCollect or {}) == 0 then
                    emptyStreak += 1
                    if emptyStreak >= 5 then
                        Hvs.stop()
                        local waitStop = os.clock() + 3
                        while live() and (Hvs.WorkerActive or Hvs.HarvestWorkerBusy) and os.clock() < waitStop do
                            task.wait(0.08)
                        end
                        task.wait(0.35)
                        F.Harvesting = false
                        restoreHarvestSettings()
                        return "empty"
                    end
                else
                    emptyStreak = 0
                end
            else
                emptyStreak = 0
            end
            task.wait(0.2)
        end

        if Hvs.Running then Hvs.stop() end
        F.Harvesting = false
        restoreHarvestSettings()
        return "stopped"
    end

    local function runAutoPlantPhase(seedId, live)
        local wCheck = Refs.World
        if not wCheck then return false, "World belum tersedia" end
        local _, readyNow, totalNow = scanWorldTrees(wCheck)
        if totalNow > 0 and not treeCoverageOk(wCheck) then
            ensureFactoryTreeRefs(wCheck)
            _, readyNow, totalNow = scanWorldTrees(wCheck)
            if totalNow > 0 and not treeCoverageOk(wCheck) then
                return false, "ready_tree"
            end
        end
        if readyNow > 0 then
            return false, "ready_tree"
        end

        clearDropProtections()
        local waitOld = os.clock() + 4
        while live() and plantState.workerActive and os.clock() < waitOld do
            task.wait(0.1)
        end
        if not live() then return false end

        plantState.autoTakeSeed = true
        if plantState.controls and plantState.controls.autoTakeSeed then
            pcall(plantState.controls.autoTakeSeed.Set, plantState.controls.autoTakeSeed, true, true)
        end

        pcall(findDropRefs, false)
        pcall(ensureGameHooks)

        local foundEntry, foundLabel = nil, nil
        for attempt = 1, 3 do
            if not live() then return false end
            if scanSeedInventory then pcall(scanSeedInventory) end
            for label, entry in pairs(seedByLabel) do
                if type(entry) == "table" and tostring(entry.Id) == tostring(seedId) then
                    foundEntry, foundLabel = entry, label
                    break
                end
            end
            if foundEntry then break end
            task.wait(0.45)
        end

        if foundEntry and foundLabel then
            selectedSeed = foundEntry
            selectedSeedLabel = foundLabel
            plantState.selectedSeedId = foundEntry.Id
            plantState.selectedSeedName = foundEntry.Name
            if seedDropdown then pcall(seedDropdown.Set, seedDropdown, foundLabel, true) end
            if plantState.saveRealtime then pcall(plantState.saveRealtime) end
        else
            return false, "Seed belum terdaftar di Auto Plant"
        end

        if invCount(seedId) <= 0 and worldDropSeedCount(seedId) <= 0 then
            return false, "Stok seed habis di inventory & world"
        end

        F.Planting = true
        F.Phase = "Auto Plant"
        F.Status = ("Menanam ulang %s..."):format(itemName(seedId))
        plantState.skipBottomRow = true
        if autoToggle then pcall(autoToggle.Set, autoToggle, true, true) end
        if startScan then startScan() end

        if not plantState.running and not plantState.workerActive then
            plantState.skipBottomRow = false
            F.Planting = false
            return false, "Auto Plant gagal dimulai"
        end

        local nextReadyCheck = os.clock() + 1.5
        while live() and (plantState.running or plantState.workerActive) do
            if os.clock() >= nextReadyCheck then
                nextReadyCheck = os.clock() + 1.5
                if Refs.World == wCheck and hvsTreeRefsReady(wCheck) and Hvs.readyCount() > 0 then
                    F.Status = "Pohon siap panen terdeteksi, menghentikan Auto Plant..."
                    if stopAutoPlant then
                        pcall(stopAutoPlant, "Pohon siap panen terdeteksi, lanjut Harvest")
                    end
                    local waitPlantStop = os.clock() + 2
                    while live() and plantState.workerActive and os.clock() < waitPlantStop do
                        task.wait(0.05)
                    end
                    plantState.skipBottomRow = false
                    F.Planting = false
                    return false, "ready_tree"
                end
            end
            F.Status = ("Auto Plant %s (tertanam: %d)"):format(
                itemName(seedId), tonumber(plantState.planted) or 0
            )
            task.wait(0.35)
        end

        if not live() and (plantState.running or plantState.workerActive) and stopAutoPlant then
            pcall(stopAutoPlant, "Dihentikan karena Factory berhenti")
        end
        plantState.skipBottomRow = false
        F.Planting = false
        F.Cycles += 1
        return true, nil
    end

    local function dropRemainingSeedsBeforeRotate(live)
        local seeds, seen = {}, {}
        local function addSeed(sid)
            if sid and not seen[sid] then
                seen[sid] = true
                seeds[#seeds + 1] = sid
            end
        end
        addSeed(F.SeedId)
        if F.BlockId then addSeed(seedOfBlock(F.BlockId)) end
        for bId in pairs(F.TrackedBlocks) do
            addSeed(seedOfBlock(bId))
        end
        for _, bId in ipairs(Hvs.TypeIds or {}) do
            addSeed(seedOfBlock(bId))
        end
        if selectedSeed and selectedSeed.Id then
            addSeed(selectedSeed.Id)
        end

        local droppedAny = false
        local warnedInvalid = false
        for _, sid in ipairs(seeds) do
            if not live() then break end
            if invCount(sid) > 0 then
                local ptOk, ptMsg = dropPointValid()
                if ptOk then
                    F.Phase = "Rotation"
                    F.Status = ("Drop sisa seed %s x%d sebelum pindah world..."):format(itemName(sid), invCount(sid))
                    local okDrop = runDropSeed(sid, nil, nil, live)
                    if okDrop then droppedAny = true end
                else
                    if not warnedInvalid then
                        warnedInvalid = true
                        notify("Factory", "Rotation: titik drop belum valid (" .. tostring(ptMsg) .. "), skip drop sisa seed.", 4)
                    end
                    break
                end
            end
        end
        if droppedAny and live() then
            task.wait(0.6)
        end
    end

    local function rotateToNextWorld(nextWorld, nextIdx, live)
        F.Rotating = true
        F.Phase = "Rotation"
        F.RotationIndex = nextIdx
        F.RotationStatus = "Pindah ke " .. nextWorld
        F.Status = ("Menyiapkan pindah world ke %s..."):format(nextWorld)

        pcall(Config.save, true)
        local staleRecFile = ROT_FOLDER .. "/reconnect_" .. tostring(LocalPlayer and LocalPlayer.UserId or 0) .. ".json"
        if type(isfile) == "function" and type(delfile) == "function" then
            local okEx, exists = pcall(isfile, staleRecFile)
            if okEx and exists then pcall(delfile, staleRecFile) end
        end
        pcall(function()
            TeleportService:SetTeleportSetting("ByteHub.AutoReconnect.v1", false)
        end)
        saveRotationPending(nextWorld, nextIdx)
        queueFactoryLoader()

        local delaySec = math.clamp(math.floor(tonumber(F.RotationDelaySec) or 3), 1, 15)
        local delayEnd = os.clock() + delaySec
        while live() and os.clock() < delayEnd do
            F.Status = ("Rotation ke %s dalam %ds..."):format(nextWorld, math.max(1, math.ceil(delayEnd - os.clock())))
            task.wait(0.25)
        end
        if not live() then
            F.Rotating = false
            clearRotationPending()
            return "stopped"
        end

        local lastErr = nil
        for attempt = 1, 3 do
            if not live() then
                F.Rotating = false
                clearRotationPending()
                return "stopped"
            end
            if normalizeRotationWorld(Guard.worldName()) ~= "" then
                F.Status = ("Keluar dari world menuju %s (%d/3)..."):format(nextWorld, attempt)
                pcall(Guard.leaveWorld)
                local exitDead = os.clock() + 4
                while live() and os.clock() < exitDead and normalizeRotationWorld(Guard.worldName()) ~= "" do
                    task.wait(0.2)
                end
                if not live() then
                    F.Rotating = false
                    clearRotationPending()
                    return "stopped"
                end
            end

            F.Status = ("Masuk world %s (%d/3)..."):format(nextWorld, attempt)
            local okEnter, enterErr, hopping = Guard.enterWorld(nextWorld)
            if hopping == true then
                F.RotationStatus = "Teleport ke " .. nextWorld
                F.Status = ("Teleport server ke %s..."):format(nextWorld)
                return "hopping"
            end
            if okEnter then
                pcall(Guard.afterEnter)
                F.BlockId = nil
                F.SeedId = nil
                table.clear(F.TrackedBlocks)
                Refs.Trees = nil
                Hvs.TreeRefCheckWorld = nil
                Hvs.TreeRefCheckAt = 0
                task.wait(1.5)
                clearRotationPending()
                F.Rotating = false
                F.RotationStatus = "Aktif di " .. nextWorld
                F.Status = ("Berhasil pindah ke %s"):format(nextWorld)
                return "entered"
            end

            lastErr = enterErr
            F.Status = ("Gagal masuk %s (%d/3): %s"):format(nextWorld, attempt, tostring(enterErr or ""))
            local retryEnd = os.clock() + 3
            while live() and os.clock() < retryEnd do
                task.wait(0.25)
            end
        end

        F.Rotating = false
        clearRotationPending()
        local worlds = parseRotationWorlds(F.RotationWorldsText)
        if #worlds > 0 then
            F.RotationIndex = (nextIdx % #worlds) + 1
        end
        F.RotationStatus = ("Gagal masuk %s"):format(nextWorld)
        F.Status = lastErr and ("Rotation gagal (" .. nextWorld .. "): " .. tostring(lastErr)) or F.RotationStatus
        return "failed"
    end

    local function factoryLoop(runId)
        local function live()
            return factoryLive(runId)
        end
        if Refs.World then
            ensureFactoryTreeRefs(Refs.World)
        elseif not Refs.Trees then
            pcall(findTreeRefs)
        end
        local plantRetryAt = {}
        local plantStageActive = false
        local lastLoopWorld = nil

        while live() do
            if not Session.Ready or next(ItemDB) == nil then
                F.Phase = "Memuat"
                F.Status = "Menunggu data game & ItemDB siap..."
                task.wait(0.3)
                continue
            end

            local w = Refs.World
            local s = playerState()
            if not w or not s then
                F.Phase = "Menunggu"
                F.Status = "Menunggu world / karakter siap..."
                task.wait(0.5)
                continue
            end

            if w ~= lastLoopWorld then
                lastLoopWorld = w
                plantStageActive = false
                table.clear(plantRetryAt)
            end

            local _, readyCount, totalTrees = scanWorldTrees(w)
            if totalTrees > 0 and not treeCoverageOk(w) then
                F.Phase = "Memindai"
                F.Status = "Mencari timestamp pohon di world..."
                ensureFactoryTreeRefs(w)
                _, readyCount, totalTrees = scanWorldTrees(w)
                if totalTrees > 0 and not treeCoverageOk(w) then
                    F.Status = "Menunggu data waktu tumbuh pohon terbaca..."
                    task.wait(1)
                    continue
                end
            end

            if readyCount > 0 then
                plantStageActive = false
            end

            local fullSeed = pickFullSeed()
            if fullSeed and dropPointValid() then
                local rx, ry = startNode(s)
                if runDropSeed(fullSeed, rx, ry, live) then
                    table.clear(plantRetryAt)
                else
                    task.wait(1)
                end
                continue
            end

            -- Saat sudah masuk fase Auto Plant (atau world penuh pohon tumbuh tanpa siap panen),
            -- block sisa/terpungut tidak boleh memicu Auto PnB lagi sampai siklus panen berikutnya.
            if not plantStageActive and not F.Planting then
                local fullBlock, _, fullSeedForBlock = pickBlockForPnB(F.BlockLimit)
                if fullBlock then
                    local okPnB = runPnBPhase(fullBlock, fullSeedForBlock, live)
                    table.clear(plantRetryAt)
                    if not okPnB then
                        if totalTrees > 0 then
                            plantStageActive = true
                        else
                            task.wait(1.5)
                        end
                    end
                    continue
                end
            end

            if readyCount > 0 then
                plantStageActive = false
                local res, a1, a2 = runHarvestPhase(live)
                if res == "pnb" and a1 then
                    runPnBPhase(a1, a2, live)
                    table.clear(plantRetryAt)
                elseif res == "dropseed" and a1 then
                    local ps = playerState()
                    local rx, ry = ps and startNode(ps)
                    runDropSeed(a1, rx, ry, live)
                    table.clear(plantRetryAt)
                elseif res == "empty" then
                    table.clear(plantRetryAt)
                elseif res == "error" then
                    F.Status = tostring(a1 or "Error Harvest")
                    task.wait(1.5)
                else
                    task.wait(0.25)
                end
                continue
            end

            -- Pastikan tidak ada pohon siap panen sebelum menghabiskan sisa block < 200 atau Auto Plant.
            task.wait(0.25)
            if not live() then break end
            if totalTrees > 0 and not treeCoverageOk(w) then
                ensureFactoryTreeRefs(w)
                if not treeCoverageOk(w) then continue end
            end
            local _, recheckReady = scanWorldTrees(w)
            if recheckReady > 0 then
                plantStageActive = false
                continue
            end

            if not plantStageActive and not F.Planting then
                local leftBlock, _, leftSeed = pickBlockForPnB(1)
                if leftBlock then
                    local okLeft = runPnBPhase(leftBlock, leftSeed, live)
                    table.clear(plantRetryAt)
                    if not okLeft then
                        if totalTrees > 0 then
                            plantStageActive = true
                        else
                            task.wait(1.5)
                        end
                    end
                    continue
                end
            end

            if hvsTreeRefsReady(w) and Hvs.readyCount() > 0 then
                plantStageActive = false
                continue
            end

            local now = os.clock()
            local plantSeed = nil
            local checkedSeeds = {}
            local function trySeedCandidate(sid)
                if plantSeed or not sid or checkedSeeds[sid] then return end
                checkedSeeds[sid] = true
                if now < (plantRetryAt[sid] or 0) then return end
                if (invCount(sid) > 0 or worldDropSeedCount(sid) > 0) and hasPlantableSpot(w, sid) then
                    plantSeed = sid
                end
            end
            trySeedCandidate(F.SeedId)
            if F.BlockId then trySeedCandidate(seedOfBlock(F.BlockId)) end
            for bId in pairs(F.TrackedBlocks) do
                trySeedCandidate(seedOfBlock(bId))
            end
            if not plantSeed and selectedSeed and selectedSeed.Id then
                trySeedCandidate(selectedSeed.Id)
            end

            if plantSeed then
                plantStageActive = true
                local okPlant, plantWhy = runAutoPlantPhase(plantSeed, live)
                if plantWhy == "ready_tree" then
                    plantStageActive = false
                else
                    plantRetryAt[plantSeed] = os.clock() + (okPlant and 15 or 45)
                end
                continue
            end

            if F.RotationOn then
                local worlds = parseRotationWorlds(F.RotationWorldsText)
                if #worlds == 0 then
                    F.RotationStatus = "Daftar world kosong"
                else
                    local nextWorld, nextIdx = nextRotationWorld(Guard.worldName())
                    if nextWorld then
                        dropRemainingSeedsBeforeRotate(live)
                        if not live() then break end
                        local rotRes = rotateToNextWorld(nextWorld, nextIdx, live)
                        if rotRes == "hopping" then
                            F.Running = false
                            F.On = false
                            break
                        elseif rotRes == "entered" then
                            plantStageActive = false
                            table.clear(plantRetryAt)
                            continue
                        else
                            task.wait(5)
                            continue
                        end
                    end
                end
            end

            F.Phase = "Menunggu"
            if totalTrees > 0 then
                F.Status = ("Menunggu %d pohon matang..."):format(totalTrees)
            else
                F.Status = "Semua panen & PnB selesai, menunggu pohon/lahan..."
            end
            task.wait(1.5)
        end
    end

    function F.start()
        if F.Running then return nil end
        if F.WorkerActive then return "Tunggu proses Factory sebelumnya berhenti." end
        if WorldFinder.Busy then return "Hentikan World Finder dulu sebelum menjalankan Factory." end
        if AutoDrop.Busy then return "Tunggu Auto Drop selesai dulu." end
        local err = checkAutoStart()
        if err then return err end
        if #parseFactoryOffsets() == 0 then
            return "Pilih tile dulu di Grid Tile tab Auto PnB."
        end

        if State.Running then stopFarm("Dihentikan karena Factory dimulai") end
        if Clear.Running and stopClear then stopClear("Dihentikan karena Factory dimulai") end
        if Splice.Running and Splice.stop then Splice.stop("Dihentikan karena Factory dimulai") end
        if Pabrik.Running and Pabrik.stop then Pabrik.stop("Dihentikan karena Factory dimulai") end
        if Build.Running and Build.stop then Build.stop("Dihentikan karena Factory dimulai") end
        if Vend.Running and Vend.stop then Vend.stop("Dihentikan karena Factory dimulai") end
        if Hvs.Running then Hvs.stop("Dihentikan karena Factory dimulai") end
        if (plantState.running or plantState.workerActive) and stopAutoPlant then
            stopAutoPlant("Dihentikan karena Factory dimulai")
        end

        if not Refs.Trees then pcall(findTreeRefs) end
        F.Rotating = false
        F.Harvesting = false
        F.Planting = false
        F.PnbX, F.PnbY = -1, -1
        F.Phase = "Memulai"
        F.Status = "Memulai Factory..."
        F.On = true
        F.Running = true
        F.WorkerActive = true
        F.RunId = (F.RunId or 0) + 1
        local id = F.RunId
        if UI.FactoryToggle then pcall(function() UI.FactoryToggle:Set(true, true) end) end

        task.spawn(function()
            local ok, e = pcall(factoryLoop, id)
            if not ok then
                warn("[ByteHub] Factory error: " .. tostring(e))
            end
            F.WorkerActive = false
            if F.RunId == id and F.Running then
                F.stop(not ok and ("Error Factory: " .. tostring(e)) or nil)
            end
        end)
        return nil
    end

    function F.stop(reason)
        local was = F.Running
        F.Running = false
        F.On = false
        F.RunId = (F.RunId or 0) + 1
        F.Rotating = false
        clearRotationPending()

        if F.Harvesting or Hvs.Running then
            pcall(Hvs.stop)
        end
        if State.Override and State.Running then
            State.Running = false
            State.Override = nil
            State.Quiet = false
        end
        if F.Planting or plantState.running then
            if stopAutoPlant then pcall(stopAutoPlant, "Dihentikan karena Factory berhenti") end
        end
        plantState.skipBottomRow = false

        F.Harvesting = false
        F.Planting = false
        F.PnbX, F.PnbY = -1, -1
        Hvs.Dropping, Hvs.DropLive = false, nil
        restoreHarvestSettings()
        autoEnd()
        releaseInput()

        F.Phase = "Mati"
        F.Status = reason and ("Berhenti: " .. tostring(reason)) or "Mati"
        if UI.FactoryToggle then pcall(function() UI.FactoryToggle:Set(false, true) end) end
        if was and reason then
            notify("Factory", F.Status, 4)
        end
    end

    F.parseOffsets = parseFactoryOffsets
    F.findSafeSpot = findSafePnBSpot
    F.scanWorldTrees = scanWorldTrees
    F.ensureTreeRefs = ensureFactoryTreeRefs
    F.parseRotationWorlds = parseRotationWorlds
    F.nextRotationWorld = nextRotationWorld
    F.saveRotationPending = saveRotationPending
    F.readRotationPending = readRotationPending
    F.clearRotationPending = clearRotationPending

    task.spawn(function()
        local pending = readRotationPending()
        if not pending then return end

        local function applyPendingSettings(p)
            F.RotationOn = true
            if type(p.RotationWorldsText) == "string" and p.RotationWorldsText ~= "" then
                F.RotationWorldsText = p.RotationWorldsText
            end
            if tonumber(p.RotationIndex) then
                F.RotationIndex = math.max(1, math.floor(tonumber(p.RotationIndex)))
            end
            if tonumber(p.RotationDelaySec) then
                F.RotationDelaySec = math.clamp(math.floor(tonumber(p.RotationDelaySec)), 1, 15)
            end
            if tonumber(p.DropX) and tonumber(p.DropY) then
                F.DropX = tonumber(p.DropX)
                F.DropY = tonumber(p.DropY)
            end
            if tonumber(p.DropFacing) then
                F.DropFacing = tonumber(p.DropFacing) < 0 and -1 or 1
            end
            if tonumber(p.DropGuardSec) then
                F.DropGuardSec = math.clamp(tonumber(p.DropGuardSec), 1, 5)
            end
            if tonumber(p.SafeDist) then
                F.SafeDist = math.clamp(math.floor(tonumber(p.SafeDist)), 1, 8)
            end
            if tonumber(p.BlockLimit) then
                F.BlockLimit = math.clamp(math.floor(tonumber(p.BlockLimit)), 20, 200)
            end
            if tonumber(p.SeedDropAt) then
                F.SeedDropAt = math.clamp(math.floor(tonumber(p.SeedDropAt)), 50, 200)
            end
        end

        F.Rotating = true
        applyPendingSettings(pending)
        F.RotationStatus = "Resume ke " .. tostring(pending.TargetWorld)

        local readyDeadline = os.clock() + 30
        while alive() and os.clock() < readyDeadline do
            if Session.Ready and next(ItemDB) ~= nil then break end
            task.wait(0.25)
        end
        if not alive() then
            F.Rotating = false
            return
        end

        applyPendingSettings(pending)
        if UI.FactoryRotationToggle and UI.FactoryRotationToggle.Set then
            pcall(UI.FactoryRotationToggle.Set, UI.FactoryRotationToggle, true, true)
        end
        if UI.FactoryRotationInput and UI.FactoryRotationInput.Set then
            pcall(UI.FactoryRotationInput.Set, UI.FactoryRotationInput, tostring(F.RotationWorldsText or ""), true)
        end
        if UI.FactoryDropDir and UI.FactoryDropDir.Select then
            pcall(UI.FactoryDropDir.Select, UI.FactoryDropDir, (F.DropFacing < 0) and "Kiri" or "Kanan")
        end

        local spawnWait = os.clock() + 5
        while alive() and F.RotationOn and os.clock() < spawnWait do
            if normalizeRotationWorld(Guard.worldName()) == pending.TargetWorld then break end
            task.wait(0.25)
        end

        local cur = normalizeRotationWorld(Guard.worldName())
        if cur ~= pending.TargetWorld and alive() and F.RotationOn then
            saveRotationPending(pending.TargetWorld, F.RotationIndex)
            queueFactoryLoader()
            local entered = false
            for _ = 1, 3 do
                if not alive() or not F.RotationOn then break end
                if normalizeRotationWorld(Guard.worldName()) ~= "" then
                    pcall(Guard.leaveWorld)
                    local exitDead = os.clock() + 4
                    while alive() and os.clock() < exitDead and normalizeRotationWorld(Guard.worldName()) ~= "" do
                        task.wait(0.2)
                    end
                end
                local okE, _, hoppingE = Guard.enterWorld(pending.TargetWorld)
                if hoppingE == true then
                    return
                end
                if okE then
                    entered = true
                    break
                end
                task.wait(2.5)
            end
            if not entered then
                clearRotationPending()
                F.Rotating = false
                F.RotationStatus = "Gagal resume masuk " .. tostring(pending.TargetWorld)
                return
            end
        end

        if not alive() or not F.RotationOn then
            F.Rotating = false
            return
        end

        pcall(Guard.afterEnter)
        clearRotationPending()
        F.Rotating = false
        F.BlockId, F.SeedId = nil, nil
        table.clear(F.TrackedBlocks)
        F.RotationStatus = "Aktif di " .. tostring(pending.TargetWorld)
        task.wait(1.5)
        if alive() and F.RotationOn and not F.Running then
            local startErr = F.start()
            if startErr then
                F.RotationStatus = "Gagal auto-start: " .. tostring(startErr)
                notify("Factory Rotation", F.RotationStatus, 4)
            end
        end
    end)
end)() end

-- Auto Plant berjalan di luar mount ini; ia memanggil ini supaya mesin farm
-- berhenti lebih dulu (hanya satu mesin yang boleh aktif).
Session.stopAllForPlant = function()
    Hvs.Running, Hvs.On = false, false
    if State.Running then stopFarm("Dihentikan karena Auto Plant dimulai") end
    if Clear.Running then stopClear("Dihentikan karena Auto Plant dimulai") end
    if Splice.Running and Splice.stop then Splice.stop("Dihentikan karena Auto Plant dimulai") end
    if Pabrik.Running then Pabrik.stop("Dihentikan karena Auto Plant dimulai") end
    if Build.Running then Build.stop("Dihentikan karena Auto Plant dimulai") end
    if Vend.Running and Vend.stop then Vend.stop("Dihentikan karena Auto Plant dimulai") end
    if Session.Factory and Session.Factory.Running and not Session.Factory.Planting and Session.Factory.stop then
        Session.Factory.stop("Dihentikan karena Auto Plant dimulai")
    end
end
end)() end -- fungsi sendiri: variabel di dalam tidak ikut batas 200 local

--// --- Bridge untuk tab Auto Plant (dipakai sebelum suite lain menyala) ---
-- Auto Plant butuh navigasi A* (jump/tangga/gap) dan daftar drop world. Semua
-- mesin itu hidup di dalam suite ini, jadi diekspos lewat tabel global.
do (function() -- fungsi sendiri: variabel di dalam tidak ikut batas 200 local
local function plantSeedDropCount(seedId)
    local ok, found = pcall(findDropRefs, false)
    if not ok or not found or not Drops.list then return nil end
    local count = 0
    local wanted = tonumber(seedId) or seedId
    for _, drop in pairs(Drops.list) do
        if type(drop) == "table" and (tonumber(drop.id) or drop.id) == wanted then
            count += math.max(0, tonumber(drop.n) or 0)
        end
    end
    return count
end

-- Daftar seed untuk dropdown, termasuk seed yang stok inventori-nya kosong.
local function plantSeedDropCounts()
    if not Drops.list then pcall(findDropRefs, false) end
    local counts = {}
    for _, drop in pairs(Drops.list or {}) do
        if type(drop) == "table" then
            local id = tonumber(drop.id) or drop.id
            local amount = tonumber(drop.n) or 0
            if id ~= nil and amount > 0 then
                counts[id] = (counts[id] or 0) + amount
            end
        end
    end
    return counts
end

local function plantSeedDropFilter(seedId)
    local wanted = tonumber(seedId) or seedId
    return function(drop)
        return (tonumber(drop.id) or drop.id) == wanted
    end
end

-- Pilih rute dengan biaya terendah ke pijakan dalam jendela tanam.
local function plantWalkTo(ty, columns, live)
    local w = Refs.World
    if not w or not OrigIsDown or not live() then return false end

    local moveEpoch = beginPlantMove()
    Move.Homing = true
    Move.HomingLive = live
    autoBegin()

    local arrived, reason = false, nil
    for _ = 1, 3 do
        local s = playerState()
        if not live() or Refs.World ~= w or not s or s.dead then break end

        -- Gunakan jendela tanam yang sama dengan worker, termasuk kolom target.
        local goals = {}
        for tx in pairs(columns) do
            for x = math.max(0, tx - 1), math.min(w.w - 1, tx + 1) do
                if openAt(x, ty) and realSupport(x, ty) then
                    goals[ty * w.w + x] = true
                end
            end
        end
        if not next(goals) then
            reason = "unreachable"
            break
        end
        goals.costOnly = true
        -- Auto Plant boleh memakai jalur jatuh panjang: game ini tidak memiliki
        -- fall damage, sehingga batas jatuh default 40 tile terlalu ketat untuk
        -- berpindah antar-walkway / kembali ke lantai yang dapat dicapai.
        goals.allowLongFall = true
        local currentX, currentY = floor(s.x), floor(s.y - 0.475)
        if s.grounded and goals[currentY * w.w + currentX] then
            arrived = true
            break
        end
        local sx, sy = startNode(s)
        local path, exhausted = astar(sx, sy, goals, currentX, ty, 0.5, false)
        if not live() then break end
        if not path then
            if exhausted then reason = "unreachable" end
            break
        end
        if #path == 0 then
            if s.grounded and sy == ty and execWalk(sx, sy, 0.08) then
                arrived = live()
                break
            end
        else
            followPath(path)
        end
        releaseInput()
        task.wait()
    end

    -- Langkah terakhir pada upaya ketiga mungkin sudah mencapai pijakan.
    local s = playerState()
    if not arrived and s and s.grounded and live() and Refs.World == w then
        local x, y = floor(s.x), floor(s.y - 0.475)
        arrived = y == ty and openAt(x, y) and realSupport(x, y)
            and (columns[x - 1] or columns[x] or columns[x + 1]) == true
    end
    releaseInput()
    Move.Homing, Move.HomingLive = false, nil
    autoEnd()
    endPlantMove(moveEpoch)
    return arrived, reason
end

-- Susuri satu baris (lantai) sambil BERLARI, tanpa berhenti tiap tile.
-- onColumn(col) dipanggil untuk tiap kolom yang dilalui (menanam tile kolom itu
-- dan tetangganya). Lubang di baris ditambal dengan block dirt bila tersedia;
-- kalau tidak ada dirt, baris berhenti dan sisa tile dilewati (tidak ditanam
-- dari baris lain). Callback bisa menghentikan sapuan untuk stok atau tile terlewat.
local function plantRunRow(ty, toX, dirtId, onColumn, live)
    local w = Refs.World
    if not w or not OrigIsDown then return "nobridge" end
    live = live or function() return true end
    local wasActive = AutoInput.active
    local moveEpoch = beginPlantMove()
    AutoInput.active = true
    local result = "done"
    local lastCol = nil
    local t0 = os.clock()
    while live() and alive() and os.clock() - t0 < 180 do
        local s = playerState()
        if not s or s.dead then result = "stop" break end
        local row = floor(s.y - 0.475)
        if row ~= ty then result = "left" break end -- jatuh/naik tak sengaja: serahkan ke A*
        local col = floor(s.x)
        local dir = (toX >= col) and 1 or -1
        if col ~= lastCol then
            lastCol = col
            if onColumn then
                local r = onColumn(col, dir)
                if r then result = r break end
            end
        end
        if col == toX then
            -- tiba di ujung: berhenti di tengah tile
            steerX(s, toX + 0.5, 0.1)
            if abs(s.x - (toX + 0.5)) <= 0.12 and abs(s.vx or 0) < 2 then
                AutoInput.left, AutoInput.right = false, false
                if onColumn then result = onColumn(toX, dir) or result end
                break
            end
            task.wait()
            continue
        end
        local nx = col + dir
        if nx < 0 or nx >= w.w then result = "blocked" break end
        -- Tidak ada pijakan di kolom berikutnya: tambal dengan dirt kalau ada.
        if not (openAt(nx, ty) and realSupport(nx, ty)) then
            if not dirtId or invCount(dirtId) <= 0 then result = "blocked" break end
            if not placeOk(nx, ty + 1) then result = "blocked" break end
            local s2 = playerState()
            if not s2 or not stateReaches(s2, nx, ty + 1, buildReach() - 0.05) then
                result = "blocked"
                break
            end
            sendSetTile("fg", nx, ty + 1, dirtId)
            if Refs.Inv then pcall(function() Refs.Inv:remove(dirtId, 1) end) end
            Move.Placed += 1
            task.wait(0.1)
            if not live() then result = "stop" break end
            if not (openAt(nx, ty) and realSupport(nx, ty)) then result = "blocked" break end
        end
        -- Dekati ujung berikutnya; hanya berhenti (rem) saat sudah dekat tujuan.
        local remaining = abs((nx + 0.5) - s.x)
        if remaining <= 0.65 then
            steerX(s, nx + 0.5, 0.12)
        else
            AutoInput.left = dir < 0
            AutoInput.right = dir > 0
        end
        task.wait()
    end
    AutoInput.left, AutoInput.right = false, false
    releaseInput()
    endPlantMove(moveEpoch, wasActive)
    return result
end

-- Cari pijakan yang bisa dicapai di sekitar drop, tanpa bergantung pada rute ujung baris.
local function plantRouteToSeed(matchesSeed, live)
    local w, state = Refs.World, playerState()
    if not w or not state or state.dead or not live() then return false end
    local goals, goalDrops = {}, {}
    local now = os.clock()

    for _, drop in pairs(Drops.list or {}) do
        if type(drop) == "table" and matchesSeed(drop) and type(drop.y) == "number"
            and canTry(drop, now, true) then
            local col, row = floor(drop.x), floor(drop.y)
            for y = math.max(0, row), math.min(w.h - 1, row + 2) do
                for x = math.max(0, col - 1), math.min(w.w - 1, col + 1) do
                    local feetY = y + 0.975
                    if abs(x + 0.5 - drop.x) < 0.6 and drop.y < feetY + 0.3
                        and drop.y > feetY - 2.6 and openAt(x, y) and realSupport(x, y)
                        and Move.los(x, y, col, row) then
                        local key = y * w.w + x
                        goals[key] = true
                        local previous = goalDrops[key]
                        if not previous or abs(drop.y - feetY) < abs(previous.y - feetY) then
                            goalDrops[key] = drop
                        end
                    end
                end
            end
        end
    end

    if not next(goals) then return false end
    goals.costOnly, goals.allowLongFall = true, true
    local sx, sy = startNode(state)
    local path = astar(sx, sy, goals, sx, sy, 0.5, false)
    if not path or not live() then return false end
    local last = path[#path]
    if last and not followPath(path) then return false end
    if not live() then return true end

    local drop = goalDrops[last and (last.y * w.w + last.x) or (sy * w.w + sx)]
    if not drop then return false, nil end

    local arrived = playerState()
    if drop and arrived and arrived.grounded and (drop.n or 0) > 0
        and abs(drop.x - arrived.x) < 0.9 and drop.y < arrived.y - 0.9
        and openAt(floor(arrived.x), floor(arrived.y - 0.475) - 1) then
        AutoInput.jump = true
        task.wait(0.15)
        AutoInput.jump = false
    end
    waitNearDrops(0.6, live)
    return true, drop
end

local function plantFetchSeedDrops(seedId, live)
    live = live or function() return true end
    local initialStock = invCount(seedId)
    local t0 = os.clock()
    local wasActive = AutoInput.active
    local moveEpoch = beginPlantMove()
    local baseMatchesSeed = plantSeedDropFilter(seedId)
    local targetRetryAt = {}
    local function matchesSeed(drop)
        if not baseMatchesSeed(drop) then return false end
        local retryKey = drop.uid or drop
        local retryAt = targetRetryAt[retryKey]
        return not retryAt or os.clock() >= retryAt
    end
    local directAttempted = {}

    local function canFetch()
        if not live() then return false end
        local inventory = Refs.Inv
        if not inventory then return true end
        local ok, room = pcall(function() return inventory:room(seedId) end)
        return not ok or type(room) ~= "number" or room > 0
    end

    local function needsSeed()
        return canFetch() and invCount(seedId) <= 0
    end

    local function targetStillExists(drop)
        return type(drop) == "table"
            and (tonumber(drop.n) or 0) > 0
            and table.find(Drops.list or {}, drop) ~= nil
    end

    -- Percobaan remote awal tidak menggerakkan avatar. Jika gagal, target
    -- tetap dicoba melalui rute fisik satu per satu di bawah.
    local function takeDroppedSeedsDirect()
        if not needsSeed() then return 0 end
        pcall(findDropRefs, false)
        local list = Drops.list
        if type(list) ~= "table" then return 0 end

        local wanted = tonumber(seedId) or seedId
        local candidates = {}
        for _, drop in pairs(list) do
            if type(drop) == "table"
                and (tonumber(drop.id) or drop.id) == wanted
                and (tonumber(drop.n) or 0) > 0 then
                candidates[#candidates + 1] = drop
            end
        end

        local collected = 0
        for _, drop in ipairs(candidates) do
            if not needsSeed() then break end
            local uid = drop.uid
            if uid == nil or not directAttempted[uid] then
                if uid ~= nil then directAttempted[uid] = true end
                local before = invCount(seedId)
                local callOK, result = pcall(takeDrop, drop, true)
                if not callOK then
                    AP_log("WARN", "Direct seed pickup gagal: " .. tostring(result))
                end
                local after = invCount(seedId)
                if after > before then
                    collected += after - before
                elseif uid ~= nil then
                    DropFailUntil[uid] = nil
                end
                task.wait(0.06)
            end
        end
        return collected
    end

    -- Satu iterasi hanya memilih satu target. Target yang gagal diberi jeda
    -- lokal agar rute berikutnya memilih drop lain, bukan bolak-balik ke titik
    -- yang sama. Tidak ada lagi sapuan baris atau reposisi kanan-kiri.
    local function approachAndTakeOne()
        pcall(findDropRefs, false)
        local routed, target = plantRouteToSeed(matchesSeed, canFetch)
        if not canFetch() then return "cancelled" end
        if not routed or not target then return "no-route" end
        if not targetStillExists(target) then return "refreshed" end

        local uid = target.uid
        local before = invCount(seedId)
        if uid ~= nil then DropFailUntil[uid] = nil end

        -- Avatar sudah berada di pijakan terdekat dari satu target ini.
        local directOK, directResult = pcall(takeDrop, target, true)
        if not directOK then
            AP_log("WARN", "Pickup target seed gagal: " .. tostring(directResult))
        end
        task.wait(0.12)

        if invCount(seedId) > before or not targetStillExists(target) then
            return "collected"
        end
        if not canFetch() then return "cancelled" end

        -- Jika pickup langsung ditolak, dekati target yang sama. Jangan
        -- berpindah ke drop lain sebelum upaya target ini selesai.
        if type(Move.visitDrop) == "function" and targetStillExists(target) then
            local visitOK, visitResult = pcall(Move.visitDrop, target, canFetch)
            if not visitOK then
                AP_log("WARN", "Gerak ke target seed gagal: " .. tostring(visitResult))
            end
        end
        if not canFetch() then return "cancelled" end

        if invCount(seedId) > before or not targetStillExists(target) then
            return "collected"
        end

        -- Coba sekali lagi setelah avatar berada dekat drop.
        if uid ~= nil then DropFailUntil[uid] = nil end
        local retryOK, retryResult = pcall(takeDrop, target, true)
        if not retryOK then
            AP_log("WARN", "Retry pickup seed gagal: " .. tostring(retryResult))
        end
        task.wait(0.12)

        if invCount(seedId) > before or not targetStillExists(target) then
            return "collected"
        end

        -- Lewati sementara target yang tidak dapat diambil. Setelah cooldown
        -- habis, target boleh dicoba lagi jika masih ada di world.
        if uid ~= nil then DropFailUntil[uid] = nil end
        targetRetryAt[uid or target] = os.clock() + 2.5
        return "unavailable"
    end

    local okP, err = pcall(function()
        autoBegin()
        while canFetch() and alive() and os.clock() - t0 < 200 do
            AutoInput.active = true
            Move.Homing = true
            Move.HomingLive = canFetch

            pcall(findDropRefs, false)
            local count = plantSeedDropCount(seedId)
            if not count or count == 0 then break end

            if needsSeed() then
                takeDroppedSeedsDirect()
            end
            if not canFetch() or not needsSeed() then break end

            local result = approachAndTakeOne()
            if result == "cancelled" then break end

            if result == "no-route" or result == "unavailable" or result == "refreshed" then
                task.wait(0.35)
            elseif result == "collected" then
                task.wait(0.1)
            end
        end
    end)

    Move.Homing, Move.HomingLive = false, nil
    autoEnd()
    releaseInput()
    endPlantMove(moveEpoch, wasActive)
    if not okP then warn("[ByteHub] Auto Plant ambil seed: " .. tostring(err)) end
    return math.max(0, invCount(seedId) - initialStock)
end

executorEnv.__plantBridge = {
    ready = function()
        return Refs.World ~= nil and OrigIsDown ~= nil
    end,
    world = function()
        return Refs.World
    end,
    inventory = function()
        return Refs.Inv
    end,
    itemDB = function()
        return ItemDB
    end,
    canPlant = function(seedId, x, y)
        if not Refs.World or type(ItemDB) ~= "table" then return false end
        return plantSpotOk(x, y, seedId)
    end,
    plantTile = function(seedId, x, y)
        if not Refs.World or type(ItemDB) ~= "table" then return false end
        if not plantSpotOk(x, y, seedId) then return false end
        return sendSetTile("fg", x, y, seedId)
    end,
    playerPosition = function()
        local s = playerState()
        if not s then return nil, nil end
        return s.x, s.y
    end,
    buildRange = function()
        return buildReach()
    end,
    walkTo = function(tx, ty, maxSec, live, allowLongFall)
        return walkTo(tx, ty, maxSec or 30, live, nil, allowLongFall == true)
    end,
    seedDropCount = plantSeedDropCount,
    seedDropCounts = plantSeedDropCounts,
    fetchSeedDrops = plantFetchSeedDrops,
    cancelAutoPlant = cancelPlantMove,
    walkToPlant = plantWalkTo,
    runRow = plantRunRow,
    landRows = landRows,
    setMoveSpeed = function(pct)
        AutoInput.speed = (type(pct) == "number" and pct > 0) and pct or nil
        AutoInput.fastWalk = type(pct) == "number" and pct > 120 or false
    end,
}
end)() end -- fungsi sendiri: variabel di dalam tidak ikut batas 200 local
end)() end -- do (gerak otomatis)

