                    return
                end
                local wasEnabled = Hook.On
                Hook.On = true
                Hook.send("test", "Test notification from ByteHub")
                Hook.On = wasEnabled
                notify("Discord", "Pesan percobaan dimasukkan ke antrean.", 3)
