        { "Pabrik", "Pabrik dan Vending", "Pemberitahuan aktivitas pabrik, vending, dan build." },
    }) do
        safe(function()
            dWhat:Toggle({
                Title = item[2],
                Desc = item[3],
                Value = Hook[item[1]],
                Callback = function(on)
                    Hook[item[1]] = on == true
                    saveDiscord()
                end,
            })
        end)
    end

    task.spawn(function()
        while alive() do
            if UI.HookStatus then
                pcall(function() UI.HookStatus:SetDesc(Hook.Status or "-") end)
            end
            task.wait(1)
        end
    end)
end)() end

