            },
        }
        Env.__ByteHubAutoReconnect = Runtime

        local function active()
            return Runtime.Active
                and Env.__ByteHubAutoReconnect == Runtime
                and type(Bridge.isAlive) == "function"
                and Bridge.isAlive()
        end

        local function addConnection(connection)
            if connection and type(connection.Disconnect) == "function" then
                Runtime.Connections[#Runtime.Connections + 1] = connection
            end
            return connection
        end

        local DEFAULT_LOADER_URL = "https://raw.githubusercontent.com/brbrpatapimm/plerr/main/NewUI_Second_95.lua"
        local PREVIOUS_LOADER_URL_V94 = "https://raw.githubusercontent.com/brbrpatapimm/plerr/main/NewUI_Second_94.lua"
        local PREVIOUS_LOADER_URL_V93 = "https://raw.githubusercontent.com/brbrpatapimm/plerr/main/NewUI_Second_93.lua"
        local PREVIOUS_LOADER_URL_V92 = "https://raw.githubusercontent.com/brbrpatapimm/plerr/main/NewUI_Second_92.lua"
        local PREVIOUS_LOADER_URL_V91 = "https://raw.githubusercontent.com/brbrpatapimm/plerr/main/NewUI_Second_91.lua"
        local PREVIOUS_LOADER_URL_V90 = "https://raw.githubusercontent.com/brbrpatapimm/plerr/main/NewUI_Second_90.lua"
        local PREVIOUS_LOADER_URL_V89 = "https://raw.githubusercontent.com/brbrpatapimm/plerr/main/NewUI_Second_89.lua"
        local PREVIOUS_LOADER_URL_V83_BLOB = "https://github.com/brbrpatapimm/plerr/blob/main/NewUI_Second_83.lua"
        local PREVIOUS_LOADER_URL_V88 = "https://raw.githubusercontent.com/brbrpatapimm/plerr/main/NewUI_Second_88.lua"
        local PREVIOUS_LOADER_URL_V73 = "https://raw.githubusercontent.com/brbrpatapimm/plerr/main/NewUI_Second_73.lua"
        local LEGACY_LOADER_URL = "https://raw.githubusercontent.com/farelfirmansyah323-dot/growbloxcit/main/ByteHub_Loader.lua"

        local function normalizeLoaderUrl(value)
            local url = tostring(value or ""):gsub("^%s+", ""):gsub("%s+$", "")
            if url == "" or url == LEGACY_LOADER_URL
                or url == PREVIOUS_LOADER_URL_V94
                or url == PREVIOUS_LOADER_URL_V93
                or url == PREVIOUS_LOADER_URL_V92
                or url == PREVIOUS_LOADER_URL_V91
                or url == PREVIOUS_LOADER_URL_V90
                or url == PREVIOUS_LOADER_URL_V89
                or url == PREVIOUS_LOADER_URL_V83_BLOB
                or url == PREVIOUS_LOADER_URL_V88 or url == PREVIOUS_LOADER_URL_V73 then
                return DEFAULT_LOADER_URL
            end

            local owner, repo, branch, filePath = url:match(
                "^https://github%.com/([^/]+)/([^/]+)/blob/([^/]+)/([^?#]+)"
            )
            if owner and repo and branch and filePath then
                url = "https://raw.githubusercontent.com/" .. owner .. "/" .. repo .. "/" .. branch .. "/" .. filePath
            else
                owner, repo, branch, filePath = url:match(
                    "^https://github%.com/([^/]+)/([^/]+)/raw/([^/]+)/([^?#]+)"
                )
                if owner and repo and branch and filePath then
                    url = "https://raw.githubusercontent.com/" .. owner .. "/" .. repo .. "/" .. branch .. "/" .. filePath
                end
            end

            return url
        end

        local Reconnect = {
            On = false,
            Fallback = true,
            World = true,
            Server = true,
            Keep = false,
            DelaySec = 5,
            LoaderUrl = DEFAULT_LOADER_URL,
            Target = "",
            LastWorld = "",
            Last = nil,
            LastAt = 0,
            Busy = false,
            Disconnecting = false,
            Status = "Siap",
            CycleOn = false,
            CycleFeatures = {},
            CycleIntervalMode = "5 Minutes",
            CycleCustomMinutes = 5,
            CycleIndex = 1,
            CycleWorld = "",
        }

        local CYCLE_FEATURES = { "Auto PnB", "Auto Plant", "Auto Harvest", "Factory" }
        local CYCLE_INTERVALS = { "5 Minutes", "10 Minutes", "15 Minutes", "30 Minutes", "Custom" }

        local function normalizeCycleFeatures(values)
            local selected = {}
            if type(values) == "table" then
                for _, value in ipairs(values) do
                    if type(value) == "string" then selected[value] = true end
                end
            elseif type(values) == "string" then
                selected[values] = true
            end
            local result = {}
            for _, feature in ipairs(CYCLE_FEATURES) do
                if selected[feature] then result[#result + 1] = feature end
            end
            return result
        end

        local function normalizeCycleInterval(value)
            for _, option in ipairs(CYCLE_INTERVALS) do
                if value == option then return option end
            end
            return "5 Minutes"
        end

        Reconnect.CycleFeatures = normalizeCycleFeatures(Reconnect.CycleFeatures)
        Reconnect.CycleIntervalMode = normalizeCycleInterval(Reconnect.CycleIntervalMode)
        Reconnect.CycleCustomMinutes = math.clamp(math.floor(tonumber(Reconnect.CycleCustomMinutes) or 5), 1, 1440)

        local CONFIG_KEYS = {
            "On", "Fallback", "World", "Server", "Keep",
            "DelaySec", "LoaderUrl", "Target",
            "CycleOn", "CycleFeatures", "CycleIntervalMode", "CycleCustomMinutes", "CycleIndex", "CycleWorld",
        }

        if type(Bridge.registerConfig) == "function" then
            local ok, err = Bridge.registerConfig("Reconnect", Reconnect, CONFIG_KEYS)
            if not ok then
                warn("[ByteHub] Gagal mendaftarkan konfigurasi Auto Reconnect: " .. tostring(err))
            end
        end

        -- Config.add dapat memuat nilai lama setelah nilai default dibuat.
        -- Normalisasi ulang agar UI dan scheduler menerima tipe/nilai yang valid.
        Reconnect.CycleFeatures = normalizeCycleFeatures(Reconnect.CycleFeatures)
        Reconnect.CycleIntervalMode = normalizeCycleInterval(Reconnect.CycleIntervalMode)
        Reconnect.CycleCustomMinutes = math.clamp(math.floor(tonumber(Reconnect.CycleCustomMinutes) or 5), 1, 1440)
        Reconnect.CycleIndex = math.max(1, math.floor(tonumber(Reconnect.CycleIndex) or 1))
        Reconnect.CycleWorld = type(Reconnect.CycleWorld) == "string" and Reconnect.CycleWorld or ""

        -- Loader URL dinormalisasi setelah penyimpanan khusus Auto Reconnect dimuat.

        local HttpService = game:GetService("HttpService")
        local TeleportService = game:GetService("TeleportService")
        local GuiService = game:GetService("GuiService")
        local CoreGui = game:GetService("CoreGui")
        local Player = type(Bridge.getPlayer) == "function" and Bridge.getPlayer() or nil

        local USER_ID = Player and Player.UserId or 0
        local FOLDER = "ByteHub"
        local PENDING_FILE = FOLDER .. "/reconnect_" .. tostring(USER_ID) .. ".json"
        local TELEPORT_KEY = "ByteHub.AutoReconnect.v1"

        local function notify(message, duration)
            if type(Bridge.notify) == "function" then
                pcall(Bridge.notify, "Auto Reconnect", tostring(message), duration or 3)
            end
        end

        local function setStatus(message)
            Reconnect.Status = tostring(message or "")
            local text = ("Status: %s\nBerhasil reconnect: %d"):format(Reconnect.Status, Runtime.Count)
            if Bridge.StatusLabel and type(Bridge.StatusLabel.Set) == "function" then
                pcall(Bridge.StatusLabel.Set, Bridge.StatusLabel, text)
            end
        end

        local function saveConfig()
            local persistentSaved = false
            if type(Runtime.PersistSettings) == "function" then
                local ok, result = pcall(Runtime.PersistSettings)
                persistentSaved = ok and result == true
            end

            local configSaved = false
            if type(Bridge.saveConfig) == "function" then
                local ok, result = pcall(Bridge.saveConfig, true)
                configSaved = ok and result == true
            elseif type(Bridge.saveCycleConfig) == "function" then
                local ok, result = pcall(Bridge.saveCycleConfig)
                configSaved = ok and result == true
            end
            return persistentSaved or configSaved
        end

        local function saveCycleConfig()
            local persistentSaved = false
            if type(Runtime.PersistSettings) == "function" then
                local ok, result = pcall(Runtime.PersistSettings)
                persistentSaved = ok and result == true
            end

            local configSaved = false
            if type(Bridge.saveCycleConfig) == "function" then
                local ok, result = pcall(Bridge.saveCycleConfig)
                configSaved = ok and result == true
            elseif type(Bridge.saveConfig) == "function" then
                local ok, result = pcall(Bridge.saveConfig, true)
                configSaved = ok and result == true
            end
            return persistentSaved or configSaved
        end

        local function normalizeWorld(value)
            return tostring(value or ""):upper():gsub("[^A-Z0-9]", "")
        end

        local function targetWorld()
            local requested = normalizeWorld(Reconnect.Target)
            if requested ~= "" then return requested end
            return normalizeWorld(Reconnect.LastWorld)
        end

        local function hasSavedActivity(saved)
            if type(saved) ~= "table" then return false end
            for _, key in ipairs({
                "plant", "farm", "clear", "spam", "splice",
                "pabrik", "build", "vend", "harvest", "factory",
            }) do
                if saved[key] == true then return true end
            end
            return false
        end

        local function captureSnapshot()
            if type(Bridge.captureSnapshot) ~= "function" then return nil end
            local ok, saved = pcall(Bridge.captureSnapshot)
            if not ok or type(saved) ~= "table" then return nil end
            if type(saved.world) ~= "string" or saved.world == "" then
                saved.world = Bridge.getWorld()
            end
            return saved
        end

        local function ensureFolder()
            if type(isfolder) == "function" and type(makefolder) == "function" then
                local ok, exists = pcall(isfolder, FOLDER)
                if ok and not exists then pcall(makefolder, FOLDER) end
            end
        end

        local function isFactoryRunning()
            return Bridge.Owner and Bridge.Owner.Factory and Bridge.Owner.Factory.Running == true
        end

        local function fallbackActive()
            return Reconnect.Fallback == true or isFactoryRunning()
        end

        Runtime.isFallbackActive = fallbackActive

        -- Pengaturan Auto Reconnect disimpan terpisah dari preset Auto Farm.
        -- File ini ditulis langsung saat callback UI berubah, sehingga tidak
        -- bergantung pada antrean task.delay atau Config.CurrentName.
        do
            local SETTINGS_FILE = FOLDER .. "/autoreconnect_" ..
                tostring(USER_ID) .. "_" .. tostring(game.PlaceId) .. ".json"

            local function normalizeStoredSettings()
                Reconnect.On = Reconnect.On == true
                Reconnect.Fallback = Reconnect.Fallback == true
                Reconnect.World = Reconnect.World == true
                Reconnect.Server = Reconnect.Server == true
                Reconnect.Keep = Reconnect.Keep == true
                Reconnect.DelaySec = math.clamp(math.floor(tonumber(Reconnect.DelaySec) or 5), 2, 60)
                Reconnect.LoaderUrl = normalizeLoaderUrl(Reconnect.LoaderUrl)
                Reconnect.Target = tostring(Reconnect.Target or "")
                Reconnect.CycleOn = Reconnect.CycleOn == true
                Reconnect.CycleFeatures = normalizeCycleFeatures(Reconnect.CycleFeatures)
                Reconnect.CycleIntervalMode = normalizeCycleInterval(Reconnect.CycleIntervalMode)
                Reconnect.CycleCustomMinutes = math.clamp(
                    math.floor(tonumber(Reconnect.CycleCustomMinutes) or 5), 1, 1440
                )
                Reconnect.CycleIndex = math.max(1, math.floor(tonumber(Reconnect.CycleIndex) or 1))
                Reconnect.CycleWorld = tostring(Reconnect.CycleWorld or "")
            end

            local function writeSettings()
                if type(writefile) ~= "function" then return false end
                ensureFolder()

                local settings = {}
                for _, key in ipairs(CONFIG_KEYS) do
                    local value = Reconnect[key]
                    if type(value) == "table" then
                        local copied = {}
                        for index, item in ipairs(value) do copied[index] = item end
                        settings[key] = copied
                    else
                        settings[key] = value
                    end
                end

                local payload = {
                    Schema = 1,
                    UserId = USER_ID,
                    PlaceId = game.PlaceId,
                    SavedAt = os.time(),
                    Settings = settings,
                }

                local okEncode, encoded = pcall(HttpService.JSONEncode, HttpService, payload)
                if not okEncode or type(encoded) ~= "string" then return false end

                local okWrite, result = pcall(writefile, SETTINGS_FILE, encoded)
                return okWrite and result ~= false
            end

            local function readSettings()
                if type(isfile) ~= "function" or type(readfile) ~= "function" then
                    return false
                end

                local okExists, exists = pcall(isfile, SETTINGS_FILE)
                if not okExists or not exists then return false end

                local okRead, raw = pcall(readfile, SETTINGS_FILE)
                if not okRead or type(raw) ~= "string" then return false end

                local okDecode, payload = pcall(HttpService.JSONDecode, HttpService, raw)
                if not okDecode or type(payload) ~= "table"
                    or payload.Schema ~= 1
                    or tonumber(payload.UserId) ~= USER_ID
                    or tonumber(payload.PlaceId) ~= game.PlaceId
                    or type(payload.Settings) ~= "table" then
                    return false
                end

                local saved = payload.Settings
                for _, key in ipairs(CONFIG_KEYS) do
                    local value = saved[key]
                    local current = Reconnect[key]
                    if value ~= nil and type(value) == type(current) then
                        if key == "CycleFeatures" then
                            Reconnect[key] = normalizeCycleFeatures(value)
                        else
                            Reconnect[key] = value
                        end
                    end
                end

                normalizeStoredSettings()
                return true
            end

            Runtime.PersistSettings = writeSettings

            -- File khusus menjadi sumber utama untuk Auto Reconnect.
            -- Jika belum ada, migrasikan nilai yang sudah dibaca dari ByteConfig.
            local loaded = readSettings()
            if not loaded then
                writeSettings()
            end
        end

        local storedLoaderUrl = tostring(Reconnect.LoaderUrl or "")
        Reconnect.LoaderUrl = normalizeLoaderUrl(Reconnect.LoaderUrl)
        local loaderUrlNeedsSave = storedLoaderUrl ~= Reconnect.LoaderUrl
        if loaderUrlNeedsSave then saveConfig() end

        local function savePending(world, activity, fallbackRecovery, worldPlaceId)
            world = normalizeWorld(world)
            if world == "" then return false end

            local isLobbyPlace = false
            pcall(function()
                isLobbyPlace = game:GetService("ReplicatedStorage"):FindFirstChild("MenuRemotes") ~= nil
            end)

            local payload = {
                Schema = 1,
                World = world,
                Activity = type(activity) == "table" and activity or nil,
                Settings = {
                    On = Reconnect.On == true,
                    Fallback = Reconnect.Fallback == true,
                    FallbackRecovery = fallbackRecovery == true,
                    World = Reconnect.World == true,
                    Server = Reconnect.Server == true,
                    Keep = Reconnect.Keep == true,
                    DelaySec = tonumber(Reconnect.DelaySec) or 5,
                    LoaderUrl = tostring(Reconnect.LoaderUrl or ""),
                    Target = tostring(Reconnect.Target or ""),
                    CycleOn = Reconnect.CycleOn == true,
                    CycleFeatures = normalizeCycleFeatures(Reconnect.CycleFeatures),
                    CycleIntervalMode = normalizeCycleInterval(Reconnect.CycleIntervalMode),
                    CycleCustomMinutes = math.clamp(math.floor(tonumber(Reconnect.CycleCustomMinutes) or 5), 1, 1440),
                    CycleIndex = math.max(1, math.floor(tonumber(Reconnect.CycleIndex) or 1)),
                    CycleWorld = tostring(Reconnect.CycleWorld or ""),
                    CycleTracking = Runtime.Cycle.isTracking() == true,
                    CycleActiveFeature = tostring(Runtime.Cycle.CurrentFeature or ""),
                },
                UserId = USER_ID,
                GameId = game.GameId,
                PlaceId = game.PlaceId,
                WorldPlaceId = tonumber(worldPlaceId) or (not isLobbyPlace and game.PlaceId or nil),
                CreatedAt = os.time(),
            }

            local fileSaved = false
            if type(writefile) == "function" then
                ensureFolder()
                local ok = pcall(writefile, PENDING_FILE, HttpService:JSONEncode(payload))
                fileSaved = ok
            end

            local teleportSaved = false
            local okTeleport = pcall(function()
                TeleportService:SetTeleportSetting(TELEPORT_KEY, payload)
            end)
            teleportSaved = okTeleport

            return fileSaved or teleportSaved
        end

        local function clearPending()
            if type(isfile) == "function" and type(delfile) == "function" then
                local ok, exists = pcall(isfile, PENDING_FILE)
                if ok and exists then pcall(delfile, PENDING_FILE) end
            end
            pcall(function()
                TeleportService:SetTeleportSetting(TELEPORT_KEY, false)
            end)
        end

        local function readPending()
            local payload

            if type(isfile) == "function" and type(readfile) == "function" then
                local okExists, exists = pcall(isfile, PENDING_FILE)
                if okExists and exists then
                    local okRead, raw = pcall(readfile, PENDING_FILE)
                    if okRead and type(raw) == "string" then
                        local okDecode, decoded = pcall(HttpService.JSONDecode, HttpService, raw)
                        if okDecode and type(decoded) == "table" then payload = decoded end
                    end
                end
            end

            if not payload then
                local ok, data = pcall(function()
                    return TeleportService:GetTeleportSetting(TELEPORT_KEY)
                end)
                if ok and type(data) == "table" then payload = data end
            end

            if type(payload) ~= "table"
                or payload.Schema ~= 1
                or tonumber(payload.UserId) ~= USER_ID
                or normalizeWorld(payload.World) == ""
                or os.time() - (tonumber(payload.CreatedAt) or 0) < 0
                or os.time() - (tonumber(payload.CreatedAt) or 0) > 900 then
                return nil
            end

            local curGameId = tonumber(game.GameId) or 0
            if payload.GameId ~= nil and curGameId ~= 0 then
                if tonumber(payload.GameId) ~= curGameId then return nil end
            elseif curGameId == 0 and payload.PlaceId ~= nil and tonumber(payload.PlaceId) ~= game.PlaceId then
                return nil
            end

            return payload
        end

        local function queueLoader()
            if os.clock() - (Runtime.LastQueueAt or 0) < 5 then
                return true, "debounced"
            end

            local url = normalizeLoaderUrl(Reconnect.LoaderUrl)
            Reconnect.LoaderUrl = url

            local isRemote = url:match("^https://") ~= nil
            local isLocal = url:match("^local:") ~= nil or url:match("%.luau?$") ~= nil
            if not isRemote and not isLocal then
                return false, "Loader URL harus HTTPS atau path file .lua lokal."
            end

            local queueFunction = Env.queue_on_teleport
                or Env.queueonteleport
                or (Env.syn and Env.syn.queue_on_teleport)
                or (Env.fluxus and Env.fluxus.queue_on_teleport)

            if type(queueFunction) ~= "function" then
                return false, "Executor tidak menyediakan queue_on_teleport."
            end

            local queuedSource = ([=[
                if not game:IsLoaded() then game.Loaded:Wait() end

                local loaderUrl = %q
                local source
                local lastError = "respons kosong"

                local function validLua(text)
                    if type(text) ~= "string" or text:match("^%%s*$") then
                        return false, "respons kosong"
                    end
                    if text:sub(1, 3) == "\239\187\191" then
                        text = text:sub(4)
                    end
                    if text:match("^%%s*<") then
                        return false, "Server mengirim HTML, bukan script Lua. Periksa URL Loader."
                    end
                    if text:match("^%%s*[45]%%d%%d[:%%s]") then
                        return false, text:sub(1, 120)
                    end
                    return true, text
                end

                local function tryLocalFile(path)
                    if type(path) ~= "string" or path == "" then return nil end
                    if type(isfile) == "function" and type(readfile) == "function" then
                        local okEx, exists = pcall(isfile, path)
                        if okEx and exists then
                            local okRd, content = pcall(readfile, path)
                            if okRd then
                                local valid, value = validLua(content)
                                if valid then return value end
                                lastError = value
                            end
                        end
                    end
                    return nil
                end

                if loaderUrl:match("^local:") then
                    source = tryLocalFile(loaderUrl:sub(7))
                elseif loaderUrl:match("%%.luau?$") and not loaderUrl:match("^https?://") then
                    source = tryLocalFile(loaderUrl)
                end

                if not source and loaderUrl:match("^https://") then
                    local ok, result = pcall(function()
                        return game:HttpGet(loaderUrl)
                    end)
                    if ok then
                        local valid, value = validLua(result)
                        if valid then
                            source = value
                        else
                            lastError = value
                        end
                    else
                        lastError = tostring(result)
                    end

                    if not source then
                        local env = _G
                        if type(getgenv) == "function" then
                            local envOk, envValue = pcall(getgenv)
                            if envOk and type(envValue) == "table" then env = envValue end
                        end

                        local requestApi = env.request
                            or env.http_request
                            or (env.syn and env.syn.request)
                            or (env.http and env.http.request)

                        if type(requestApi) == "function" then
                            local sent, response = pcall(requestApi, {
                                Url = loaderUrl,
                                Method = "GET",
                            })

                            if sent and type(response) == "table" then
                                local status = tonumber(response.StatusCode or response.Status)
                                local body = response.Body or response.body
                                if status and (status < 200 or status >= 300) then
                                    lastError = "HTTP " .. tostring(status)
                                else
                                    local valid, value = validLua(body)
                                    if valid then
                                        source = value
                                    else
                                        lastError = value
                                    end
                                end
                            else
                                lastError = tostring(response)
                            end
                        end
                    end
                end

                if not source then
                    for _, localPath in ipairs({ "ByteHub/local_loader.lua", "NewUI_Second_95.lua" }) do
                        source = tryLocalFile(localPath)
                        if source then break end
                    end
                end

                assert(type(source) == "string" and source ~= "",
                    "[ByteHub] Gagal mengunduh loader: " .. tostring(lastError))

                local env = _G
                if type(getgenv) == "function" then
                    local envOk, envValue = pcall(getgenv)
                    if envOk and type(envValue) == "table" then env = envValue end
                end

                local compiler = loadstring or env.loadstring
                assert(type(compiler) == "function", "[ByteHub] Executor tidak menyediakan loadstring.")

                local fn, compileError = compiler(source, "ByteHub_Loader")
                assert(type(fn) == "function",
                    "[ByteHub] Compile loader gagal: " .. tostring(compileError))

                local ran, runtimeError = xpcall(fn, function(err)
                    if debug and type(debug.traceback) == "function" then
                        return debug.traceback(tostring(err), 2)
                    end
                    return tostring(err)
                end)
                assert(ran, "[ByteHub] Runtime loader gagal: " .. tostring(runtimeError))
            ]=]):format(url)

            local ok, result = pcall(queueFunction, queuedSource)
            if not ok then return false, result end
            if result == false then return false, "Executor menolak antrean loader." end
            Runtime.LastQueueAt = os.clock()
            saveConfig()
            return true, result
        end

        Runtime.queueLoader = queueLoader
        Runtime.getLoaderUrl = function()
            return normalizeLoaderUrl(Reconnect.LoaderUrl)
        end

        local function waitForWorld(world, timeout)
            local wanted = normalizeWorld(world)
            local deadline = os.clock() + (timeout or 10)
            while active() and os.clock() < deadline do
                if normalizeWorld(Bridge.getWorld()) == wanted then return true end
                task.wait(0.25)
            end
            return false
        end

        local function waitForWorldExit(timeout)
            local deadline = os.clock() + (timeout or 6)
            while active() and os.clock() < deadline do
                if normalizeWorld(Bridge.getWorld()) == "" then return true end
                task.wait(0.25)
            end
            return normalizeWorld(Bridge.getWorld()) == ""
        end

        local function resumeSaved(world, saved, reason)
            if not waitForWorld(world, 10) then
                return false, "World belum terdeteksi setelah masuk."
            end

            if type(Bridge.afterWorldEnter) == "function" then
                pcall(Bridge.afterWorldEnter)
            end

            if hasSavedActivity(saved) and type(Bridge.resumeActivities) == "function" then
                local ok, result, detail = pcall(Bridge.resumeActivities, saved)
                if not ok then return false, tostring(result) end
                if result == false then return false, tostring(detail or "Pemulihan aktivitas gagal.") end
            end

            clearPending()
            Runtime.Count += 1
            setStatus(reason .. ": berhasil masuk ke " .. world)
            notify(reason .. ": kembali ke " .. world, 4)
            return true
        end

        local function enterAndResume(world, saved, reason)
            world = normalizeWorld(world)
            if world == "" then return false, "World tujuan kosong." end

            local inLobbyPlace = false
            pcall(function()
                inLobbyPlace = game:GetService("ReplicatedStorage"):FindFirstChild("MenuRemotes") ~= nil
            end)
            if not inLobbyPlace then
                local waitReadyEnd = os.clock() + 15
                while active() and os.clock() < waitReadyEnd do
                    local gameReady = Player and Player:GetAttribute("GameReady") == true
                    local enterReady = type(Bridge.isEnterReady) ~= "function" or Bridge.isEnterReady()
                    if gameReady and enterReady then break end
                    setStatus("Menunggu menu world siap sebelum masuk " .. world .. "...")
                    task.wait(0.4)
                end
            end

            for attempt = 1, 5 do
                if not active() then return false, "Modul dihentikan." end

                local ok, err, hopping = Bridge.enterWorld(world)
                if hopping == true then
                    savePending(world, saved, fallbackActive())
                    local queued, queueError = queueLoader()
                    setStatus("Transfer ke " .. world .. (queued and " sedang berjalan." or ". " .. tostring(queueError)))
                    return true, "hopping"
                end

                if ok then
                    local resumed, resumeError = resumeSaved(world, saved, reason)
                    if resumed then return true end
                    err = resumeError
                end

                setStatus(("Gagal masuk %s (%d/5): %s"):format(world, attempt, tostring(err)))
                task.wait(math.max(2, Reconnect.DelaySec))
            end

            notify("Gagal masuk kembali ke " .. world, 5)
            return false, "Percobaan masuk world habis."
        end

        -- Shared sequence: intentionally mirrors the Rejoin World Now button.
        -- World references can remain stale briefly after the menu opens, so a
        -- failed waitForWorldExit check must not abort the actual enterWorld call.
        local function leaveAndEnterWorld(world, saved, reason)
            world = normalizeWorld(world)
            if world == "" then return false, "World tujuan kosong." end

            if Bridge.hasActivity() then
                pcall(Bridge.stopActivities)
            end

            if normalizeWorld(Bridge.getWorld()) ~= "" then
                pcall(Bridge.leaveWorld)
                waitForWorldExit(6) -- advisory wait only, same behavior as manual rejoin
            end

            return enterAndResume(world, saved, reason)
        end

        Runtime.Cycle.ArmedStates = Runtime.Cycle.ArmedStates or {}
        Runtime.Cycle.WaitingForSingle = false

        Runtime.Cycle.flagFor = function(feature)
            if feature == "Auto PnB" then return "farm" end
            if feature == "Auto Plant" then return "plant" end
            if feature == "Auto Harvest" then return "harvest" end
            if feature == "Factory" then return "factory" end
            return nil
        end

        Runtime.Cycle.features = function()
            Reconnect.CycleFeatures = normalizeCycleFeatures(Reconnect.CycleFeatures)
            return Reconnect.CycleFeatures
        end

        Runtime.Cycle.intervalSeconds = function()
            local mode = normalizeCycleInterval(Reconnect.CycleIntervalMode)
            if mode == "Custom" then
                return math.clamp(math.floor(tonumber(Reconnect.CycleCustomMinutes) or 5), 1, 1440) * 60
            end
            local minutes = tonumber(mode:match("^(%d+)")) or 5
            return minutes * 60
        end

        Runtime.Cycle.readSnapshot = function()
            local ok, saved = pcall(Bridge.captureSnapshot)
            if not ok or type(saved) ~= "table" then return nil end
            return saved
        end

        Runtime.Cycle.activeFeatures = function(saved)
            local activeFeatures = {}
            if type(saved) ~= "table" then return activeFeatures end

            local selected = {}
            for _, feature in ipairs(Runtime.Cycle.features()) do
                selected[feature] = true
            end

            for _, feature in ipairs(CYCLE_FEATURES) do
                local flag = Runtime.Cycle.flagFor(feature)
                if selected[feature] and flag and saved[flag] == true then
                    activeFeatures[#activeFeatures + 1] = feature
                end
            end
            return activeFeatures
        end

        Runtime.Cycle.rememberStates = function(saved)
            for _, feature in ipairs(CYCLE_FEATURES) do
                local flag = Runtime.Cycle.flagFor(feature)
                Runtime.Cycle.ArmedStates[flag] =
                    type(saved) == "table" and saved[flag] == true or false
            end
        end

        Runtime.Cycle.isTracking = function()
            return Reconnect.CycleOn == true
                and Runtime.Cycle.CurrentFeature ~= nil
                and (Runtime.Cycle.NextAt > 0 or Runtime.Cycle.Transitioning)
        end

        Runtime.Cycle.status = function(message)
            if message then
                Runtime.Cycle.StatusText = tostring(message)
            elseif not Reconnect.CycleOn then
                Runtime.Cycle.StatusText = "Nonaktif"
            elseif Runtime.Cycle.Transitioning then
                Runtime.Cycle.StatusText = "Rejoin World Now · memulihkan aktivitas..."
            elseif Runtime.Cycle.WaitingForSingle then
                Runtime.Cycle.StatusText = "Aktifkan satu fitur Cycle pada satu waktu."
            elseif Runtime.Cycle.NextAt > 0 then
                local left = math.max(0, math.ceil(Runtime.Cycle.NextAt - os.clock()))
                local minutes = math.floor(left / 60)
                local seconds = left % 60
                Runtime.Cycle.StatusText = ("Menjalankan %s · rejoin dalam %02d:%02d"):format(
                    tostring(Runtime.Cycle.CurrentFeature or "-"), minutes, seconds
                )
            else
                Runtime.Cycle.StatusText = "Standby · aktifkan fitur secara manual di Auto Farm"
            end

            local control = Runtime.Controls and Runtime.Controls.CycleStatus
            if control and type(control.SetDesc) == "function" then
                pcall(control.SetDesc, control, Runtime.Cycle.StatusText)
            end
        end

        Runtime.Cycle.makeSnapshot = function(feature, base)
            if type(base) ~= "table" then
                base = Runtime.Cycle.readSnapshot()
            end
            if type(base) ~= "table" then
                return nil, "Snapshot aktivitas tidak tersedia."
            end

            local flag = Runtime.Cycle.flagFor(feature)
            if not flag or base[flag] ~= true then
                return nil, "Aktifkan " .. tostring(feature) .. " secara manual di tab Auto Farm terlebih dahulu."
            end

            local world = tostring(base.world or Bridge.getWorld() or "")
            if world == "" then return nil, "World aktif tidak ditemukan." end

            local snapshot = {
                world = world,
                plant = false,
                farm = false,
                harvest = false,
                factory = false,
                plantSeedId = base.plantSeedId,
                pnbX = tonumber(base.pnbX),
                pnbY = tonumber(base.pnbY),
                tx = tonumber(base.tx),
                ty = tonumber(base.ty),
            }

            if feature == "Auto Plant" then
                local seedId = tonumber(base.plantSeedId)
                if not seedId then
                    return nil, "Seed Auto Plant yang sedang berjalan tidak dapat dibaca."
                end
                snapshot.plant = true
                snapshot.plantSeedId = seedId
            elseif feature == "Auto PnB" then
                local x = tonumber(base.pnbX) or tonumber(base.tx)
                local y = tonumber(base.pnbY) or tonumber(base.ty)
                if x == nil or y == nil then
                    return nil, "Koordinat Auto PnB tidak tersedia. Pastikan Auto PnB sedang berjalan."
                end
                snapshot.farm = true
                snapshot.pnbX, snapshot.pnbY = x, y
                snapshot.tx, snapshot.ty = x, y
            elseif feature == "Auto Harvest" then
                snapshot.harvest = true
            elseif feature == "Factory" then
                snapshot.factory = true
            end

            return snapshot
        end

        Runtime.Cycle.isFeatureActive = function(feature)
            local flag = Runtime.Cycle.flagFor(feature)
            if not flag then return false end
            local saved = Runtime.Cycle.readSnapshot()
            return type(saved) == "table" and saved[flag] == true
        end

        Runtime.Cycle.waitFeature = function(feature, token, timeout)
            local deadline = os.clock() + (timeout or 90)
            while active() and Reconnect.CycleOn
                and token == Runtime.Cycle.Token
                and os.clock() < deadline do
                if Runtime.Cycle.isFeatureActive(feature) then return true end
                task.wait(0.5)
            end
            return false, "Fitur " .. tostring(feature) .. " belum aktif setelah rejoin."
        end

        Runtime.Cycle.setTimer = function(feature, saved, message)
            if not Reconnect.CycleOn then return false end
            Runtime.Cycle.CurrentFeature = feature
            Runtime.Cycle.CycleWorld = tostring((saved and saved.world) or Bridge.getWorld() or "")
            Reconnect.CycleWorld = Runtime.Cycle.CycleWorld
            Runtime.Cycle.Transitioning = false
            Runtime.Cycle.NextAt = os.clock() + Runtime.Cycle.intervalSeconds()
            Runtime.Cycle.WaitingForSingle = false
            Runtime.Cycle.rememberStates(saved or Runtime.Cycle.readSnapshot())
            Runtime.Cycle.status()
            if message then
                notify("Cycle Reconnect", message, 4)
            end
            return true
        end

        Runtime.Cycle.standby = function(message, saved)
            Runtime.Cycle.CurrentFeature = nil
            Runtime.Cycle.NextAt = 0
            Runtime.Cycle.Transitioning = false
            Runtime.Cycle.CycleWorld = ""
            Reconnect.CycleWorld = ""
            Runtime.Cycle.WaitingForSingle = false
            Runtime.Cycle.rememberStates(saved or Runtime.Cycle.readSnapshot())
            Runtime.Cycle.status(message or "Standby · aktifkan fitur secara manual di Auto Farm")
        end

        Runtime.Cycle.fail = function(token, message)
            if token ~= Runtime.Cycle.Token then return end

            -- Keep the master toggle ON. A failed attempt pauses Cycle in
            -- standby; it does not silently disable the user's configuration.
            Reconnect.CycleOn = true
            Reconnect.Busy = false
            Runtime.Cycle.Transitioning = false
            Runtime.Cycle.NextAt = 0
            Runtime.Cycle.CurrentFeature = nil
            Runtime.Cycle.PausedAt = nil
            Runtime.Cycle.RestartRequested = false
            Runtime.Cycle.WaitingForSingle = false
            Runtime.Cycle.rememberStates(Runtime.Cycle.readSnapshot())

            saveCycleConfig()
            Runtime.Cycle.status(
                "Gagal: " .. tostring(message)
                    .. " · Cycle tetap ON. Aktifkan ulang fitur Auto Farm untuk mencoba lagi."
            )
            notify(
                tostring(message) .. " Cycle tetap ON; aktifkan ulang fitur Auto Farm untuk mencoba lagi.",
                6
            )
        end

        -- Toggle ON hanya mengaktifkan standby. Tidak ada fitur Auto Farm
        -- yang dinyalakan atau dihentikan dari fungsi ini.
        Runtime.Cycle.start = function()
            if not active() then return false, "ByteHub belum siap." end

            local features = Runtime.Cycle.features()
            if #features == 0 then
                Reconnect.CycleOn = true
                Runtime.Cycle.Token += 1
                Runtime.Cycle.standby("Standby · pilih minimal satu fitur Cycle")
                saveCycleConfig()
                return true
            end

            Reconnect.CycleOn = true
            Runtime.Cycle.Token += 1
            Runtime.Cycle.Transitioning = false
            Runtime.Cycle.NextAt = 0
            Runtime.Cycle.CurrentFeature = nil
            Runtime.Cycle.PausedAt = nil
            Runtime.Cycle.RestartRequested = false
            Runtime.Cycle.WaitingForSingle = false
            local current = Runtime.Cycle.readSnapshot()
            Runtime.Cycle.rememberStates(current)
            if type(Bridge.saveCycleConfig) == "function" then
                pcall(Bridge.saveCycleConfig)
            else
                saveConfig()
            end
            Runtime.Cycle.status("Standby · aktifkan salah satu fitur terpilih secara manual di Auto Farm")
            return true
        end

        Runtime.Cycle.resumeAfterRecovery = function(feature, token)
            if not Reconnect.CycleOn or not feature then return false end
            token = token or Runtime.Cycle.Token
            Runtime.Cycle.CurrentFeature = feature
            Runtime.Cycle.Transitioning = true
            Runtime.Cycle.NextAt = 0
            Runtime.Cycle.status("Memulihkan " .. feature .. " setelah rejoin...")
            task.spawn(function()
                local started, startError = Runtime.Cycle.waitFeature(feature, token, 90)
                if token ~= Runtime.Cycle.Token or not Reconnect.CycleOn then return end
                if not started then
                    Runtime.Cycle.fail(token, startError)
                    return
                end
                local current = Runtime.Cycle.readSnapshot()
                Runtime.Cycle.setTimer(feature, current,
                    feature .. " aktif kembali. Timer dimulai ulang.")
            end)
            return true
        end

        Runtime.Cycle.advance = function()
            if not active() or not Reconnect.CycleOn or Runtime.Cycle.Transitioning then return end

            local current = Runtime.Cycle.readSnapshot()
            local activeFeatures = Runtime.Cycle.activeFeatures(current)
            if #activeFeatures == 0 then
                Runtime.Cycle.standby("Standby · fitur Auto Farm sudah dimatikan", current)
                return
            end
            if #activeFeatures > 1 then
                Runtime.Cycle.standby("Pilih satu fitur Cycle yang aktif pada satu waktu.", current)
                Runtime.Cycle.WaitingForSingle = true
                return
            end

            local feature = activeFeatures[1]
            local snapshot, snapshotError = Runtime.Cycle.makeSnapshot(feature, current)
            if not snapshot then
                Runtime.Cycle.standby(snapshotError, current)
                return
            end

            local world = tostring(snapshot.world or "")
            if normalizeWorld(world) == "" then
                Runtime.Cycle.fail(Runtime.Cycle.Token, "World tujuan tidak diketahui.")
                return
            end

            local token = Runtime.Cycle.Token
            Runtime.Cycle.CurrentFeature = feature
            Reconnect.CycleWorld = world
            Runtime.Cycle.Transitioning = true
            Runtime.Cycle.NextAt = 0
            Reconnect.Busy = true
            Runtime.Cycle.status("Rejoin World Now · memulihkan " .. feature .. "...")
            if type(Bridge.saveCycleConfig) == "function" then
                pcall(Bridge.saveCycleConfig)
            end

            task.spawn(function()
                -- Use the same leave -> enter path as Rejoin World Now.
                -- Do not abort merely because the cached World reference has
                -- not become empty yet; the world-selection screen may already
                -- be open while the reference is stale.
                local enterCall, entered, detail =
                    pcall(leaveAndEnterWorld, world, snapshot, "Cycle Reconnect")

                Reconnect.Busy = false
                if not enterCall then
                    entered, detail = false, tostring(entered)
                end

                if entered and detail == "hopping" then
                    Runtime.Cycle.status("Rejoin sedang berjalan. Aktivitas dipulihkan setelah loader aktif.")
                    return
                end
                if not entered then
                    Runtime.Cycle.fail(token, detail or "Gagal rejoin ke world.")
                    return
                end

                if not Reconnect.CycleOn or token ~= Runtime.Cycle.Token then
                    Runtime.Cycle.standby("Nonaktif · rejoin selesai")
                    return
                end

                Runtime.Cycle.resumeAfterRecovery(feature, token)
            end)
        end

        Runtime.Cycle.bootstrap = function(pending, pendingHopping)
            if not Reconnect.CycleOn or not active() or pendingHopping then return end

            local features = Runtime.Cycle.features()
            if #features == 0 then
                Runtime.Cycle.standby("Standby · pilih minimal satu fitur Cycle")
                saveCycleConfig()
                return
            end

            local settings = type(pending) == "table" and pending.Settings or nil
            local wasTracking = type(settings) == "table" and settings.CycleTracking == true
            local expectedFeature = type(settings) == "table" and settings.CycleActiveFeature or nil
            local pendingActivity = type(pending) == "table" and pending.Activity or nil
            local pendingActive = Runtime.Cycle.activeFeatures(pendingActivity)

            if Reconnect.CycleWorld == "" and type(pendingActivity) == "table" then
                Reconnect.CycleWorld = tostring(pendingActivity.world or "")
            end
            if Reconnect.CycleWorld == "" then
                Reconnect.CycleWorld = tostring(Bridge.getWorld() or "")
            end

            if wasTracking and type(expectedFeature) == "string"
                and table.find(pendingActive, expectedFeature) then
                Runtime.Cycle.Token += 1
                Runtime.Cycle.resumeAfterRecovery(expectedFeature, Runtime.Cycle.Token)
            else
                -- Rejoin dari Auto Reconnect biasa tidak boleh menyalakan timer
                -- Cycle jika Cycle sebelumnya masih standby.
                Runtime.Cycle.standby(
                    "Standby · aktifkan fitur secara manual di Auto Farm",
                    Runtime.Cycle.readSnapshot()
                )
            end
        end

        local function getCurrentSnapshot()
            local saved = Reconnect.Last
            if type(saved) ~= "table" and Bridge.hasActivity() then
                saved = captureSnapshot()
            end
            if type(saved) == "table" and (not saved.world or saved.world == "") then
                saved.world = Bridge.getWorld()
            end
            return saved
        end

        local function onWorldClosed(message)
            local cycleTracking = Runtime.Cycle.isTracking()
            if Bridge.Owner and Bridge.Owner.Factory and Bridge.Owner.Factory.Rotating then
                return
            end
            if not active() or not ((Reconnect.On and Reconnect.World) or cycleTracking or fallbackActive())
                or Reconnect.Busy or Reconnect.Disconnecting then
                return
            end

            local guardMode = type(Bridge.getGuardMode) == "function" and Bridge.getGuardMode() or "idle"
            if guardMode == "away" or guardMode == "out" then return end

            local saved = getCurrentSnapshot()
            local cycleFeature = cycleTracking and Runtime.Cycle.CurrentFeature or nil
            local world = (saved and saved.world) or targetWorld()
            world = normalizeWorld(world)
            if world == "" then return end

            Reconnect.Busy = true
            task.spawn(function()
                setStatus("Terlempar dari " .. world .. ". Menyiapkan reconnect...")
                if saved and Bridge.hasActivity() then
                    pcall(Bridge.stopActivities)
                end

                task.wait(math.max(1, tonumber(Reconnect.DelaySec) or 5))

                if not active() or not (Reconnect.On or (Reconnect.CycleOn and cycleFeature ~= nil) or fallbackActive()) then
                    Reconnect.Busy = false
                    Runtime.Cycle.Transitioning = false
                    return
                end

                if normalizeWorld(Bridge.getWorld()) ~= "" then
                    pcall(Bridge.leaveWorld)
                    waitForWorldExit(6)
                end

                if cycleFeature then
                    Runtime.Cycle.Transitioning = true
                    Runtime.Cycle.NextAt = 0
                end

                local entered, detail = enterAndResume(world, saved, "World recovery")
                Reconnect.Busy = false

                if cycleFeature and Reconnect.CycleOn and entered and detail ~= "hopping" then
                    Runtime.Cycle.resumeAfterRecovery(cycleFeature)
                elseif cycleFeature and Reconnect.CycleOn and entered and detail == "hopping" then
                    Runtime.Cycle.status("Rejoin sedang berjalan. Aktivitas dipulihkan setelah loader aktif.")
                else
                    Runtime.Cycle.Transitioning = false
                end
            end)
        end

        local function onServerDisconnect(message)
            if not active() or not ((Reconnect.On and Reconnect.Server) or Runtime.Cycle.isTracking() or fallbackActive())
                or Reconnect.Disconnecting then
                return
            end

            Reconnect.Disconnecting = true
            local saved = getCurrentSnapshot()
            local world = normalizeWorld((saved and saved.world) or targetWorld())

            if world ~= "" then
                savePending(world, saved, fallbackActive())
            end

            if saved and Bridge.hasActivity() then
                pcall(Bridge.stopActivities)
            end

            local queued, queueError = queueLoader()
            setStatus("Koneksi server terputus. Mencoba masuk kembali...")
            if not queued then
                notify("Reconnect loader: " .. tostring(queueError), 5)
            end

            task.spawn(function()
                task.wait(math.max(1, tonumber(Reconnect.DelaySec) or 5))
                local placeId = type(Bridge.getPlaceId) == "function" and Bridge.getPlaceId() or game.PlaceId

                local startingJobId = game.JobId
                for attempt = 1, 6 do
                    if not active() then return end
                    local ok, err = pcall(function()
                        if Player then
                            TeleportService:Teleport(placeId, Player)
                        else
                            TeleportService:Teleport(placeId)
                        end
                    end)

                    if ok then
                        setStatus(("Permintaan teleport dikirim (%d/6). Menunggu server..."):format(attempt))
                    else
                        setStatus(("Teleport gagal (%d/6): %s"):format(attempt, tostring(err)))
                    end

                    task.wait(12)
                    if not active() then return end
                    if game.JobId ~= startingJobId then return end
                end

                Reconnect.Disconnecting = false
                setStatus("Reconnect server gagal. Coba masuk ulang secara manual.")
            end)
        end

        local function bindDisconnectEvents()
            pcall(function()
                addConnection(GuiService.ErrorMessageChanged:Connect(function(message)
                    if type(message) == "string" and message ~= "" then
                        onServerDisconnect(message)
                    end
                end))
            end)

            pcall(function()
                local promptGui = CoreGui:FindFirstChild("RobloxPromptGui")
                local overlay = promptGui and promptGui:FindFirstChild("promptOverlay")
                if overlay then
                    addConnection(overlay.ChildAdded:Connect(function(child)
                        if child and child.Name == "ErrorPrompt" then
                            local message = ""
                            pcall(function() message = GuiService:GetErrorMessage() end)
                            onServerDisconnect(message ~= "" and message or "Error prompt muncul.")
                        end
                    end))
                end
            end)

            if Player then
                pcall(function()
                    addConnection(Player.OnTeleport:Connect(function(state)
                        if state == Enum.TeleportState.Started
                            or state == Enum.TeleportState.InProgress
                            or state == Enum.TeleportState.WaitingForServer then
                            if fallbackActive() or (Reconnect.On and Reconnect.Server) or Runtime.Cycle.isTracking() then
                                if not readPending() then
                                    local snap = getCurrentSnapshot()
                                    local wName = normalizeWorld((snap and snap.world) or targetWorld())
                                    if wName ~= "" then
                                        savePending(wName, snap, fallbackActive())
                                    end
                                end
                            end
                            queueLoader()
                        end
                    end))
                end)
            end

            pcall(function()
                addConnection(TeleportService.TeleportInitFailed:Connect(function(failedPlayer, teleportResult, errorMessage)
                    if failedPlayer == Player and active() and not Reconnect.Disconnecting
                        and ((Reconnect.On and Reconnect.Server) or Runtime.Cycle.isTracking() or fallbackActive()) then
                        onServerDisconnect("Teleport gagal: " .. tostring(errorMessage or teleportResult or ""))
                    end
                end))
            end)
        end

        local function reconnectNow()
            if Reconnect.Busy then
                setStatus("Proses reconnect sedang berjalan.")
                return
            end

            local world = targetWorld()
            if world == "" then
                setStatus("World tujuan belum diketahui. Masuk ke world atau isi Target World.")
                return
            end

            local saved = getCurrentSnapshot()
            if saved and normalizeWorld(saved.world) ~= world then saved = nil end

            Reconnect.Busy = true
            task.spawn(function()
                leaveAndEnterWorld(world, saved, "Manual reconnect")
                Reconnect.Busy = false
            end)
        end

        local function buildUI()
            local tab = Bridge.Tab
            tab:Section({ Title = "WORLD RECOVERY" })

            Runtime.Controls = Runtime.Controls or {}
            Runtime.Controls.Master = tab:Toggle({
                Title = "Auto Reconnect",
                Desc = "Aktifkan pemulihan otomatis setelah keluar dari world atau server.",
                Value = Reconnect.On,
                Callback = function(value)
                    Reconnect.On = value == true
                    if not Reconnect.On then
                        Reconnect.Busy = false
                        Reconnect.Disconnecting = false
                        clearPending()
                    end
                    saveConfig()
                    setStatus(Reconnect.On and "Aktif" or "Nonaktif")
                end,
            })

            Runtime.Controls.Fallback = tab:Toggle({
                Title = "Auto Reconnect Fallback",
                Desc = "Otomatis rejoin world & lanjutkan Factory/aktivitas saat ke-kick dari world atau server.",
                Value = Reconnect.Fallback == true,
                Callback = function(value)
                    Reconnect.Fallback = value == true
                    saveConfig()
                    setStatus(Reconnect.Fallback and "Fallback aktif" or "Fallback nonaktif")
                end,
            })

            Runtime.Controls.World = tab:Toggle({
                Title = "Kicked from world",
                Desc = "Masuk kembali ke world yang sama setelah world ditutup.",
                Value = Reconnect.World,
                Callback = function(value)
                    Reconnect.World = value == true
                    saveConfig()
                end,
            })

            Runtime.Controls.Server = tab:Toggle({
                Title = "Disconnected from server",
                Desc = "Mencoba masuk kembali ke game setelah koneksi server terputus.",
                Value = Reconnect.Server,
                Callback = function(value)
                    Reconnect.Server = value == true
                    saveConfig()
                end,
            })

            Runtime.Controls.Keep = tab:Toggle({
                Title = "Always return to world",
                Desc = "Kembali otomatis jika berada di menu pemilihan world.",
                Value = Reconnect.Keep,
                Callback = function(value)
                    Reconnect.Keep = value == true
                    saveConfig()
                end,
            })

            Runtime.Controls.Target = tab:Input({
                Title = "Target World",
                Placeholder = "Kosongkan untuk world terakhir",
                Value = Reconnect.Target,
                Live = true,
                Callback = function(value)
                    Reconnect.Target = tostring(value or "")
                    saveConfig()
                end,
            })

            Runtime.Controls.Delay = tab:Slider({
                Title = "Reconnect Delay (seconds)",
                Value = { Min = 2, Max = 60, Default = math.clamp(tonumber(Reconnect.DelaySec) or 5, 2, 60) },
                Step = 1,
                Callback = function(value)
                    Reconnect.DelaySec = math.clamp(math.floor(tonumber(value) or 5), 2, 60)
                    saveConfig()
                end,
            })

            Runtime.Controls.LoaderUrl = tab:Input({
                Title = "Loader URL",
                Placeholder = "GitHub file URL atau Raw Lua URL",
                Value = Reconnect.LoaderUrl,
                Live = true,
                Callback = function(value)
                    Reconnect.LoaderUrl = normalizeLoaderUrl(value)
                    saveConfig()
                end,
            })

            tab:Section({ Title = "CYCLE RECONNECT" })

            Runtime.Controls.CycleFeatures = tab:Dropdown({
                Title = "Cycle Features",
                Desc = "Pilih fitur yang boleh dipulihkan. Aktifkan fiturnya secara manual di tab Auto Farm.",
                Values = CYCLE_FEATURES,
                Value = Reconnect.CycleFeatures,
                MultiSelect = true,
                Callback = function(values)
                    Reconnect.CycleFeatures = normalizeCycleFeatures(values)
                    Reconnect.CycleIndex = 1

                    if #Reconnect.CycleFeatures == 0 and Reconnect.CycleOn then
                        Runtime.Cycle.Token += 1
                        Runtime.Cycle.NextAt = 0
                        Runtime.Cycle.CurrentFeature = nil
                        Runtime.Cycle.Transitioning = false
                        Runtime.Cycle.RestartRequested = false
                        Runtime.Cycle.standby("Standby · pilih minimal satu fitur Cycle")
                    elseif Reconnect.CycleOn then
                        Runtime.Cycle.standby(
                            "Pilihan diperbarui · aktifkan fitur secara manual di Auto Farm",
                            Runtime.Cycle.readSnapshot()
                        )
                    end
                    saveCycleConfig()
                end,
            })

            Runtime.Controls.CycleInterval = tab:Dropdown({
                Title = "Cycle Interval",
                Desc = "Waktu aktif fitur yang dipilih sebelum Rejoin World Now.",
                Values = CYCLE_INTERVALS,
                Value = Reconnect.CycleIntervalMode,
                Callback = function(value)
                    if type(value) == "table" then value = value[1] end
                    Reconnect.CycleIntervalMode = normalizeCycleInterval(value)
                    if Reconnect.CycleOn and Runtime.Cycle.NextAt > 0 then
                        Runtime.Cycle.NextAt = os.clock() + Runtime.Cycle.intervalSeconds()
                    end
                    saveCycleConfig()
                    Runtime.Cycle.status()
                end,
            })

            Runtime.Controls.CycleCustomMinutes = tab:Input({
                Title = "Custom Minutes",
                Placeholder = "Contoh: 45",
                Value = tostring(Reconnect.CycleCustomMinutes),
                Live = false,
                Callback = function(value)
                    local parsed = tonumber(value)
                    if not parsed or parsed < 1 then
                        notify("Cycle Reconnect", "Custom Minutes harus berupa angka minimal 1.", 4)
                        if Runtime.Controls.CycleCustomMinutes then
                            Runtime.Controls.CycleCustomMinutes:Set(tostring(Reconnect.CycleCustomMinutes))
                        end
                        return
                    end
                    Reconnect.CycleCustomMinutes = math.clamp(math.floor(parsed), 1, 1440)
                    if Runtime.Cycle.NextAt > 0 and Reconnect.CycleOn
                        and Reconnect.CycleIntervalMode == "Custom" then
                        Runtime.Cycle.NextAt = os.clock() + Runtime.Cycle.intervalSeconds()
                    end
                    saveCycleConfig()
                    Runtime.Cycle.status()
                end,
            })

            Runtime.Controls.CycleMaster = tab:Toggle({
                Title = "Cycle Reconnect",
                Desc = "Standby sampai Anda mengaktifkan fitur terpilih secara manual di tab Auto Farm.",
                Value = Reconnect.CycleOn,
                Callback = function(value)
                    if value == true then
                        local ok, err = Runtime.Cycle.start()
                        if not ok then
                            Reconnect.CycleOn = false
                            if Runtime.Controls.CycleMaster then
                                pcall(function() Runtime.Controls.CycleMaster:Set(false) end)
                            end
                            saveCycleConfig()
                            Runtime.Cycle.status("Tidak aktif")
                            notify("Cycle Reconnect", err or "Tidak dapat mengaktifkan standby.", 5)
                        end
                    else
                        Reconnect.CycleOn = false
                        Runtime.Cycle.Token += 1
                        Runtime.Cycle.NextAt = 0
                        Runtime.Cycle.CurrentFeature = nil
                        Runtime.Cycle.RestartRequested = false
                        Runtime.Cycle.PausedAt = nil
                        Runtime.Cycle.WaitingForSingle = false
                        if not Reconnect.Busy then Runtime.Cycle.Transitioning = false end
                        Runtime.Cycle.standby("Nonaktif · aktivitas Auto Farm tidak diubah")
                        saveCycleConfig()
                    end
                end,
            })

            Runtime.Controls.CycleStatus = tab:Paragraph({
                Title = "Cycle Status",
                Desc = Runtime.Cycle.StatusText,
            })

            tab:Button({
                Title = "Rejoin World Now",
                Desc = "Keluar dan masuk kembali ke world tujuan.",
                ButtonText = "Rejoin",
                Callback = reconnectNow,
            })

            tab:Button({
                Title = "Kick Diri Sendiri",
                Desc = "Kick penuh dari server Roblox (ErrorPrompt) untuk menguji Auto Reconnect Fallback.",
                ButtonText = "Kick",
                Callback = function()
                    local lp = Player or game:GetService("Players").LocalPlayer
                    if lp and type(lp.Kick) == "function" then
                        pcall(function()
                            lp:Kick("Self kick (ByteHub)")
                        end)
                    end
                end,
            })

            tab:Section({ Title = "INFORMATION" })
            if Bridge.StatusLabel and type(Bridge.StatusLabel.Set) == "function" then
                setStatus("Siap. Auto Reconnect nonaktif.")
            end
        end

        buildUI()
        bindDisconnectEvents()

        task.spawn(function()
            local attempts = 0
            while active() and not Runtime.WorldListenerActive and attempts < 30 do
                attempts += 1
                local connected, connectionOrError = false, nil

                if type(Bridge.connectWorldClosed) == "function" then
                    local ok, result, detail = pcall(Bridge.connectWorldClosed, onWorldClosed)
                    if ok then
                        connected, connectionOrError = result, detail
                    else
                        connectionOrError = result
                    end
                end

                if connected then
                    Runtime.WorldListenerActive = true
                    if type(connectionOrError) == "table"
                        and type(connectionOrError.Disconnect) == "function" then
                        addConnection(connectionOrError)
                    end
                    setStatus("Siap. Listener world aktif.")
                    return
                end

                setStatus("Menunggu referensi WorldClosed: " .. tostring(connectionOrError))
                task.wait(2)
            end

            if active() and not Runtime.WorldListenerActive then
                setStatus("Listener WorldClosed tidak ditemukan. Reconnect server tetap tersedia.")
            end
        end)

        function Runtime.Shutdown()
            if not Runtime.Active then return end
            -- Flush current Auto Reconnect settings before UI/session teardown.
            pcall(saveConfig)
            Runtime.Active = false
            for _, connection in ipairs(Runtime.Connections) do
                pcall(function() connection:Disconnect() end)
            end
            table.clear(Runtime.Connections)
            Reconnect.On = false
            Reconnect.Busy = false
            Reconnect.Disconnecting = false
            if Env.__ByteHubAutoReconnect == Runtime then
                Env.__ByteHubAutoReconnect = nil
            end
        end

        local function hasActiveFactoryRotationPending()
            local payload
            local rotFile = FOLDER .. "/factory_rotation_" .. tostring(USER_ID) .. ".json"
            if type(isfile) == "function" and type(readfile) == "function" then
                local okEx, exists = pcall(isfile, rotFile)
                if okEx and exists then
                    local okRd, raw = pcall(readfile, rotFile)
                    if okRd and type(raw) == "string" then
                        local okDec, dec = pcall(HttpService.JSONDecode, HttpService, raw)
                        if okDec and type(dec) == "table" then payload = dec end
                    end
                end
            end
            if not payload then
                local okT, data = pcall(function()
                    return TeleportService:GetTeleportSetting("ByteHub.FactoryRotation.v1")
                end)
                if okT and type(data) == "table" then payload = data end
            end
            if type(payload) ~= "table"
                or payload.Schema ~= 1
                or tonumber(payload.UserId) ~= USER_ID
                or normalizeWorld(payload.TargetWorld) == ""
                or os.time() - (tonumber(payload.CreatedAt) or 0) < 0
                or os.time() - (tonumber(payload.CreatedAt) or 0) > 900 then
                return false
            end
            local curGameId = tonumber(game.GameId) or 0
            if payload.GameId ~= nil and curGameId ~= 0 then
                if tonumber(payload.GameId) ~= curGameId then return false end
            elseif curGameId == 0 and payload.PlaceId ~= nil and tonumber(payload.PlaceId) ~= game.PlaceId then
                return false
            end
            return true
        end

        task.spawn(function()
            local pending = readPending()
            if hasActiveFactoryRotationPending() then
                if pending then clearPending() end
                pending = nil
            end

            if pending and type(pending.Settings) == "table" then
                local settings = pending.Settings
                if settings.On ~= nil then Reconnect.On = settings.On == true end
                if settings.Fallback ~= nil then Reconnect.Fallback = settings.Fallback == true end
                if settings.World ~= nil then Reconnect.World = settings.World == true end
                if settings.Server ~= nil then Reconnect.Server = settings.Server == true end
                if settings.Keep ~= nil then Reconnect.Keep = settings.Keep == true end
                if tonumber(settings.DelaySec) then
                    Reconnect.DelaySec = math.clamp(math.floor(tonumber(settings.DelaySec)), 2, 60)
                end
                if type(settings.LoaderUrl) == "string" and settings.LoaderUrl ~= "" then
                    Reconnect.LoaderUrl = normalizeLoaderUrl(settings.LoaderUrl)
                end
                if type(settings.Target) == "string" then Reconnect.Target = settings.Target end
                if settings.CycleOn ~= nil then Reconnect.CycleOn = settings.CycleOn == true end
                if type(settings.CycleFeatures) == "table" then
                    Reconnect.CycleFeatures = normalizeCycleFeatures(settings.CycleFeatures)
                end
                if type(settings.CycleIntervalMode) == "string" then
                    Reconnect.CycleIntervalMode = normalizeCycleInterval(settings.CycleIntervalMode)
                end
                if tonumber(settings.CycleCustomMinutes) then
                    Reconnect.CycleCustomMinutes = math.clamp(math.floor(tonumber(settings.CycleCustomMinutes)), 1, 1440)
                end
                if tonumber(settings.CycleIndex) then
                    Reconnect.CycleIndex = math.max(1, math.floor(tonumber(settings.CycleIndex)))
                end
                if type(settings.CycleWorld) == "string" then
                    Reconnect.CycleWorld = settings.CycleWorld
                end

                local controls = Runtime.Controls or {}
                if controls.Master and controls.Master.Set then controls.Master:Set(Reconnect.On) end
                if controls.Fallback and controls.Fallback.Set then controls.Fallback:Set(Reconnect.Fallback == true) end
                if controls.World and controls.World.Set then controls.World:Set(Reconnect.World) end
                if controls.Server and controls.Server.Set then controls.Server:Set(Reconnect.Server) end
                if controls.Keep and controls.Keep.Set then controls.Keep:Set(Reconnect.Keep) end
                if controls.Delay and controls.Delay.Set then controls.Delay:Set(Reconnect.DelaySec) end
                if controls.LoaderUrl and controls.LoaderUrl.Set then controls.LoaderUrl:Set(Reconnect.LoaderUrl) end
                if controls.Target and controls.Target.Set then controls.Target:Set(Reconnect.Target) end
                if controls.CycleMaster and controls.CycleMaster.Set then controls.CycleMaster:Set(Reconnect.CycleOn) end
                if controls.CycleFeatures and controls.CycleFeatures.Set then controls.CycleFeatures:Set(Reconnect.CycleFeatures) end
                if controls.CycleInterval and controls.CycleInterval.Set then controls.CycleInterval:Set(Reconnect.CycleIntervalMode) end
                if controls.CycleCustomMinutes and controls.CycleCustomMinutes.Set then
                    controls.CycleCustomMinutes:Set(tostring(Reconnect.CycleCustomMinutes))
                end
                saveConfig()
            end

            local initialWorld = normalizeWorld(Bridge.getWorld())
            if initialWorld ~= "" then
                Reconnect.LastWorld = initialWorld
            end
            if pending then
                local pWorld = normalizeWorld(pending.World)
                if pWorld ~= "" then
                    Reconnect.LastWorld = pWorld
                    Reconnect.Last = pending.Activity
                    Reconnect.LastAt = os.clock()
                end
            end

            local pendingHopping = false
            local fallbackPending = pending and type(pending.Settings) == "table" and pending.Settings.FallbackRecovery == true
            if pending and (Reconnect.On or Reconnect.CycleOn or Reconnect.Fallback or fallbackPending) and active() then
                Reconnect.Busy = true
                local world = normalizeWorld(pending.World)
                local saved = pending.Activity

                setStatus("Menyiapkan pemulihan ke " .. world .. "...")
                local current = normalizeWorld(Bridge.getWorld())
                local inLobbyPlace = false
                pcall(function()
                    inLobbyPlace = game:GetService("ReplicatedStorage"):FindFirstChild("MenuRemotes") ~= nil
                end)

                if current == world then
                    resumeSaved(world, saved, fallbackPending and "Fallback recovery" or "Server recovery")
                elseif inLobbyPlace then
                    local targetPid = tonumber(pending.WorldPlaceId or pending.PlaceId)
                    savePending(world, saved, fallbackPending or fallbackActive(), targetPid)
                    queueLoader()
                    setStatus("Di Lobby: masuk kembali ke server world untuk " .. world .. "...")
                    local hopped = false
                    pcall(function()
                        local pg = Player and Player:FindFirstChildOfClass("PlayerGui")
                        if pg then
                            for _, obj in ipairs(pg:GetDescendants()) do
                                if obj:IsA("TextButton") and obj.Visible then
                                    local txt = tostring(obj.Text or ""):lower()
                                    if txt == "play" or txt == "start" or txt == "masuk" then
                                        if type(firesignal) == "function" then
                                            pcall(firesignal, obj.MouseButton1Click)
                                            pcall(firesignal, obj.Activated)
                                            hopped = true
                                            break
                                        elseif type(getconnections) == "function" then
                                            for _, conn in ipairs(getconnections(obj.MouseButton1Click)) do
                                                pcall(function() conn:Fire() end)
                                                hopped = true
                                            end
                                            for _, conn in ipairs(getconnections(obj.Activated)) do
                                                pcall(function() conn:Fire() end)
                                                hopped = true
                                            end
                                            if hopped then break end
                                        end
                                    end
                                end
                            end
                        end
                    end)
                    if not hopped and targetPid and targetPid ~= game.PlaceId then
                        pcall(function()
                            if Player then
                                TeleportService:Teleport(targetPid, Player)
                            else
                                TeleportService:Teleport(targetPid)
                            end
                        end)
                    end
                    pendingHopping = true
                else
                    local entered, detail = enterAndResume(world, saved, fallbackPending and "Fallback recovery" or "Server recovery")
                    pendingHopping = entered == true and detail == "hopping"
                end

                Reconnect.Busy = false
            elseif pending and not Reconnect.On and not Reconnect.CycleOn and not Reconnect.Fallback and not fallbackPending then
                clearPending()
            end

            if Reconnect.CycleOn and active() and not pendingHopping then
                Runtime.Cycle.bootstrap(pending, false)
            end

            local outsideSince = nil
            while active() do
                task.wait(1)

                local currentWorld = normalizeWorld(Bridge.getWorld())
                if currentWorld ~= "" then
                    Reconnect.LastWorld = currentWorld
                end

                if Bridge.hasActivity() then
                    local snapshot = captureSnapshot()
                    if snapshot then
                        Reconnect.Last = snapshot
                        Reconnect.LastAt = os.clock()
                    end
                elseif Reconnect.LastAt > 0 and os.clock() - Reconnect.LastAt > (currentWorld == "" and 30 or 3) then
                    Reconnect.Last = nil
                    Reconnect.LastAt = 0
                end

                local rotatingFactory = Bridge.Owner and Bridge.Owner.Factory and Bridge.Owner.Factory.Rotating == true
                local isLobbyNow = false
                pcall(function()
                    isLobbyNow = game:GetService("ReplicatedStorage"):FindFirstChild("MenuRemotes") ~= nil
                end)
                local guardModeLoop = type(Bridge.getGuardMode) == "function" and Bridge.getGuardMode() or "idle"
                local allowSilentReturn = (Reconnect.On and Reconnect.Keep) or (fallbackActive() and Reconnect.LastWorld ~= "")
                if not rotatingFactory and not isLobbyNow and allowSilentReturn and not Reconnect.Busy
                    and not Reconnect.Disconnecting and currentWorld == ""
                    and guardModeLoop ~= "away" and guardModeLoop ~= "out" then
                    outsideSince = outsideSince or os.clock()
                    local world = targetWorld()
                    local waitSec = (Reconnect.On and Reconnect.Keep) and math.max(8, Reconnect.DelaySec)
                        or math.max(4, Reconnect.DelaySec)
                    local reasonText = (Reconnect.On and Reconnect.Keep) and "Auto return" or "Fallback rejoin"
                    if world ~= "" and os.clock() - outsideSince >= waitSec then
                        outsideSince = nil
                        Reconnect.Busy = true
                        enterAndResume(world, Reconnect.Last, reasonText)
                        Reconnect.Busy = false
                    end
                else
                    outsideSince = nil
                end

                if Reconnect.CycleOn and not Runtime.Cycle.Transitioning and not rotatingFactory then
                    local guardMode = type(Bridge.getGuardMode) == "function" and Bridge.getGuardMode() or "idle"
                    local guardPaused = guardMode == "away" or guardMode == "out"
                        or guardMode == "pause" or guardMode == "back"

                    if guardPaused then
                        Runtime.Cycle.PausedAt = Runtime.Cycle.PausedAt or os.clock()
                    elseif Runtime.Cycle.PausedAt then
                        if Runtime.Cycle.NextAt > 0 then
                            Runtime.Cycle.NextAt += os.clock() - Runtime.Cycle.PausedAt
                        end
                        Runtime.Cycle.PausedAt = nil
                    end

                    if not guardPaused then
                        local cycleSnapshot = Runtime.Cycle.readSnapshot()
                        local activeFeatures = Runtime.Cycle.activeFeatures(cycleSnapshot)

                        if #activeFeatures == 0 then
                            if Runtime.Cycle.NextAt > 0 or Runtime.Cycle.CurrentFeature ~= nil then
                                Runtime.Cycle.standby(
                                    "Standby · aktifkan fitur secara manual di Auto Farm",
                                    cycleSnapshot
                                )
                            else
                                Runtime.Cycle.rememberStates(cycleSnapshot)
                                Runtime.Cycle.status()
                            end
                        elseif #activeFeatures > 1 then
                            Runtime.Cycle.standby(
                                "Aktifkan satu fitur Cycle pada satu waktu.",
                                cycleSnapshot
                            )
                            Runtime.Cycle.WaitingForSingle = true
                        else
                            local feature = activeFeatures[1]
                            local flag = Runtime.Cycle.flagFor(feature)
                            local wasActive = Runtime.Cycle.ArmedStates[flag] == true

                            if Runtime.Cycle.NextAt <= 0 then
                                if not wasActive or Runtime.Cycle.WaitingForSingle then
                                    Runtime.Cycle.CurrentFeature = feature
                                    Runtime.Cycle.CycleWorld = tostring(cycleSnapshot.world or currentWorld or "")
                                    Reconnect.CycleWorld = Runtime.Cycle.CycleWorld
                                    Runtime.Cycle.NextAt = os.clock() + Runtime.Cycle.intervalSeconds()
                                    Runtime.Cycle.WaitingForSingle = false
                                    Runtime.Cycle.status()
                                else
                                    Runtime.Cycle.status(
                                        "Standby · matikan lalu aktifkan kembali fitur terpilih di Auto Farm"
                                    )
                                end
                            elseif feature ~= Runtime.Cycle.CurrentFeature then
                                -- User manually switched to another selected feature.
                                Runtime.Cycle.CurrentFeature = feature
                                Runtime.Cycle.CycleWorld = tostring(cycleSnapshot.world or currentWorld or "")
                                Reconnect.CycleWorld = Runtime.Cycle.CycleWorld
                                Runtime.Cycle.NextAt = os.clock() + Runtime.Cycle.intervalSeconds()
                                Runtime.Cycle.status()
                            elseif os.clock() >= Runtime.Cycle.NextAt and not Reconnect.Busy then
                                Runtime.Cycle.rememberStates(cycleSnapshot)
                                Runtime.Cycle.advance()
                            end

                            Runtime.Cycle.rememberStates(cycleSnapshot)
                        end
                    end
                    Runtime.Cycle.status()
                end

                if Bridge.StatusLabel and Reconnect.Status then
                    setStatus(Reconnect.Status)
                end
            end
        end)

        print("[ByteHub] Auto Reconnect module siap.")
        return Runtime
    end

    local ok, err = pcall(startByteHubAutoReconnect)
    if not ok then
        warn("[ByteHub] Auto Reconnect gagal diinisialisasi: " .. tostring(err))
        pcall(function()
            pAutoReconnectStatus:Set("Auto Reconnect gagal dimuat: " .. tostring(err))
        end)
    end
end)()


task.delay(0.6, function()
	if not gui.Parent then return end
	notify("BYTEHUB v2", "Tekan " .. State.toggleKey.Name .. " untuk buka/tutup", 4, true)
end)
